INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C1','kor',4,2,'u3',2,'이 단원에서 배울 두 가지 — 토의로 문제의 해결 방법을 찾기 · 그 방법을 의견과 이유가 드러나게 제안하는 글로 알리기',ARRAY['[4국01-06][4국03-03]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C2','kor',4,2,'u3',2,'토의 — 혼자서는 풀기 어려운 문제를 여럿이 의견을 모아 해결 방법을 찾는 것(교실 앞문 문턱)',ARRAY['[4국01-06]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C3','kor',4,2,'u3',2,'토의에 알맞은 일 — 여러 의견이 나올 수 있고 모두와 관련 있는 일 — 답이 하나로 정해진 일이나 나 혼자만의 일은 토의할 까닭이 없음',ARRAY['[4국01-06]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C4','kor',4,2,'u3',2,'토의할 때 바른 태도 — 손을 들고 내 차례에 말하기 · 나와 다른 의견도 끝까지 듣기 — 끼어들거나 목소리 큰 친구의 의견을 그대로 따르지 않음',ARRAY['[4국01-06]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C5','kor',4,2,'u3',2,'제안과 제안하는 글 — 제안은 어떤 일에 대해 의견을 내놓는 것 — 제안하는 내용을 담아 쓴 글이 제안하는 글',ARRAY['[4국01-06][4국03-03]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C6','kor',4,2,'u3',2,'토의와 제안하는 글의 관계 — 둘 다 문제를 해결하는 방법 — 토의로 정한 것을 글로 제안할 수도 있고, 상황에 따라 알맞은 방법을 고름(언제나 글부터도, 글은 필요 없음도 아님)',ARRAY['[4국01-06][4국03-03]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C7','kor',4,2,'u3',2,'글쓴이의 의견 찾기 — 「……하면 어떨까요?」처럼 바라는 것을 내놓는 문장에서 의견을 찾음 — 문제 상황이나 좋아지는 점과 구별',ARRAY['[4국01-06][4국03-03]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C8','kor',4,2,'u3',2,'토의 절차 — 주제 정하기(풀 문제 고르기) → 의견 마련하기(의견과 이유 준비) → 의견 모으기(묻고 따지기) → 의견 결정하기(기준으로 정하기)',ARRAY['[4국01-06]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C9','kor',4,2,'u3',2,'주제를 정할 때 — 여러 문제 가운데 어느 것이 더 급한지 까닭을 들어 이야기한 뒤 정함',ARRAY['[4국01-06]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C10','kor',4,2,'u3',2,'토의할 때 주의할 점 — 우리가 해결할 수 있는 주제인지 살핌 · 내 의견의 단점도 생각 · 끝까지 듣고 알맞은지 따짐 · 기준을 세워 견주어 정함 · 말할 기회를 고르게 · 주제에서 벗어나지 않게',ARRAY['[4국01-06]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C11','kor',4,2,'u3',2,'질문하면 좋은 점 — 친구의 생각을 더 정확히 알고, 의견이 주제에 알맞은지 함께 따지고, 답을 생각하는 사이에 의견이 더 나아짐(테이프로 덮기)',ARRAY['[4국01-06]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C12','kor',4,2,'u3',2,'상대의 기분을 헤아린 질문 — 의견의 좋은 점을 먼저 인정하고 궁금한 점을 구체적으로 물음 — 내가 그 친구라면 기꺼이 답하고 싶은 질문',ARRAY['[4국01-06]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C13','kor',4,2,'u3',2,'말투와 내용 둘 다 — 공손한 말투는 필요하지만 질문은 의견이 문제를 해결하는지 따지는 데 도움이 되어야 함(스티커 색 ✗) — 질문 수를 채우는 것도 목적이 아님',ARRAY['[4국01-06]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C14','kor',4,2,'u3',2,'더 나은 의견을 만드는 질문 갈래 — 결과(무엇이 달라질까요?) · 어려움(곤란한 점은 없을까요?) · 실천 방법(언제, 누가, 어떻게?)',ARRAY['[4국01-06]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C15','kor',4,2,'u3',4,'모둠 토의 주제 고르기 — 우리 모두와 관련 있고, 여러 의견이 나올 수 있고, 우리가 해결에 나설 수 있는 문제(현관 바닥 · 음수대 줄)',ARRAY['[4국01-06]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C16','kor',4,2,'u3',4,'문제가 생긴 까닭과 영향 — 까닭은 「왜 그런가」(젖은 우산과 신발의 물이 고임), 영향은 그 때문에 생기는 일(미끄러져 다칠 수 있음·현관이 붐빔)',ARRAY['[4국01-06]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C17','kor',4,2,'u3',4,'의견을 마련할 때 스스로 묻기 — 문제 해결에 도움이 되는가 · 우리가 실천할 수 있는가 · 이유가 알맞은가 · 단점도 생각했는가',ARRAY['[4국01-06]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C18','kor',4,2,'u3',4,'쉬운 의견과 알맞은 의견 — 쉽게 할 수 있어도 문제를 해결하지 못하면 알맞은 의견이 아님(솔비) — 쉬운지와 해결되는지를 함께 따지고, 쉬운 의견을 모두 버리는 것도 아님',ARRAY['[4국01-06]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C19','kor',4,2,'u3',4,'모둠 친구 의견에 할 질문 — 실천 방법이나 어려움을 존중하는 말로 물음 — 의견과 상관없는 것을 묻거나 깎아내리지 않음',ARRAY['[4국01-06]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C20','kor',4,2,'u3',4,'질문에 답하며 자라는 의견 — 질문에 답하면서 의견이 더 구체적으로 다듬어짐(두 사람씩 요일 · 발판 두 장) — 의견을 고쳐도 지는 것이 아님',ARRAY['[4국01-06]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C21','kor',4,2,'u3',4,'의견을 결정하는 방법 — 해결에 도움이 되는지, 실천할 수 있는지 기준에 비추어 견줌 — 합치든 하나를 고르든 같은 기준으로 따짐(넷을 모두 합치면 언제나 좋다 ✗)',ARRAY['[4국01-06]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C22','kor',4,2,'u3',4,'우리 힘으로 못 하는 일 — 발판처럼 우리 힘만으로 할 수 없는 일은 바꿀 수 있는 곳에 제안하기로 함 — 제안하는 글로 이어짐',ARRAY['[4국01-06]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C23','kor',4,2,'u3',4,'구체적인 실천 계획 — 언제 · 누가 · 무엇을 할지 분명하게(비 오는 날 등교 시간에 두 사람씩 요일을 나누어) — 「열심히 노력한다」는 계획이 아님',ARRAY['[4국01-06]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C24','kor',4,2,'u3',4,'토의 참여 점검 — 주제에 알맞은 의견과 이유 · 궁금한 점이나 어려움 묻기 · 끝까지 듣기 · 결정이 내 의견과 달라도 함께 실천',ARRAY['[4국01-06]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C25','kor',4,2,'u3',6,'누구에게 제안할까 — 그 일을 정하거나 바꿀 수 있는 사람에게 제안함(교실을 어떻게 쓸지 정하는 방과 후 담당 선생님)',ARRAY['[4국03-03]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C26','kor',4,2,'u3',6,'문제 상황 찾기 — 누가 어디에서 어떤 불편을 겪는지 찾음(기다릴 곳이 없어 복도 바닥에 앉아 있고 부딪치기도 함)',ARRAY['[4국03-03]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C27','kor',4,2,'u3',6,'제안하는 글의 짜임 — 문제 상황(무엇이 불편한가) · 제안하는 내용(무엇을 바라는가) · 제안하는 이유(그러면 무엇이 좋은가)',ARRAY['[4국03-03]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C28','kor',4,2,'u3',6,'막기만 하는 말과 제안 — 「복도에 앉지 마세요」처럼 「~하세요」로 끝나도 막기만 하고 해결 방법과 이유가 없으면 제안하는 글로는 부족함',ARRAY['[4국03-03]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C29','kor',4,2,'u3',6,'쓰기 전에 생각할 내용 — 제안하는 내용이 드러나는 제목 · 누구에게 쓸지 · 문제 상황을 보여 줄 그림이나 사진 · 글을 어떻게 전할지',ARRAY['[4국03-03]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C30','kor',4,2,'u3',6,'제안하는 글을 쓰면 좋은 점 — 문제와 해결 방법이 또렷하게 정리됨 · 만나기 어려운 분께도 차분히 전함 · 읽은 사람도 관심을 두고 함께 나섬 — 언제나 받아들여지는 것도, 불만을 쏟는 글도 아님',ARRAY['[4국03-03]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C31','kor',4,2,'u3',6,'상황에 맞는 방법 고르기 — 짝이 지우개를 말없이 가져다 쓰는 것처럼 두 사람 사이의 일은 직접 차분히 말하는 것이 알맞음 — 제안하는 글은 여러 방법 가운데 하나',ARRAY['[4국03-03]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C32','kor',4,2,'u3',7,'제안하는 글을 쓰는 과정 — 문제 상황 파악하기 → 누구에게 제안할지 생각하기 → 제안하는 내용을 정하고 이유 설명하기 → 제안하는 글 쓰기',ARRAY['[4국03-03]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C33','kor',4,2,'u3',7,'앞 단계로 되돌아가기 — 쓰다가 이유가 약한 것을 알면 앞 단계로 돌아가 다시 생각해도 됨 — 차례는 길잡이',ARRAY['[4국03-03]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C34','kor',4,2,'u3',7,'제안할 대상 정하기 — 안내판을 달고 고치는 일을 정할 수 있는 시청 담당자처럼, 제안을 받아 실제로 바꿀 수 있는 곳 — 대상을 분명히 하면 제안이 구체적이 됨',ARRAY['[4국03-03]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C35','kor',4,2,'u3',7,'알맞은 제안 내용 — 문제를 바로 해결하면서 실제로 할 수 있는 제안(눈높이 안내판 · 큰 글자) — 해결은 되지만 실천이 어렵거나(하루 종일 안내하는 사람) 문제에서 멀어진 제안(버스 없애기)은 알맞지 않음',ARRAY['[4국03-03]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C36','kor',4,2,'u3',7,'알맞은 이유 — 제안대로 하면 여러 사람에게 무엇이 좋아지는지 보여 주는 이유 — 「왜냐하면」을 썼다고 알맞은 것도, 내 불편만 말하는 것도 아님',ARRAY['[4국03-03]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C37','kor',4,2,'u3',7,'문제 상황과 제목 — 문제 상황은 겪은 일로 구체적으로 쓰고, 제목은 무엇을 제안하는지 드러나게 붙임(다 쓰고 나서 붙여도 됨)',ARRAY['[4국03-03]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C38','kor',4,2,'u3',7,'제안과 이유의 표현 — 제안 — 「……면 좋겠습니다」 「……면 어떨까요?」 「……합시다」 · 이유 — 「왜냐하면 ……때문입니다」 「……면 ……할 수 있습니다」 — 외우지 않고 문장에 어울리는 것을 고름',ARRAY['[4국03-03]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C39','kor',4,2,'u3',7,'예의 있게 제안하기 — 읽는 사람이 받아들이고 싶어지게 예의 있게 씀 — 불만을 쏟거나(생각이 없나 봐요) 억지로 요구하지 않음(무조건 고쳐 놓으세요)',ARRAY['[4국03-03]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C40','kor',4,2,'u3',7,'받아들여지지 않을 때 — 제안은 받아들여질 때도, 까닭이 있어 받아들여지지 않을 때도 있음 — 그 까닭을 살펴 제안을 고치거나 다른 방법을 찾음',ARRAY['[4국03-03]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C41','kor',4,2,'u3',9,'제안하는 내용과 이유의 짝 — 「무엇을 바라는가」(낮은 반납함을 하나 더)와 「그러면 무엇이 좋은가」(동생들도 스스로 돌려줌)를 짝지어 찾음',ARRAY['[4국03-03]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C42','kor',4,2,'u3',9,'제안하는 글로 풀기 알맞은 문제 — 많은 사람이 겪고, 바꿀 수 있는 분께 해결 방법을 제안할 수 있는 문제 — 날씨처럼 바꿀 수 없는 일이나 두 사람 사이의 속상한 일과 구별',ARRAY['[4국03-03]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C43','kor',4,2,'u3',9,'이유에는 좋아지는 점과 확인한 사실 — 여러 사람에게 좋아지는 점과 여쭈어 확인한 사실이 이유가 됨 — 내 취향이나 확인하지 않은 짐작(다른 학교에도 다 있을 것 같다)은 이유로 약하고, 사실처럼 쓰지 않음',ARRAY['[4국03-03]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C44','kor',4,2,'u3',9,'개요 짜기 — 쓸 내용을 처음 · 가운데 · 끝으로 나누어 핵심 낱말로 짧게 적어 차례를 정함 — 글 전체를 미리 다 쓰지 않음',ARRAY['[4국03-03]']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C45','kor',4,2,'u3',9,'문장의 짜임 — 누가/무엇이 + 어찌하다(우리는 손을 씻습니다) · 어떠하다(물이 차갑습니다) · 무엇이다(이곳은 수돗가입니다)',ARRAY['[4국04-03]']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C46','kor',4,2,'u3',9,'어색한 문장 고치기 — 「누가/무엇이」와 뒷부분이 서로 어울리게 고침(수돗가는 손을 씻는 곳입니다 · 우리는 비누로 손을 깨끗이 씻습니다)',ARRAY['[4국04-03]']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C47','kor',4,2,'u3',9,'「무엇이」 칸에 오는 것 — 「누가/무엇이」 칸에는 사람만이 아니라 물건도 옴 — 비누 걸이가(무엇이) + 튼튼합니다(어떠하다)',ARRAY['[4국04-03]']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C48','kor',4,2,'u3',9,'점검하고 고쳐 쓰기 — 누구에게 제안하는지 · 문제 상황을 구체적으로 · 내용과 이유 · 소리 내어 읽어 어색한 문장 · 제목을 살펴 고침 — 친구의 제안이 더 좋으면 받아들여 다듬어도 됨',ARRAY['[4국03-03]']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C49','kor',4,2,'u3',9,'글을 전하는 방법 — 읽을 사람에 맞게 전함 — 교장 선생님께는 직접 드리고, 이웃에게는 허락을 받아 게시판에, 시청에는 누리집 제안 게시판에',ARRAY['[4국03-03]']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C50','kor',4,2,'u3',11,'질문 쪽지 — 친구 의견 곁에 붙이는 질문 쪽지는 실천할 때의 어려움이나 단점을 존중하는 말로 물어 의견을 더 나아지게 함 — 글씨·글쓴이를 묻거나 이상하다고 하지 않음',ARRAY['[4국01-06][4국03-03]']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C51','kor',4,2,'u3',11,'해결은 바라는 모습을 이루는 것 — 「놀잇감을 모두 치우자」는 다툼을 없애지만 「함께 즐겁게 놀자」는 바람까지 없앰 — 문제만 없애는 것이 아니라 바라는 모습을 이루어야 해결',ARRAY['[4국01-06][4국03-03]']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C52','kor',4,2,'u3',11,'안건 발표의 짜임 — 문제 상황(응원 도구가 한 번 쓰고 버려짐) → 제안하는 내용(나눔 상자) → 제안하는 이유(쓰레기가 줄고 준비 시간을 아낌)로 이어 말함',ARRAY['[4국01-06][4국03-03]']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C53','kor',4,2,'u3',11,'안건 고르기 — 전교 학생 자치회에는 많은 학생과 관련 있고, 실천할 수 있으며, 이유에 공감을 얻은 제안을 냄 — 목소리 크기나 우리 반만의 좋은 점으로 고르지 않음',ARRAY['[4국01-06][4국03-03]']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C54','kor',4,2,'u3',11,'한 낱말이 되면 붙여 쓰기 — 두 낱말이 만나 하나의 낱말이 되면 붙여 씀 — 정리를 하다 → 정리하다 · 겁을 먹다 → 겁먹다 · 마음을 먹다 → 마음먹다',ARRAY['기초 다지기(띄어쓰기·낱말 관계·글씨 — 성취기준 번호 확인 필요)']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C55','kor',4,2,'u3',11,'이어져도 띄어 쓰는 말 — 「밥 먹다 · 물 마시다」처럼 하나의 낱말이 된 것이 아니면 띄어 씀 — 헷갈리면 사전을 찾음',ARRAY['기초 다지기(띄어쓰기·낱말 관계·글씨 — 성취기준 번호 확인 필요)']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C56','kor',4,2,'u3',11,'낱말 사이의 관계 — 뜻이 비슷한 관계(무섭다-두렵다) · 뜻이 반대인 관계(넓다-좁다) · 뜻을 포함하는 관계(악기 ⊃ 피아노)',ARRAY['기초 다지기(띄어쓰기·낱말 관계·글씨 — 성취기준 번호 확인 필요)']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C57','kor',4,2,'u3',11,'반대말은 쓰임에 따라 — 같은 「벗다」라도 무엇을 벗는지에 따라 반대말이 입다 · 쓰다 · 신다 · 끼다로 달라짐 — 반대말이 하나뿐인 것은 아님',ARRAY['기초 다지기(띄어쓰기·낱말 관계·글씨 — 성취기준 번호 확인 필요)']::text[],57) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u3-C58','kor',4,2,'u3',11,'겹받침 ㄺ 바르게 쓰기 — 맑다 · 굵다 · 흙길 · 닭장 — ㄹ과 ㄱ을 받침 칸 안에 나란히, 한쪽이 너무 크지 않게 씀',ARRAY['기초 다지기(띄어쓰기·낱말 관계·글씨 — 성취기준 번호 확인 필요)']::text[],58) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X01','kor',4,'u3',ARRAY['K4-2-u3-C2']::text[],'토의를 여럿이 모여 아무 이야기나 나누는 것이나 한 사람이 정해 알려 주는 것으로 여긴다','여럿이 해결 방법을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X02','kor',4,'u3',ARRAY['K4-2-u3-C3','K4-2-u3-C15']::text[],'답이 하나로 정해진 일이나 나 혼자만의 일도 토의할 일로 고른다','여러 의견 · 모두와 관련') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X03','kor',4,'u3',ARRAY['K4-2-u3-C4','K4-2-u3-C24']::text[],'토의할 때 다른 의견에 끼어들거나 목소리 큰 친구의 의견을 그대로 따르는 것을 바른 태도로 여긴다','차례 · 끝까지 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X04','kor',4,'u3',ARRAY['K4-2-u3-C6','K4-2-u3-C31']::text[],'문제가 생기면 언제나 제안하는 글부터 써야 한다고 여긴다','상황에 맞는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X05','kor',4,'u3',ARRAY['K4-2-u3-C6']::text[],'토의를 했으면 제안하는 글은 필요 없다고 여기거나 토의와 제안하는 글을 서로 관계없는 것으로 여긴다','토의로 정한 것을 글로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X06','kor',4,'u3',ARRAY['K4-2-u3-C7','K4-2-u3-C41']::text[],'글쓴이의 의견(제안하는 내용)을 문제 상황이나 좋아지는 점, 글에 없는 내용과 헷갈린다','무엇을 바라는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X07','kor',4,'u3',ARRAY['K4-2-u3-C8']::text[],'토의 절차의 차례나 단계마다 하는 일을 엇갈리게 안다','고르기 → 준비 → 따지기 → 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X08','kor',4,'u3',ARRAY['K4-2-u3-C9']::text[],'토의 주제를 어느 것이 더 급한지 따지지 않고 먼저 나온 것이나 손든 수로만 정한다','더 급한 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X09','kor',4,'u3',ARRAY['K4-2-u3-C10','K4-2-u3-C15']::text[],'우리가 해결에 나설 수 없을 만큼 큰 문제를 토의 주제로 고른다(방학 한 달 늘리기·학교 새로 짓기)','우리가 풀 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X10','kor',4,'u3',ARRAY['K4-2-u3-C10','K4-2-u3-C17']::text[],'내 의견의 단점은 생각하지 않고 「이것만 하면 끝」이라고 여긴다','단점도 생각해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X11','kor',4,'u3',ARRAY['K4-2-u3-C11']::text[],'토의에서 질문은 상대가 의견을 포기하게 만들거나 시간을 늘리는 것이라고 여긴다','의견을 다듬어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X12','kor',4,'u3',ARRAY['K4-2-u3-C12','K4-2-u3-C19','K4-2-u3-C50']::text[],'상대의 기분을 헤아리지 않고 틀렸다고 먼저 말하거나 깎아내리며 묻는 질문을 괜찮다고 여긴다','좋은 점 먼저 · 구체적으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X13','kor',4,'u3',ARRAY['K4-2-u3-C13']::text[],'「좋은 의견이에요」 같은 존중하는 말만 붙이면 무엇을 묻든 좋은 질문이라고 여긴다','말투와 내용 둘 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X14','kor',4,'u3',ARRAY['K4-2-u3-C13','K4-2-u3-C51']::text[],'질문은 많을수록 좋다고 여겨 궁금한 것이 없어도 수를 채우거나, 질문을 많이 받은 의견이 좋은 의견이라고 여긴다','개수보다 쓸모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X15','kor',4,'u3',ARRAY['K4-2-u3-C14']::text[],'결과 · 어려움 · 실천 방법을 묻는 질문을 엇갈리게 안다','달라질까 · 곤란할까 · 언제 누가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X16','kor',4,'u3',ARRAY['K4-2-u3-C16']::text[],'문제가 생긴 까닭과 그 때문에 생긴 영향을 헷갈린다','왜 그런가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X17','kor',4,'u3',ARRAY['K4-2-u3-C17','K4-2-u3-C18']::text[],'가장 쉽게 할 수 있는 의견이 언제나 가장 좋은 의견이라고 여긴다','해결되는지도 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X18','kor',4,'u3',ARRAY['K4-2-u3-C18']::text[],'쉬운 의견은 해결에 도움이 되더라도 모두 버려야 한다고 여긴다','쉬운지와 해결되는지 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X19','kor',4,'u3',ARRAY['K4-2-u3-C21']::text[],'여러 의견을 모두 합치면 언제나 가장 좋은 의견이 된다고 여긴다','합친 것도 기준으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X20','kor',4,'u3',ARRAY['K4-2-u3-C21']::text[],'기준 없이 가위바위보나 빨리 정하는 것으로 의견을 결정한다','기준에 비추어 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X21','kor',4,'u3',ARRAY['K4-2-u3-C23']::text[],'실천 계획을 「열심히 노력한다」·「언젠가 해 본다」처럼 막연하게 세운다','언제 · 누가 · 무엇을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X22','kor',4,'u3',ARRAY['K4-2-u3-C22']::text[],'우리 힘만으로 할 수 없는 일을 억지로 우리끼리 하려 하거나 그냥 포기한다','바꿀 수 있는 곳에 제안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X23','kor',4,'u3',ARRAY['K4-2-u3-C20']::text[],'질문을 받고 의견을 고치면 진 것이라고 여기거나 질문 때문에 의견이 나빠진다고 여긴다','답하며 의견이 자라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X24','kor',4,'u3',ARRAY['K4-2-u3-C25','K4-2-u3-C34']::text[],'제안할 대상을 그 일을 정하거나 바꿀 수 없는 사람으로 고른다','바꿀 수 있는 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X25','kor',4,'u3',ARRAY['K4-2-u3-C26']::text[],'문제 상황을 글이나 그림과 상관없는 것으로 찾는다','누가 어디서 어떤 불편?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X26','kor',4,'u3',ARRAY['K4-2-u3-C27','K4-2-u3-C52']::text[],'문제 상황 · 제안하는 내용 · 제안하는 이유를 엇갈리게 짝짓는다','불편 → 바람 → 좋아지는 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X27','kor',4,'u3',ARRAY['K4-2-u3-C28']::text[],'「~하세요」로 끝나면 해결 방법이 없어도 제안하는 글이라고 여긴다','해결 방법이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X28','kor',4,'u3',ARRAY['K4-2-u3-C28']::text[],'짧게 막기만 하는 말일수록 좋은 제안이라고 여긴다','방법과 이유까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X29','kor',4,'u3',ARRAY['K4-2-u3-C29']::text[],'제안하는 글을 쓰기 전에 생각할 내용(제목·대상·그림이나 사진·전할 방법)을 모르거나 상관없는 것을 고른다','제목 · 누구 · 사진 · 전하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X30','kor',4,'u3',ARRAY['K4-2-u3-C30','K4-2-u3-C40']::text[],'글로 제안하면 언제나 받아들여진다고 여긴다','받아들여지지 않을 때도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X31','kor',4,'u3',ARRAY['K4-2-u3-C30','K4-2-u3-C39']::text[],'제안하는 글을 속상한 마음이나 불만을 마음껏 쏟아 내는 글로 여긴다','해결 방법을 내놓아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X32','kor',4,'u3',ARRAY['K4-2-u3-C32']::text[],'제안하는 글을 쓰는 과정의 차례를 엇갈리게 안다','문제 → 누구 → 내용·이유 → 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X33','kor',4,'u3',ARRAY['K4-2-u3-C33']::text[],'쓰는 과정은 차례대로만 가야 하고 앞 단계로 되돌아가면 안 된다고 여긴다','차례는 길잡이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X34','kor',4,'u3',ARRAY['K4-2-u3-C35']::text[],'문제만 해결되면 실천하기 어려운 제안도 알맞다고 여긴다(하루 종일 안내하는 사람 세우기)','실제로 할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X35','kor',4,'u3',ARRAY['K4-2-u3-C35','K4-2-u3-C41']::text[],'문제에서 멀어지거나 문제를 키우는 제안을 고른다(버스를 없애기·건물을 새로 짓기)','이 문제를 바로 푸나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X36','kor',4,'u3',ARRAY['K4-2-u3-C36']::text[],'「왜냐하면 ……때문입니다」만 쓰면 무엇이든 알맞은 이유가 된다고 여긴다','무엇이 좋아지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X37','kor',4,'u3',ARRAY['K4-2-u3-C36','K4-2-u3-C43']::text[],'내가 겪은 불편이나 내 취향만으로 제안하는 이유를 든다','여러 사람에게 좋아지는 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X38','kor',4,'u3',ARRAY['K4-2-u3-C43']::text[],'확인하지 않은 짐작을 사실처럼 이유로 쓴다','확인한 사실인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X39','kor',4,'u3',ARRAY['K4-2-u3-C39']::text[],'「무조건」·「당장」처럼 억지로 요구하거나 상대를 탓하는 표현을 제안하는 글에 쓴다','예의 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X40','kor',4,'u3',ARRAY['K4-2-u3-C38']::text[],'제안 표현은 외워서 어느 문장에나 똑같이 넣어야 한다고 여기거나 제안 표현과 이유 표현을 엇갈리게 안다','어울리는 것을 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X41','kor',4,'u3',ARRAY['K4-2-u3-C40']::text[],'제안이 받아들여지지 않으면 포기하거나 같은 글을 날마다 다시 보낸다','까닭을 살펴 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X42','kor',4,'u3',ARRAY['K4-2-u3-C37','K4-2-u3-C48']::text[],'문제 상황을 막연하게 쓰거나, 제목을 제안 내용과 상관없이 붙인다','겪은 일 · 제안이 드러나는 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X43','kor',4,'u3',ARRAY['K4-2-u3-C42']::text[],'제안하는 글로 풀 문제로 날씨처럼 바꿀 수 없는 일이나 두 사람 사이의 속상한 일을 고른다','누구에게 제안하면 바뀌나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X44','kor',4,'u3',ARRAY['K4-2-u3-C44']::text[],'개요에 글 전체를 미리 다 쓰거나 개요 없이 떠오르는 대로 쓴다','핵심 낱말로 짧게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X45','kor',4,'u3',ARRAY['K4-2-u3-C45']::text[],'어찌하다 · 어떠하다 · 무엇이다 문장의 짜임을 엇갈리게 안다','움직임 · 모습 · 무엇') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X46','kor',4,'u3',ARRAY['K4-2-u3-C46']::text[],'「누가/무엇이」와 뒷부분이 어울리지 않는 문장을 그대로 두거나 엉뚱하게 고친다','소리 내어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X47','kor',4,'u3',ARRAY['K4-2-u3-C47']::text[],'「누가/무엇이」 칸에는 사람만 올 수 있다고 여기거나 짧으면 문장이 아니라고 여긴다','물건도 「무엇이」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X48','kor',4,'u3',ARRAY['K4-2-u3-C49']::text[],'글을 전하는 방법을 읽을 사람과 상관없이 정한다','누구에게 어떻게?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X49','kor',4,'u3',ARRAY['K4-2-u3-C51']::text[],'다툼이나 문제만 없어지면 원래 바라던 것까지 없어져도 해결이라고 여긴다','바라는 모습을 이루나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X50','kor',4,'u3',ARRAY['K4-2-u3-C53']::text[],'안건을 발표 목소리 크기나 우리 반에만 좋은 점으로 고른다','많은 학생 · 공감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X51','kor',4,'u3',ARRAY['K4-2-u3-C55']::text[],'두 낱말이 이어지면 언제나 붙여 써야 한다고 여긴다(밥먹고·물마시고)','한 낱말이 됐나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X52','kor',4,'u3',ARRAY['K4-2-u3-C54']::text[],'하나의 낱말이 된 말을 띄어 쓴다(정리 하고·겁 먹고)','한 낱말은 붙여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X53','kor',4,'u3',ARRAY['K4-2-u3-C56']::text[],'뜻이 비슷한 · 반대인 · 포함하는 관계를 엇갈리게 안다','비슷 · 반대 · 포함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X54','kor',4,'u3',ARRAY['K4-2-u3-C57']::text[],'한 낱말의 반대말은 하나뿐이라고 여긴다','무엇을 벗나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X55','kor',4,'u3',ARRAY['K4-2-u3-C58']::text[],'겹받침 ㄺ을 받침 하나로 쓰거나 다른 받침으로 쓴다(막다·말다·흑길)','ㄹ과 ㄱ을 나란히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X56','kor',4,'u3',ARRAY['K4-2-u3-C1']::text[],'이 단원에서 배울 내용을 단원과 상관없는 것으로 여긴다','토의 · 제안하는 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X57','kor',4,'u3',ARRAY['K4-2-u3-C5','K4-2-u3-C25']::text[],'제안을 명령하거나 불평하는 것으로 여긴다','의견을 내놓는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u3-X58','kor',4,'u3',ARRAY['K4-2-u3-C24']::text[],'모둠에서 결정한 의견이 내 의견과 다르면 따르지 않아도 된다고 여긴다','함께 실천해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#1','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C2',1,'mc','auto','「토의」를 바르게 설명한 것은 무엇인가요?',ARRAY['K4-2-u3-X01']::text[],false,'{"seq":1,"concept":"K4-2-u3-C2","difficulty":1,"kind":"mc","stem":"「토의」를 바르게 설명한 것은 무엇인가요?","options":[{"t":"여럿이 의견을 모아 문제의 해결 방법을 찾는 것","correct":true},{"t":"한 사람이 방법을 정해 다른 사람에게 알려 주는 것","mis":"K4-2-u3-X01"},{"t":"여럿이 모여 아무 이야기나 나누는 것","mis":"K4-2-u3-X01"},{"t":"누가 이기는지 가리려고 말다툼하는 것","mis":"K4-2-u3-X01"}],"explanation":["문턱 이야기를 떠올려요.","여럿이 의견을 모았어요.","해결 방법을 찾았어요."],"asset":{"type":"passage","lines":["교실 앞문 문턱에 발이 걸려 넘어질 뻔한 친구가 여럿이었어요.","반 친구들이 왜 걸리는지, 어떻게 하면 좋을지 함께 이야기해 선생님께 알렸어요.","얼마 뒤 문턱에 눈에 잘 띄는 밝은 색 띠가 붙었어요."],"title":"모두가 그냥 지나쳤던 문턱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#2','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C3',1,'mc','auto','반 친구들과 토의해 정하기에 알맞은 일은 무엇인가요?',ARRAY['K4-2-u3-X02']::text[],false,'{"seq":2,"concept":"K4-2-u3-C3","difficulty":1,"kind":"mc","stem":"반 친구들과 토의해 정하기에 알맞은 일은 무엇인가요?","options":[{"t":"학급 행사 날 우리 반이 함께 할 활동","correct":true},{"t":"3 더하기 4의 답","mis":"K4-2-u3-X02"},{"t":"오늘 내가 신을 양말 색깔","mis":"K4-2-u3-X02"},{"t":"내 필통에 넣을 지우개 개수","mis":"K4-2-u3-X02"}],"explanation":["답이 정해진 일은 빼요.","나 혼자만의 일도 빼요.","모두와 관련 있는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#3','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C4',1,'ox','auto','토의할 때 내 생각과 다르면 친구 말이 끝나기 전에 바로 끼어들어 말해요.',ARRAY['K4-2-u3-X03']::text[],false,'{"seq":3,"concept":"K4-2-u3-C4","difficulty":1,"kind":"ox","stem":"토의할 때 내 생각과 다르면 친구 말이 끝나기 전에 바로 끼어들어 말해요.","answer":"X","reason_options":[{"t":"나와 다른 의견도 끝까지 들어야 알맞은지 함께 따질 수 있기 때문에","correct":true},{"t":"빨리 말해야 내 의견이 뽑히기 때문에","mis":"K4-2-u3-X03"}],"mis":"K4-2-u3-X03","explanation":["차례를 지켜요.","끝까지 들어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#4','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C7',1,'mc','auto','새론이가 내놓은 의견은 무엇인가요?',ARRAY['K4-2-u3-X06']::text[],false,'{"seq":4,"concept":"K4-2-u3-C7","difficulty":1,"kind":"mc","stem":"새론이가 내놓은 의견은 무엇인가요?","options":[{"t":"쉬는 시간마다 창문을 열었다가 수업 종이 치면 닫자","correct":true},{"t":"교실 창문을 하루 내내 열어 두자","mis":"K4-2-u3-X06"},{"t":"오후에는 답답하니 공부를 쉬자","mis":"K4-2-u3-X06"},{"t":"미세 먼지가 많은 날에만 창문을 열자","mis":"K4-2-u3-X06"}],"explanation":["「……면 어떨까요?」를 찾아요.","3번 문장이에요.","쉬는 시간마다 열자는 의견이에요."],"asset":{"type":"passage","lines":["1 4학년 2반 친구들, 안녕하세요? 저는 새론입니다.","2 요즘 창문을 닫아 두는 시간이 길어서, 오후가 되면 교실 공기가","   답답하다는 친구가 많습니다.","3 쉬는 시간마다 창문 당번이 창문을 열었다가 수업 종이 치면 닫으면 어떨까요?","4 그러면 바깥 공기가 들어와 머리가 맑아지고 공부에 더 집중할 수 있습니다.","5 다만 미세 먼지가 많은 날에는 창문을 짧게만 열기로 해요."],"title":"새론이의 글 「쉬는 시간마다 창문을 열어요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#5','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C8',2,'match','auto','토의 절차와 그 단계에서 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u3-C8","difficulty":2,"kind":"match","stem":"토의 절차와 그 단계에서 하는 일을 알맞게 이으세요.","pairs":[{"l":"주제 정하기","r":"모두와 관련 있고 우리가 풀 수 있는 문제를 고른다"},{"l":"의견 마련하기","r":"주제에 맞는 의견과 뒷받침할 이유를 준비한다"},{"l":"의견 모으기","r":"의견을 나누며 알맞은지 서로 묻고 따진다"},{"l":"의견 결정하기","r":"기준을 세워 가장 알맞은 의견을 정한다"}],"mis":"K4-2-u3-X07","explanation":["「고른다」는 처음이에요.","준비하고, 따지고,","「정한다」는 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#6','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C12',2,'mc','auto','희수와 유건의 질문 가운데 이솔이의 기분을 헤아린 질문과 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13','K4-2-u3-X11']::text[],false,'{"seq":6,"concept":"K4-2-u3-C12","difficulty":2,"kind":"mc","stem":"희수와 유건의 질문 가운데 이솔이의 기분을 헤아린 질문과 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"유건 — 좋은 점을 먼저 인정하고 궁금한 점을 구체적으로 물었다","correct":true},{"t":"희수 — 짧게 바로 물어서 좋다","mis":"K4-2-u3-X12"},{"t":"둘 다 물어보았으니 차이가 없다","mis":"K4-2-u3-X13"},{"t":"희수 — 귀찮다고 말해야 이솔이가 의견을 포기하니 좋다","mis":"K4-2-u3-X11"}],"explanation":["내가 이솔이라고 생각해요.","어느 질문에 답하고 싶나요?","유건이의 질문이에요."],"asset":{"type":"speech","turns":[{"who":"이솔","text":"책마다 번호 스티커를 붙이고 책꽂이 칸에도 같은 번호를 붙이면 좋겠습니다. 번호만 맞추면 누구나 제자리에 꽂을 수 있기 때문입니다."},{"who":"희수","text":"그건 너무 귀찮은 방법 아닌가요?"},{"who":"이솔","text":"처음에 한 번만 붙여 두면 그다음부터는 쉽다고 생각합니다."},{"who":"유건","text":"책을 쉽게 찾을 수 있겠네요. 그런데 스티커가 떨어지면 어떻게 하나요?"},{"who":"이솔","text":"스티커 위에 투명 테이프를 덮으면 잘 떨어지지 않을 것 같습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#7','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C11',2,'mc','auto','두 친구의 질문은 토의에서 어떤 역할을 했나요?',ARRAY['K4-2-u3-X11','K4-2-u3-X23']::text[],false,'{"seq":7,"concept":"K4-2-u3-C11","difficulty":2,"kind":"mc","stem":"두 친구의 질문은 토의에서 어떤 역할을 했나요?","options":[{"t":"이솔이의 의견이 「테이프로 덮기」까지 더 구체적으로 다듬어지게 도왔다","correct":true},{"t":"이솔이가 의견을 포기하게 만들었다","mis":"K4-2-u3-X11"},{"t":"토의 시간을 길게 늘이기만 했다","mis":"K4-2-u3-X11"},{"t":"이솔이가 의견을 고쳤으니 토의에서 진 것이다","mis":"K4-2-u3-X23"}],"explanation":["질문 전과 뒤를 견줘요.","테이프 생각이 더해졌어요.","의견이 다듬어졌어요."],"asset":{"type":"speech","turns":[{"who":"이솔","text":"책마다 번호 스티커를 붙이고 책꽂이 칸에도 같은 번호를 붙이면 좋겠습니다. 번호만 맞추면 누구나 제자리에 꽂을 수 있기 때문입니다."},{"who":"희수","text":"그건 너무 귀찮은 방법 아닌가요?"},{"who":"이솔","text":"처음에 한 번만 붙여 두면 그다음부터는 쉽다고 생각합니다."},{"who":"유건","text":"책을 쉽게 찾을 수 있겠네요. 그런데 스티커가 떨어지면 어떻게 하나요?"},{"who":"이솔","text":"스티커 위에 투명 테이프를 덮으면 잘 떨어지지 않을 것 같습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#8','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C5',2,'mc','auto','「제안」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X57','K4-2-u3-X01']::text[],false,'{"seq":8,"concept":"K4-2-u3-C5","difficulty":2,"kind":"mc","stem":"「제안」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 일에 대해 의견을 내놓는 것","correct":true},{"t":"다른 사람에게 억지로 시키는 것","mis":"K4-2-u3-X57"},{"t":"불편한 점을 불평만 하는 것","mis":"K4-2-u3-X57"},{"t":"여럿이 모여 아무 이야기나 하는 것","mis":"K4-2-u3-X01"}],"explanation":["예슬이의 생각을 떠올려요.","글로 써서 붙이자는 의견이에요.","의견을 내놓는 것이 제안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#9','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C10',2,'mc','auto','「스티커만 붙이면 끝! 더 생각할 것 없어.」라고 말한 친구가 놓친 주의할 점은 무엇인가요?',ARRAY['K4-2-u3-X03','K4-2-u3-X08','K4-2-u3-X14']::text[],false,'{"seq":9,"concept":"K4-2-u3-C10","difficulty":2,"kind":"mc","stem":"「스티커만 붙이면 끝! 더 생각할 것 없어.」라고 말한 친구가 놓친 주의할 점은 무엇인가요?","options":[{"t":"내 의견의 단점도 생각해 본다","correct":true},{"t":"목소리를 크게 내어 말한다","mis":"K4-2-u3-X03"},{"t":"가장 먼저 나온 의견으로 정한다","mis":"K4-2-u3-X08"},{"t":"질문을 되도록 많이 한다","mis":"K4-2-u3-X14"}],"explanation":["「끝」이라고 했어요.","스티커가 떨어지면요?","단점도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_basic#10','kor',4,2,'u3','L02','g4_2_kor_u3_L02_basic','lesson_basic','K4-2-u3-C6',3,'error','auto','토의와 제안하는 글을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X05']::text[],false,'{"seq":10,"concept":"K4-2-u3-C6","difficulty":3,"kind":"error","stem":"토의와 제안하는 글을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「문제가 생기면 언제나 제안하는 글부터 써야 해.」","correct":true,"mis_target":"K4-2-u3-X04"},{"t":"친구 가 — 「토의로 정한 방법을 글로 써서 다른 반에 알릴 수 있어.」","mis":"K4-2-u3-X05"},{"t":"친구 나 — 「둘 다 문제를 해결하는 방법이야.」","mis":"K4-2-u3-X05"}],"explanation":["둘 다 해결 방법이에요.","「언제나」를 조심해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#1','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C2',2,'sa','auto','여럿이 의견을 모아 문제의 해결 방법을 찾는 것을 무엇이라고 하는지 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u3-C2","difficulty":2,"kind":"sa","stem":"여럿이 의견을 모아 문제의 해결 방법을 찾는 것을 무엇이라고 하는지 두 글자로 쓰세요.","answer":["토의"],"explanation":["여럿이 모여요.","의견을 모아요.","‘토의’예요."],"mis":"K4-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#2','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C14',2,'blank','auto','「그렇게 할 때 곤란한 점은 없을까요?」는 의견의 (  )을/를 묻는 질문이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X15']::text[],false,'{"seq":2,"concept":"K4-2-u3-C14","difficulty":2,"kind":"blank","stem":"「그렇게 할 때 곤란한 점은 없을까요?」는 의견의 (  )을/를 묻는 질문이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"어려움","correct":true},{"t":"결과","mis":"K4-2-u3-X15"},{"t":"실천 방법","mis":"K4-2-u3-X15"},{"t":"좋은 점","mis":"K4-2-u3-X15"}],"explanation":["「곤란한 점」을 봐요.","하기 힘든 점이에요.","‘어려움’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#3','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C9',3,'mc','auto','사회자 호연이가 토의 주제를 정한 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X08','K4-2-u3-X03']::text[],false,'{"seq":3,"concept":"K4-2-u3-C9","difficulty":3,"kind":"mc","stem":"사회자 호연이가 토의 주제를 정한 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"두 문제 가운데 무엇이 더 급한지 까닭을 들어 이야기하게 한 뒤 정했다","correct":true},{"t":"먼저 나온 문제로 바로 정했다","mis":"K4-2-u3-X08"},{"t":"손을 든 친구 수만 세어 정했다","mis":"K4-2-u3-X08"},{"t":"목소리가 가장 큰 친구의 문제로 정했다","mis":"K4-2-u3-X03"}],"explanation":["사회자의 마지막 말을 봐요.","더 급한 까닭을 들었어요.","그 뒤에 정했어요."],"asset":{"type":"speech","turns":[{"who":"사회자 호연","text":"우리 반에서 함께 해결하고 싶은 문제가 있나요?"},{"who":"성주","text":"학급 문고 책이 제자리로 돌아오지 않아서 읽고 싶은 책을 찾기 어렵습니다."},{"who":"초은","text":"사물함 위에 물건이 쌓여 있어서 떨어질 때가 있습니다."},{"who":"사회자 호연","text":"두 문제 가운데 무엇이 더 급한지 까닭을 들어 말해 봅시다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#4','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C13',3,'mc','auto','이 질문에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X13','K4-2-u3-X14','K4-2-u3-X12']::text[],false,'{"seq":4,"concept":"K4-2-u3-C13","difficulty":3,"kind":"mc","stem":"이 질문에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"말투는 공손하지만, 의견이 문제를 해결하는지 따지는 데 도움이 되지 않는다","correct":true},{"t":"「좋은 의견이에요」를 붙였으니 좋은 질문이다","mis":"K4-2-u3-X13"},{"t":"질문은 무엇이든 많을수록 토의가 좋아진다","mis":"K4-2-u3-X14"},{"t":"공손한 말은 필요 없으니 빼고 물어야 한다","mis":"K4-2-u3-X12"}],"explanation":["말투를 봐요.","무엇을 묻는지도 봐요.","스티커 색은 해결과 상관없어요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"좋은 의견이에요! 그런데 스티커는 무슨 색인가요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#5','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C10',3,'match','auto','토의 상황과 그 친구가 지켜야 할 주의할 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u3-C10","difficulty":3,"kind":"match","stem":"토의 상황과 그 친구가 지켜야 할 주의할 점을 알맞게 이으세요.","pairs":[{"l":"「우리 학교 여름 방학을 한 달 늘리는 방법을 토의해요.」","r":"우리가 해결할 수 있는 주제인지 살핀다"},{"l":"「스티커만 붙이면 끝! 더 생각할 것 없어.」","r":"내 의견의 단점도 생각해 본다"},{"l":"친구 말이 끝나기 전에 「그건 아니야!」","r":"끝까지 듣고 주제에 알맞은지 따진다"},{"l":"「가장 먼저 나온 의견으로 해요.」","r":"기준을 세워 여러 의견을 견주어 정한다"}],"mis":"K4-2-u3-X10","explanation":["각 친구가 놓친 것을 찾아요.","풀 수 있나 · 단점 · 끝까지","기준으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#6','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C3',3,'ox','auto','「내가 오늘 신을 양말 색깔」은 반 친구들과 토의해 정하기에 알맞은 일이에요.',ARRAY['K4-2-u3-X02']::text[],false,'{"seq":6,"concept":"K4-2-u3-C3","difficulty":3,"kind":"ox","stem":"「내가 오늘 신을 양말 색깔」은 반 친구들과 토의해 정하기에 알맞은 일이에요.","answer":"X","reason_options":[{"t":"나 혼자만의 일이라 모두와 관련 있는 일이 아니기 때문에","correct":true},{"t":"여러 의견이 나올 수 있는 일은 무엇이든 토의할 일이기 때문에","mis":"K4-2-u3-X02"}],"mis":"K4-2-u3-X02","explanation":["누구와 관련 있나요?","나 혼자만의 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#7','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C14',3,'mc','auto','이솔이의 의견에 「누가, 언제 스티커를 붙이면 좋을까요?」라고 물었다면 어떤 질문인가요?',ARRAY['K4-2-u3-X15','K4-2-u3-X11']::text[],false,'{"seq":7,"concept":"K4-2-u3-C14","difficulty":3,"kind":"mc","stem":"이솔이의 의견에 「누가, 언제 스티커를 붙이면 좋을까요?」라고 물었다면 어떤 질문인가요?","options":[{"t":"실천 방법을 묻는 질문","correct":true},{"t":"결과를 묻는 질문","mis":"K4-2-u3-X15"},{"t":"어려움을 묻는 질문","mis":"K4-2-u3-X15"},{"t":"의견을 포기하게 하는 질문","mis":"K4-2-u3-X11"}],"explanation":["「누가, 언제」를 봐요.","어떻게 할지 묻고 있어요.","실천 방법이에요."],"asset":{"type":"speech","turns":[{"who":"이솔","text":"책마다 번호 스티커를 붙이고 책꽂이 칸에도 같은 번호를 붙이면 좋겠습니다. 번호만 맞추면 누구나 제자리에 꽂을 수 있기 때문입니다."},{"who":"희수","text":"그건 너무 귀찮은 방법 아닌가요?"},{"who":"이솔","text":"처음에 한 번만 붙여 두면 그다음부터는 쉽다고 생각합니다."},{"who":"유건","text":"책을 쉽게 찾을 수 있겠네요. 그런데 스티커가 떨어지면 어떻게 하나요?"},{"who":"이솔","text":"스티커 위에 투명 테이프를 덮으면 잘 떨어지지 않을 것 같습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#8','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C4',4,'mc','auto','토의 중에 목소리가 큰 친구가 「무조건 내 의견대로 하자!」라고 할 때 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u3-X03','K4-2-u3-X12','K4-2-u3-X01']::text[],false,'{"seq":8,"concept":"K4-2-u3-C4","difficulty":4,"kind":"mc","stem":"토의 중에 목소리가 큰 친구가 「무조건 내 의견대로 하자!」라고 할 때 알맞은 태도는 무엇인가요?","options":[{"t":"다른 친구들의 의견도 끝까지 듣고, 기준에 비추어 견주어 정하자고 말한다","correct":true},{"t":"목소리가 크니 그 의견을 그대로 따른다","mis":"K4-2-u3-X03"},{"t":"바로 끼어들어 「네 의견은 틀렸어!」라고 말한다","mis":"K4-2-u3-X12"},{"t":"토의를 그만두고 각자 마음대로 정한다","mis":"K4-2-u3-X01"}],"explanation":["모두의 의견이 고르게 나와야 해요.","끝까지 들어요.","기준으로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#9','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C1',4,'mc','auto','예슬이가 정한 방법을 다른 반에도 알리고 싶어 해요. 이 단원에서 배울 두 가지와 이어 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X05','K4-2-u3-X04','K4-2-u3-X56']::text[],false,'{"seq":9,"concept":"K4-2-u3-C1","difficulty":4,"kind":"mc","stem":"예슬이가 정한 방법을 다른 반에도 알리고 싶어 해요. 이 단원에서 배울 두 가지와 이어 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"토의로 해결 방법을 찾고, 그 방법을 의견과 이유가 드러나게 제안하는 글로 알린다","correct":true},{"t":"토의로 정했으니 더 할 일은 없다","mis":"K4-2-u3-X05"},{"t":"어떤 문제든 처음부터 제안하는 글부터 쓴다","mis":"K4-2-u3-X04"},{"t":"화분을 잘 기르는 방법을 외운다","mis":"K4-2-u3-X56"}],"explanation":["학급 회의는 토의예요.","알리는 것은 글이에요.","두 가지가 이어져요."],"asset":{"type":"passage","lines":["주제 — 교실 화분이 자꾸 시드는 문제를 어떻게 해결할까?","한빛 — 「요일마다 물을 주는 사람을 정하면 좋겠습니다.」","예슬 — 「우리 반에서 정한 방법을 다른 반에도 알리고 싶어.」"],"title":"한빛이네 반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L02_challenge#10','kor',4,2,'u3','L02','g4_2_kor_u3_L02_challenge','lesson_challenge','K4-2-u3-C12',4,'essay','teacher','희수의 질문 「그건 너무 귀찮은 방법 아닌가요?」를 이솔이의 기분을 헤아리면서 의견을 다듬는 데 도움이 되는 질문으로 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C12","difficulty":4,"kind":"essay","stem":"희수의 질문 「그건 너무 귀찮은 방법 아닌가요?」를 이솔이의 기분을 헤아리면서 의견을 다듬는 데 도움이 되는 질문으로 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 「번호만 맞추면 되니 편하겠네요. 그런데 처음에 스티커를 붙이는 일은 누가, 언제 하면 좋을까요?」라고 고친다. 의견의 좋은 점을 먼저 인정해서 이솔이가 기꺼이 답하고 싶어지고, 귀찮다는 느낌 대신 실천 방법을 구체적으로 물어서 의견을 더 낫게 다듬을 수 있기 때문이다.","scoring_points":["좋은 점을 먼저 인정하는 말을 넣었는가","궁금한 점(결과·어려움·실천 방법)을 구체적으로 물었는가","그렇게 고친 까닭을 썼는가"]},"explanation":["좋은 점을 먼저 말해요.","구체적으로 물어요.","의견이 더 나아져요."],"asset":{"type":"speech","turns":[{"who":"이솔","text":"책마다 번호 스티커를 붙이고 책꽂이 칸에도 같은 번호를 붙이면 좋겠습니다. 번호만 맞추면 누구나 제자리에 꽂을 수 있기 때문입니다."},{"who":"희수","text":"그건 너무 귀찮은 방법 아닌가요?"},{"who":"이솔","text":"처음에 한 번만 붙여 두면 그다음부터는 쉽다고 생각합니다."},{"who":"유건","text":"책을 쉽게 찾을 수 있겠네요. 그런데 스티커가 떨어지면 어떻게 하나요?"},{"who":"이솔","text":"스티커 위에 투명 테이프를 덮으면 잘 떨어지지 않을 것 같습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#1','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C15',1,'mc','auto','모둠 토의 주제로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X09','K4-2-u3-X02']::text[],false,'{"seq":1,"concept":"K4-2-u3-C15","difficulty":1,"kind":"mc","stem":"모둠 토의 주제로 알맞은 것은 무엇인가요?","options":[{"t":"음수대 앞 줄이 긴 문제를 어떻게 해결할까?","correct":true},{"t":"우리 동네에 큰 공원을 새로 만들려면 어떻게 할까?","mis":"K4-2-u3-X09"},{"t":"학교 건물을 새로 크게 지으려면 어떻게 할까?","mis":"K4-2-u3-X09"},{"t":"내 필통에 연필을 몇 자루 넣을까?","mis":"K4-2-u3-X02"}],"explanation":["우리 모두와 관련 있나요?","우리가 나설 수 있나요?","음수대 줄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#2','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C16',1,'mc','auto','㉠과 ㉡ 가운데 「문제가 생긴 까닭」을 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u3-X16']::text[],false,'{"seq":2,"concept":"K4-2-u3-C16","difficulty":1,"kind":"mc","stem":"㉠과 ㉡ 가운데 「문제가 생긴 까닭」을 바르게 고른 것은 무엇인가요?","options":[{"t":"㉠ — 젖은 우산과 신발의 물이 바닥에 고인다","correct":true},{"t":"㉡ — 미끄러져 다칠 수 있다","mis":"K4-2-u3-X16"},{"t":"㉠과 ㉡ 모두 까닭이다","mis":"K4-2-u3-X16"},{"t":"㉠과 ㉡ 모두 영향이다","mis":"K4-2-u3-X16"}],"explanation":["「왜 미끄러운가」를 물어요.","물이 고여서예요.","㉡은 그 때문에 생긴 일이에요."],"asset":{"type":"passage","lines":["㉠ 젖은 우산과 신발에서 떨어진 물이 현관 바닥에 고인다","㉡ 미끄러져 다칠 수 있고, 조심하느라 현관이 붐빈다"],"title":"효주네 모둠이 정리한 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#3','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C17',1,'ox','auto','의견을 마련할 때 「의견의 단점도 생각했는가?」도 스스로 물어요.',ARRAY['K4-2-u3-X10']::text[],false,'{"seq":3,"concept":"K4-2-u3-C17","difficulty":1,"kind":"ox","stem":"의견을 마련할 때 「의견의 단점도 생각했는가?」도 스스로 물어요.","answer":"O","reason_options":[{"t":"단점을 알아야 질문에 답하고 의견을 더 낫게 다듬을 수 있기 때문에","correct":true},{"t":"좋은 의견에는 단점이 없기 때문에","mis":"K4-2-u3-X10"}],"mis":"K4-2-u3-X10","explanation":["네 가지 물음을 떠올려요.","단점도 들어 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#4','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C23',1,'mc','auto','결정한 의견을 실천할 계획으로 가장 구체적인 것은 무엇인가요?',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":4,"concept":"K4-2-u3-C23","difficulty":1,"kind":"mc","stem":"결정한 의견을 실천할 계획으로 가장 구체적인 것은 무엇인가요?","options":[{"t":"비 오는 날 등교 시간에 두 사람씩 요일을 나누어 현관 바닥을 닦는다","correct":true},{"t":"현관을 안전하게 하려고 열심히 노력한다","mis":"K4-2-u3-X21"},{"t":"언젠가 시간이 날 때 한 번 해 본다","mis":"K4-2-u3-X21"},{"t":"모두가 알아서 조심한다","mis":"K4-2-u3-X21"}],"explanation":["언제 하나요?","누가 하나요?","무엇을 하나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#5','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C18',2,'mc','auto','솔비의 의견은 가장 쉽게 할 수 있어요. 솔비의 의견에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X18','K4-2-u3-X10']::text[],false,'{"seq":5,"concept":"K4-2-u3-C18","difficulty":2,"kind":"mc","stem":"솔비의 의견은 가장 쉽게 할 수 있어요. 솔비의 의견에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"쉽지만 바닥에 고인 물을 줄이지 못해 문제 해결에 도움이 적다","correct":true},{"t":"가장 쉬우니 가장 좋은 의견이다","mis":"K4-2-u3-X17"},{"t":"쉬운 의견은 모두 버려야 한다","mis":"K4-2-u3-X18"},{"t":"마음속으로 하는 일이라 단점이 하나도 없다","mis":"K4-2-u3-X10"}],"explanation":["솔비의 의견대로 해 봐요.","바닥의 물이 줄어드나요?","쉬운지와 해결되는지 함께 따져요."],"asset":{"type":"passage","lines":["주제 — 비 오는 날 현관 바닥이 미끄러운 문제를 어떻게 해결할까?","효주 — 현관 밖에서 우산을 털고 접어서 들어오자.","석진 — 비 오는 날 현관 수건 당번을 두자.","온하 — 물기를 빨아들이는 발판을 더 깔아 달라고 학교에 부탁하자.","솔비 — 현관을 지날 때 마음속으로 「조심하자」고 말하자."],"title":"효주네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#6','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C19',2,'mc','auto','석진이의 의견에 할 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13','K4-2-u3-X14']::text[],false,'{"seq":6,"concept":"K4-2-u3-C19","difficulty":2,"kind":"mc","stem":"석진이의 의견에 할 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"「수건 당번은 언제, 몇 사람이 하면 좋을까?」","correct":true},{"t":"「그건 말도 안 돼. 누가 그걸 해?」","mis":"K4-2-u3-X12"},{"t":"「수건은 무슨 색이 좋아?」","mis":"K4-2-u3-X13"},{"t":"「궁금한 건 없지만 질문 수를 채우려고 물어볼게.」","mis":"K4-2-u3-X14"}],"explanation":["의견을 더 낫게 하나요?","존중하는 말투인가요?","실천 방법을 물었어요."],"asset":{"type":"passage","lines":["주제 — 비 오는 날 현관 바닥이 미끄러운 문제를 어떻게 해결할까?","효주 — 현관 밖에서 우산을 털고 접어서 들어오자.","석진 — 비 오는 날 현관 수건 당번을 두자.","온하 — 물기를 빨아들이는 발판을 더 깔아 달라고 학교에 부탁하자.","솔비 — 현관을 지날 때 마음속으로 「조심하자」고 말하자."],"title":"효주네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#7','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C21',2,'mc','auto','모둠의 의견을 결정하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X20','K4-2-u3-X19','K4-2-u3-X03']::text[],false,'{"seq":7,"concept":"K4-2-u3-C21","difficulty":2,"kind":"mc","stem":"모둠의 의견을 결정하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"문제 해결에 도움이 되는지, 우리가 실천할 수 있는지 기준에 비추어 견준다","correct":true},{"t":"가위바위보로 빨리 정한다","mis":"K4-2-u3-X20"},{"t":"네 의견을 모두 합치면 언제나 가장 좋다","mis":"K4-2-u3-X19"},{"t":"목소리가 가장 큰 친구의 의견으로 정한다","mis":"K4-2-u3-X03"}],"explanation":["기준이 있나요?","「언제나」를 조심해요.","기준에 비추어 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#8','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C22',2,'mc','auto','효주네 모둠은 발판 의견을 어떻게 하기로 했나요?',ARRAY['K4-2-u3-X22','K4-2-u3-X19']::text[],false,'{"seq":8,"concept":"K4-2-u3-C22","difficulty":2,"kind":"mc","stem":"효주네 모둠은 발판 의견을 어떻게 하기로 했나요?","options":[{"t":"우리 힘만으로 할 수 없어 학교에 제안하기로 했다","correct":true},{"t":"각자 집에서 발판을 가져오기로 했다","mis":"K4-2-u3-X22"},{"t":"할 수 없는 일이니 그냥 잊기로 했다","mis":"K4-2-u3-X22"},{"t":"의견이 넷이니 모두 합쳐 정했다","mis":"K4-2-u3-X19"}],"explanation":["「따로 할 일」을 봐요.","우리 힘으로는 못 해요.","학교에 제안해요."],"asset":{"type":"passage","lines":["결정한 의견 — 현관 밖에서 우산 털고 접기 + 비 오는 날 등교 시간 수건 당번","결정한 까닭 — 두 의견이 서로 도와 바닥의 물을 줄이고, 우리가 할 수 있다","따로 할 일 — 발판은 우리 힘만으로 할 수 없어 학교에 제안하기로 했다"],"title":"효주네 모둠의 결정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#9','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C20',2,'mc','auto','질문을 받은 석진이가 「두 사람씩 요일을 나누어 맡으면 돼.」라고 답했어요. 이 일로 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u3-X23','K4-2-u3-X11']::text[],false,'{"seq":9,"concept":"K4-2-u3-C20","difficulty":2,"kind":"mc","stem":"질문을 받은 석진이가 「두 사람씩 요일을 나누어 맡으면 돼.」라고 답했어요. 이 일로 알 수 있는 것은 무엇인가요?","options":[{"t":"질문에 답하면서 의견이 더 구체적으로 다듬어졌다","correct":true},{"t":"질문을 받아서 의견이 나빠졌다","mis":"K4-2-u3-X23"},{"t":"의견을 고쳤으니 석진이가 토의에서 졌다","mis":"K4-2-u3-X23"},{"t":"질문은 토의 시간만 늘렸다","mis":"K4-2-u3-X11"}],"explanation":["질문 전의 의견을 떠올려요.","「두 사람씩 요일」이 더해졌어요.","의견이 자랐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_basic#10','kor',4,2,'u3','L04','g4_2_kor_u3_L04_basic','lesson_basic','K4-2-u3-C24',3,'error','auto','토의에 참여한 모습을 돌아보았어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X58','K4-2-u3-X03']::text[],false,'{"seq":10,"concept":"K4-2-u3-C24","difficulty":3,"kind":"error","stem":"토의에 참여한 모습을 돌아보았어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「결정한 의견이 내 의견과 달라서 나는 하지 않을래.」","correct":true,"mis_target":"K4-2-u3-X58"},{"t":"친구 가 — 「친구 말을 끝까지 들었어.」","mis":"K4-2-u3-X03"},{"t":"친구 나 — 「친구 의견에 어려운 점을 물었어.」","mis":"K4-2-u3-X03"}],"explanation":["끝까지 들었어요.","어려움을 물었어요.","결정은 함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#1','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C16',2,'blank','auto','「미끄러져 다칠 수 있다」는 현관 바닥 문제가 주는 (  )이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X16']::text[],false,'{"seq":1,"concept":"K4-2-u3-C16","difficulty":2,"kind":"blank","stem":"「미끄러져 다칠 수 있다」는 현관 바닥 문제가 주는 (  )이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"영향","correct":true},{"t":"까닭","mis":"K4-2-u3-X16"},{"t":"의견","mis":"K4-2-u3-X16"},{"t":"주제","mis":"K4-2-u3-X16"}],"explanation":["왜 그런가가 아니에요.","그 때문에 생기는 일이에요.","‘영향’이에요."],"asset":{"type":"passage","lines":["㉠ 젖은 우산과 신발에서 떨어진 물이 현관 바닥에 고인다","㉡ 미끄러져 다칠 수 있고, 조심하느라 현관이 붐빈다"],"title":"효주네 모둠이 정리한 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#2','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C15',2,'mc','auto','모둠 토의 주제로 알맞은 문제의 조건을 바르게 모은 것은 무엇인가요?',ARRAY['K4-2-u3-X02','K4-2-u3-X09']::text[],false,'{"seq":2,"concept":"K4-2-u3-C15","difficulty":2,"kind":"mc","stem":"모둠 토의 주제로 알맞은 문제의 조건을 바르게 모은 것은 무엇인가요?","options":[{"t":"우리 모두와 관련 있음 · 여러 의견이 나올 수 있음 · 우리가 해결에 나설 수 있음","correct":true},{"t":"답이 하나로 정해짐 · 나만 관련 있음 · 어려울수록 좋음","mis":"K4-2-u3-X02"},{"t":"가장 큰 문제 · 나라 전체의 일 · 한 번에 끝남","mis":"K4-2-u3-X09"},{"t":"선생님만 관련 있음 · 의견이 하나뿐 · 바로 끝남","mis":"K4-2-u3-X02"}],"explanation":["모두와 관련 있나요?","의견이 여럿 나오나요?","우리가 나설 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#3','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C18',3,'mc','auto','다온이네 모둠의 ㉱ 로운이의 의견에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X18','K4-2-u3-X10']::text[],false,'{"seq":3,"concept":"K4-2-u3-C18","difficulty":3,"kind":"mc","stem":"다온이네 모둠의 ㉱ 로운이의 의견에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"쉽게 할 수 있지만 작품을 단단히 붙여 주지 못해 문제 해결에 도움이 적다","correct":true},{"t":"가장 쉬우니 모둠의 의견으로 정해야 한다","mis":"K4-2-u3-X17"},{"t":"쉬운 의견이니 따져 보지 않고 버린다","mis":"K4-2-u3-X18"},{"t":"마음으로 하는 일이라 단점이 없다","mis":"K4-2-u3-X10"}],"explanation":["로운이의 의견대로 해 봐요.","작품이 덜 떨어지나요?","해결되는지도 따져요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#4','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C21',3,'mc','auto','다온이네 모둠에서 「㉮와 ㉯를 합치자」는 말이 나왔어요. 어떻게 하는 것이 알맞나요?',ARRAY['K4-2-u3-X19','K4-2-u3-X20']::text[],false,'{"seq":4,"concept":"K4-2-u3-C21","difficulty":3,"kind":"mc","stem":"다온이네 모둠에서 「㉮와 ㉯를 합치자」는 말이 나왔어요. 어떻게 하는 것이 알맞나요?","options":[{"t":"합친 의견도 문제 해결에 도움이 되는지, 실천할 수 있는지 같은 기준으로 따져 본다","correct":true},{"t":"합치면 언제나 가장 좋으니 바로 정한다","mis":"K4-2-u3-X19"},{"t":"합치는 김에 넷을 모두 합친다","mis":"K4-2-u3-X19"},{"t":"합칠지 말지는 가위바위보로 정한다","mis":"K4-2-u3-X20"}],"explanation":["합친 것도 의견이에요.","같은 기준을 써요.","따져 본 뒤에 정해요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#5','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C19',3,'mc','auto','다온이네 모둠의 ㉯ 하윤이의 의견에 할 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13','K4-2-u3-X14']::text[],false,'{"seq":5,"concept":"K4-2-u3-C19","difficulty":3,"kind":"mc","stem":"다온이네 모둠의 ㉯ 하윤이의 의견에 할 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"「좋은 생각이야. 그런데 당번이 결석하는 날은 누가 살피면 좋을까?」","correct":true},{"t":"「그건 귀찮아서 아무도 안 할걸?」","mis":"K4-2-u3-X12"},{"t":"「당번 이름표는 무슨 모양이야?」","mis":"K4-2-u3-X13"},{"t":"「질문할 건 없는데 그냥 아무거나 물어볼게.」","mis":"K4-2-u3-X14"}],"explanation":["존중하는 말로 시작해요.","어려움을 물어요.","의견이 더 단단해져요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#6','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C21',3,'ox','auto','모둠 의견이 넷이면 넷을 모두 합친 의견이 언제나 가장 좋아요.',ARRAY['K4-2-u3-X19']::text[],false,'{"seq":6,"concept":"K4-2-u3-C21","difficulty":3,"kind":"ox","stem":"모둠 의견이 넷이면 넷을 모두 합친 의견이 언제나 가장 좋아요.","answer":"X","reason_options":[{"t":"합친 의견도 해결에 도움이 되는지, 실천할 수 있는지 같은 기준으로 따져야 하기 때문에","correct":true},{"t":"의견이 많이 들어갈수록 더 좋은 의견이기 때문에","mis":"K4-2-u3-X19"}],"mis":"K4-2-u3-X19","explanation":["솔비의 의견은 넣지 않았어요.","합친 것도 따져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#7','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C17',3,'error','auto','의견을 마련할 때 스스로 물을 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X10']::text[],false,'{"seq":7,"concept":"K4-2-u3-C17","difficulty":3,"kind":"error","stem":"의견을 마련할 때 스스로 물을 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「내 의견이 가장 쉬운가만 물어보면 돼.」","correct":true,"mis_target":"K4-2-u3-X17"},{"t":"친구 가 — 「우리가 실천할 수 있는가?」","mis":"K4-2-u3-X10"},{"t":"친구 나 — 「의견의 단점도 생각했는가?」","mis":"K4-2-u3-X10"}],"explanation":["물을 것은 네 가지예요.","쉬운지만 물으면 안 돼요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#8','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C23',4,'mc','auto','다온이네 모둠이 ㉮와 ㉯를 합친 의견으로 결정했어요. 가장 구체적인 실천 계획은 무엇인가요?',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":8,"concept":"K4-2-u3-C23","difficulty":4,"kind":"mc","stem":"다온이네 모둠이 ㉮와 ㉯를 합친 의견으로 결정했어요. 가장 구체적인 실천 계획은 무엇인가요?","options":[{"t":"다음 주 월요일부터 게시판 당번 두 명이 아침 활동 전에 집게를 살피고 떨어진 작품을 다시 붙인다","correct":true},{"t":"게시판을 소중히 여기도록 모두 노력한다","mis":"K4-2-u3-X21"},{"t":"작품이 떨어지면 언젠가 다시 붙인다","mis":"K4-2-u3-X21"},{"t":"작품이 떨어지지 않게 모두 조심한다","mis":"K4-2-u3-X21"}],"explanation":["언제부터 하나요?","누가 하나요?","무엇을 하나요?"],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#9','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C16',4,'mc','auto','효주네 모둠이 의견을 모으기 전에 문제가 생긴 까닭을 먼저 정리한 것이 도움이 된 까닭은 무엇인가요?',ARRAY['K4-2-u3-X16','K4-2-u3-X11']::text[],false,'{"seq":9,"concept":"K4-2-u3-C16","difficulty":4,"kind":"mc","stem":"효주네 모둠이 의견을 모으기 전에 문제가 생긴 까닭을 먼저 정리한 것이 도움이 된 까닭은 무엇인가요?","options":[{"t":"까닭을 알아야 그 까닭을 줄이는 의견(우산 털기·수건 당번)을 떠올릴 수 있기 때문에","correct":true},{"t":"까닭과 영향은 같은 것이라 하나만 정리하면 되기 때문에","mis":"K4-2-u3-X16"},{"t":"까닭을 정리하면 질문할 필요가 없어지기 때문에","mis":"K4-2-u3-X11"},{"t":"영향이 클수록 의견이 쉬워지기 때문에","mis":"K4-2-u3-X16"}],"explanation":["까닭은 물이 고이는 것이에요.","물을 줄이면 돼요.","의견이 까닭에서 나왔어요."],"asset":{"type":"passage","lines":["㉠ 젖은 우산과 신발에서 떨어진 물이 현관 바닥에 고인다","㉡ 미끄러져 다칠 수 있고, 조심하느라 현관이 붐빈다"],"title":"효주네 모둠이 정리한 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L04_challenge#10','kor',4,2,'u3','L04','g4_2_kor_u3_L04_challenge','lesson_challenge','K4-2-u3-C18',4,'essay','teacher','다온이네 모둠에서 ㉱ 로운이의 의견이 가장 쉬운데도 알맞지 않은 까닭을 쓰고, ㉮~㉰ 가운데 알맞은 의견 하나를 골라 두 가지 기준에 비추어 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C18","difficulty":4,"kind":"essay","stem":"다온이네 모둠에서 ㉱ 로운이의 의견이 가장 쉬운데도 알맞지 않은 까닭을 쓰고, ㉮~㉰ 가운데 알맞은 의견 하나를 골라 두 가지 기준에 비추어 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉱는 마음속으로 비는 것이라 가장 쉽지만, 그렇게 해도 작품이 단단히 붙지 않아 문제 해결에 도움이 되지 않는다. ㉮가 알맞다. 집게로 집으면 작품이 덜 떨어져 문제 해결에 도움이 되고, 작은 집게는 우리 반이 준비해 실천할 수 있기 때문이다. ㉰는 떨어지지는 않지만 작품을 함께 보려는 게시판의 쓸모가 없어진다.","scoring_points":["㉱가 쉽지만 해결에 도움이 적다고 썼는가","알맞은 의견 하나를 골랐는가","「해결에 도움」과 「실천할 수 있음」 두 기준으로 까닭을 썼는가"]},"explanation":["쉬운지와 해결되는지 함께 봐요.","기준 두 가지를 써요.","까닭을 들어요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#1','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C26',1,'mc','auto','아정이와 친구들에게 어떤 문제가 있나요?',ARRAY['K4-2-u3-X25']::text[],false,'{"seq":1,"concept":"K4-2-u3-C26","difficulty":1,"kind":"mc","stem":"아정이와 친구들에게 어떤 문제가 있나요?","options":[{"t":"수업 전에 기다릴 곳이 없어 복도 바닥에 앉아 있다","correct":true},{"t":"숙제가 너무 많다","mis":"K4-2-u3-X25"},{"t":"방과 후 수업이 재미없다","mis":"K4-2-u3-X25"},{"t":"복도가 너무 넓다","mis":"K4-2-u3-X25"}],"explanation":["친구들이 어디에 있나요?","복도 바닥이에요.","기다릴 곳이 없어요."],"asset":{"type":"passage","lines":["1 방과 후 담당 선생님, 안녕하세요? 저는 4학년 아정입니다.","2 요즘 방과 후 수업이 시작되기 전까지 기다릴 곳이 없어","   많은 친구가 복도 바닥에 앉아 있습니다. 지나가는 사람과 부딪치기도 합니다.","3 수업이 끝난 빈 교실 하나를 기다리는 곳으로 열어 주시면 좋겠습니다.","4 그러면 복도가 붐비지 않아 안전하고, 기다리는 동안 숙제나 책 읽기를 할 수 있습니다.","5 읽어 주셔서 고맙습니다."],"title":"아정이의 글 「방과 후 수업을 기다리는 교실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#2','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C25',1,'mc','auto','아정이가 제안할 사람으로 가장 알맞은 사람은 누구인가요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":2,"concept":"K4-2-u3-C25","difficulty":1,"kind":"mc","stem":"아정이가 제안할 사람으로 가장 알맞은 사람은 누구인가요?","options":[{"t":"교실을 어떻게 쓸지 정할 수 있는 방과 후 담당 선생님","correct":true},{"t":"복도에서 부딪친 친구","mis":"K4-2-u3-X24"},{"t":"같은 반 짝","mis":"K4-2-u3-X24"},{"t":"아정이의 동생","mis":"K4-2-u3-X24"}],"explanation":["누가 교실을 열 수 있나요?","그 일을 정하는 사람이에요.","방과 후 담당 선생님이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#3','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C28',1,'ox','auto','「복도에 앉지 마세요.」는 「~하세요」로 끝나니 제안하는 글이에요.',ARRAY['K4-2-u3-X27']::text[],false,'{"seq":3,"concept":"K4-2-u3-C28","difficulty":1,"kind":"ox","stem":"「복도에 앉지 마세요.」는 「~하세요」로 끝나니 제안하는 글이에요.","answer":"X","reason_options":[{"t":"막기만 할 뿐 어디서 기다릴지 해결 방법과 이유가 없기 때문에","correct":true},{"t":"「~하세요」로 끝나면 모두 제안하는 글이기 때문에","mis":"K4-2-u3-X27"}],"mis":"K4-2-u3-X27","explanation":["쪽지대로 하면 어디로 가나요?","해결 방법이 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["「복도에 앉지 마세요.」"],"title":"다른 친구가 복도에 붙인 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#4','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C27',1,'mc','auto','제안하는 글에 들어가는 세 가지를 바르게 모은 것은 무엇인가요?',ARRAY['K4-2-u3-X31','K4-2-u3-X29','K4-2-u3-X26']::text[],false,'{"seq":4,"concept":"K4-2-u3-C27","difficulty":1,"kind":"mc","stem":"제안하는 글에 들어가는 세 가지를 바르게 모은 것은 무엇인가요?","options":[{"t":"문제 상황 · 제안하는 내용 · 제안하는 이유","correct":true},{"t":"문제 상황 · 속상한 마음 · 불만","mis":"K4-2-u3-X31"},{"t":"제목 · 날짜 · 그림","mis":"K4-2-u3-X29"},{"t":"등장인물 · 사건 · 배경","mis":"K4-2-u3-X26"}],"explanation":["무엇이 불편한가요?","무엇을 바라나요?","그러면 무엇이 좋아지나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#5','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C27',2,'match','auto','아정이의 글에서 글의 부분과 제안하는 글의 짜임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u3-C27","difficulty":2,"kind":"match","stem":"아정이의 글에서 글의 부분과 제안하는 글의 짜임을 알맞게 이으세요.","pairs":[{"l":"2 · 기다릴 곳이 없어 복도 바닥에 앉아 있다","r":"문제 상황"},{"l":"3 · 빈 교실 하나를 열어 주시면 좋겠다","r":"제안하는 내용"},{"l":"4 · 복도가 안전하고 숙제를 할 수 있다","r":"제안하는 이유"}],"mis":"K4-2-u3-X26","explanation":["불편한 점이에요.","바라는 점이에요.","좋아지는 점이에요."],"asset":{"type":"passage","lines":["1 방과 후 담당 선생님, 안녕하세요? 저는 4학년 아정입니다.","2 요즘 방과 후 수업이 시작되기 전까지 기다릴 곳이 없어","   많은 친구가 복도 바닥에 앉아 있습니다. 지나가는 사람과 부딪치기도 합니다.","3 수업이 끝난 빈 교실 하나를 기다리는 곳으로 열어 주시면 좋겠습니다.","4 그러면 복도가 붐비지 않아 안전하고, 기다리는 동안 숙제나 책 읽기를 할 수 있습니다.","5 읽어 주셔서 고맙습니다."],"title":"아정이의 글 「방과 후 수업을 기다리는 교실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#6','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C29',2,'mc','auto','제안하는 글을 쓰기 전에 생각할 내용을 바르게 모은 것은 무엇인가요?',ARRAY['K4-2-u3-X29','K4-2-u3-X31','K4-2-u3-X30']::text[],false,'{"seq":6,"concept":"K4-2-u3-C29","difficulty":2,"kind":"mc","stem":"제안하는 글을 쓰기 전에 생각할 내용을 바르게 모은 것은 무엇인가요?","options":[{"t":"제안이 드러나는 제목 · 누구에게 쓸지 · 문제를 보여 줄 그림이나 사진 · 전할 방법","correct":true},{"t":"글자 수 · 종이 색 · 글씨체","mis":"K4-2-u3-X29"},{"t":"속상한 마음 · 불만 · 탓할 사람","mis":"K4-2-u3-X31"},{"t":"받아들여질 날짜 · 받을 상 · 칭찬","mis":"K4-2-u3-X30"}],"explanation":["제목을 떠올려요.","누구에게 쓰나요?","어떻게 전하나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#7','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C30',2,'mc','auto','제안하는 글을 쓰면 좋은 점은 무엇인가요?',ARRAY['K4-2-u3-X30','K4-2-u3-X31']::text[],false,'{"seq":7,"concept":"K4-2-u3-C30","difficulty":2,"kind":"mc","stem":"제안하는 글을 쓰면 좋은 점은 무엇인가요?","options":[{"t":"얼굴을 보고 말하기 어려운 분께도 차분히 전할 수 있다","correct":true},{"t":"글로 쓰면 언제나 받아들여진다","mis":"K4-2-u3-X30"},{"t":"속상한 마음을 마음껏 쏟아 낼 수 있다","mis":"K4-2-u3-X31"},{"t":"어떤 문제든 글 한 장으로 바로 해결된다","mis":"K4-2-u3-X30"}],"explanation":["「언제나」를 조심해요.","불만을 쏟는 글이 아니에요.","차분히 전할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#8','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C31',2,'mc','auto','짝이 내 지우개를 말없이 자꾸 가져다 쓸 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X28']::text[],false,'{"seq":8,"concept":"K4-2-u3-C31","difficulty":2,"kind":"mc","stem":"짝이 내 지우개를 말없이 자꾸 가져다 쓸 때 알맞은 방법은 무엇인가요?","options":[{"t":"짝에게 직접 차분히 말한다","correct":true},{"t":"교장 선생님께 제안하는 글을 쓴다","mis":"K4-2-u3-X04"},{"t":"「지우개 쓰지 마세요」 쪽지를 붙인다","mis":"K4-2-u3-X28"},{"t":"전교 학생 자치회 안건으로 낸다","mis":"K4-2-u3-X04"}],"explanation":["두 사람 사이의 일이에요.","직접 말하면 돼요.","방법은 상황에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#9','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C25',2,'mc','auto','아정이가 한 일 가운데 「제안」에 해당하는 것은 무엇인가요?',ARRAY['K4-2-u3-X57','K4-2-u3-X25']::text[],false,'{"seq":9,"concept":"K4-2-u3-C25","difficulty":2,"kind":"mc","stem":"아정이가 한 일 가운데 「제안」에 해당하는 것은 무엇인가요?","options":[{"t":"빈 교실 하나를 기다리는 곳으로 열어 달라고 의견을 내놓았다","correct":true},{"t":"복도에 앉은 친구들에게 비키라고 명령했다","mis":"K4-2-u3-X57"},{"t":"방과 후 수업이 싫다고 불평했다","mis":"K4-2-u3-X57"},{"t":"복도에 앉은 친구 수를 세었다","mis":"K4-2-u3-X25"}],"explanation":["제안은 의견을 내놓는 것이에요.","무엇을 바랐나요?","빈 교실이에요."],"asset":{"type":"passage","lines":["1 방과 후 담당 선생님, 안녕하세요? 저는 4학년 아정입니다.","2 요즘 방과 후 수업이 시작되기 전까지 기다릴 곳이 없어","   많은 친구가 복도 바닥에 앉아 있습니다. 지나가는 사람과 부딪치기도 합니다.","3 수업이 끝난 빈 교실 하나를 기다리는 곳으로 열어 주시면 좋겠습니다.","4 그러면 복도가 붐비지 않아 안전하고, 기다리는 동안 숙제나 책 읽기를 할 수 있습니다.","5 읽어 주셔서 고맙습니다."],"title":"아정이의 글 「방과 후 수업을 기다리는 교실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_basic#10','kor',4,2,'u3','L06','g4_2_kor_u3_L06_basic','lesson_basic','K4-2-u3-C28',3,'error','auto','쪽지 「복도에 앉지 마세요.」를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X28','K4-2-u3-X27']::text[],false,'{"seq":10,"concept":"K4-2-u3-C28","difficulty":3,"kind":"error","stem":"쪽지 「복도에 앉지 마세요.」를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「짧게 막을수록 좋은 제안이니 이 쪽지가 가장 좋아.」","correct":true,"mis_target":"K4-2-u3-X28"},{"t":"친구 나 — 「어디서 기다릴지 해결 방법이 없어.」","mis":"K4-2-u3-X27"},{"t":"친구 다 — 「왜 그래야 하는지 이유도 없어.」","mis":"K4-2-u3-X27"}],"explanation":["방법이 있나요?","이유가 있나요?","친구 가가 알맞지 않아요."],"asset":{"type":"passage","lines":["「복도에 앉지 마세요.」"],"title":"다른 친구가 복도에 붙인 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#1','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C27',2,'sa','auto','제안하는 글에서 「그러면 무엇이 좋은가」를 쓰는 부분을 무엇이라고 하는지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u3-C27","difficulty":2,"kind":"sa","stem":"제안하는 글에서 「그러면 무엇이 좋은가」를 쓰는 부분을 무엇이라고 하는지 쓰세요.","answer":["제안하는 이유","이유"],"explanation":["불편한 점이 아니에요.","바라는 점도 아니에요.","‘제안하는 이유’예요."],"mis":"K4-2-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#2','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C25',2,'blank','auto','제안은 그 일을 정하거나 (  ) 수 있는 사람에게 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X24','K4-2-u3-X57']::text[],false,'{"seq":2,"concept":"K4-2-u3-C25","difficulty":2,"kind":"blank","stem":"제안은 그 일을 정하거나 (  ) 수 있는 사람에게 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"바꿀","correct":true},{"t":"모를","mis":"K4-2-u3-X24"},{"t":"탓할","mis":"K4-2-u3-X57"},{"t":"기다릴","mis":"K4-2-u3-X24"}],"explanation":["아정이는 방과 후 담당 선생님께 썼어요.","교실을 열 수 있는 분이에요.","‘바꿀’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#3','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C28',3,'mc','auto','쪽지를 제안하는 글로 고친다면 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X28','K4-2-u3-X27','K4-2-u3-X31']::text[],false,'{"seq":3,"concept":"K4-2-u3-C28","difficulty":3,"kind":"mc","stem":"쪽지를 제안하는 글로 고친다면 가장 알맞은 것은 무엇인가요?","options":[{"t":"「실내화를 놓을 칸이 모자랍니다. 반마다 실내화 주머니 걸이를 달아 주시면 좋겠습니다. 그러면 신발장 위가 정리되어 실내화가 떨어지지 않습니다.」","correct":true},{"t":"「신발장 위에 실내화를 절대 두지 마세요!」","mis":"K4-2-u3-X28"},{"t":"「신발장 위에 실내화를 두지 마세요. 꼭이요.」","mis":"K4-2-u3-X27"},{"t":"「실내화를 신발장 위에 두는 사람이 정말 싫어요.」","mis":"K4-2-u3-X31"}],"explanation":["막기만 하나요?","방법과 이유가 있나요?","첫째가 제안하는 글이에요."],"asset":{"type":"passage","lines":["「신발장 위에 실내화를 두지 마세요.」"],"title":"현관 신발장에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#4','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C30',3,'mc','auto','「글을 읽은 사람들도 문제에 관심을 두고 함께 나설 수 있다」를 보여 주는 예는 무엇인가요?',ARRAY['K4-2-u3-X30','K4-2-u3-X31','K4-2-u3-X04']::text[],false,'{"seq":4,"concept":"K4-2-u3-C30","difficulty":3,"kind":"mc","stem":"「글을 읽은 사람들도 문제에 관심을 두고 함께 나설 수 있다」를 보여 주는 예는 무엇인가요?","options":[{"t":"아정이의 글을 읽은 다른 선생님들도 기다리는 친구들을 함께 살피게 되었다","correct":true},{"t":"아정이의 글이 쓰자마자 그대로 받아들여졌다","mis":"K4-2-u3-X30"},{"t":"아정이가 속상한 마음을 다 털어놓아 시원했다","mis":"K4-2-u3-X31"},{"t":"아정이가 글을 쓴 뒤로 친구들과 이야기하지 않았다","mis":"K4-2-u3-X04"}],"explanation":["읽은 사람을 떠올려요.","관심을 두었어요.","함께 나섰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#5','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C29',3,'match','auto','아정이가 쓰기 전에 생각할 내용과 아정이의 경우를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u3-C29","difficulty":3,"kind":"match","stem":"아정이가 쓰기 전에 생각할 내용과 아정이의 경우를 알맞게 이으세요.","pairs":[{"l":"제목","r":"방과 후 수업을 기다리는 교실을 열어 주세요"},{"l":"누구에게","r":"방과 후 담당 선생님"},{"l":"그림이나 사진","r":"복도 바닥에 앉아 기다리는 모습"},{"l":"전할 방법","r":"교무실에 찾아가 직접 드리기"}],"mis":"K4-2-u3-X29","explanation":["제안이 드러나는 제목이에요.","바꿀 수 있는 사람이에요.","문제를 보여 주는 사진이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#6','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C31',3,'ox','auto','문제를 해결하려면 무조건 제안하는 글을 써야 해요.',ARRAY['K4-2-u3-X04']::text[],false,'{"seq":6,"concept":"K4-2-u3-C31","difficulty":3,"kind":"ox","stem":"문제를 해결하려면 무조건 제안하는 글을 써야 해요.","answer":"X","reason_options":[{"t":"두 사람 사이의 일처럼 직접 말하는 것이 알맞을 때도 있기 때문에","correct":true},{"t":"글로 써야만 문제가 해결되기 때문에","mis":"K4-2-u3-X04"}],"mis":"K4-2-u3-X04","explanation":["지우개 일을 떠올려요.","직접 말하면 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#7','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C26',3,'mc','auto','문제 상황이 가장 구체적으로 드러난 문장은 무엇인가요?',ARRAY['K4-2-u3-X25','K4-2-u3-X31','K4-2-u3-X26']::text[],false,'{"seq":7,"concept":"K4-2-u3-C26","difficulty":3,"kind":"mc","stem":"문제 상황이 가장 구체적으로 드러난 문장은 무엇인가요?","options":[{"t":"「수업 전에 기다릴 곳이 없어 많은 친구가 복도 바닥에 앉아 있고, 지나가는 사람과 부딪치기도 합니다.」","correct":true},{"t":"「복도가 좀 그래요.」","mis":"K4-2-u3-X25"},{"t":"「방과 후 수업이 싫어요.」","mis":"K4-2-u3-X31"},{"t":"「빈 교실을 열어 주시면 좋겠습니다.」","mis":"K4-2-u3-X26"}],"explanation":["누가, 어디서, 어떤 불편?","넷째는 바라는 점이에요.","첫째가 구체적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#8','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C27',4,'mc','auto','하린이의 글에서 문제 상황 · 제안하는 내용 · 제안하는 이유를 차례대로 바르게 찾은 것은 무엇인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X25']::text[],false,'{"seq":8,"concept":"K4-2-u3-C27","difficulty":4,"kind":"mc","stem":"하린이의 글에서 문제 상황 · 제안하는 내용 · 제안하는 이유를 차례대로 바르게 찾은 것은 무엇인가요?","options":[{"t":"2 · 3 · 4","correct":true},{"t":"3 · 2 · 4","mis":"K4-2-u3-X26"},{"t":"2 · 4 · 3","mis":"K4-2-u3-X26"},{"t":"1 · 3 · 4","mis":"K4-2-u3-X25"}],"explanation":["줄이 긴 것이 불편이에요.","열면 어떨까요가 바람이에요.","붐비지 않는 것이 이유예요."],"asset":{"type":"passage","lines":["1 도서실 담당 선생님, 안녕하세요? 저는 4학년 하린입니다.","2 점심시간에 도서실 문이 닫혀 있어서, 책을 빌리려는 친구들이","   쉬는 시간마다 한꺼번에 몰려 줄이 깁니다.","3 점심시간에도 도서실을 열고, 도서 도우미가 돌아가며 도우면 어떨까요?","4 그러면 책을 빌리는 친구들이 나뉘어 쉬는 시간에 붐비지 않고,","   점심을 먹은 뒤 조용히 책을 읽을 곳도 생깁니다."],"title":"하린이의 글 「점심시간에도 도서실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#9','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C25',4,'mc','auto','하린이가 도서실 담당 선생님께 글을 쓴 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X24','K4-2-u3-X57']::text[],false,'{"seq":9,"concept":"K4-2-u3-C25","difficulty":4,"kind":"mc","stem":"하린이가 도서실 담당 선생님께 글을 쓴 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"점심시간에 도서실을 열지 정할 수 있는 분이기 때문에","correct":true},{"t":"하린이와 가장 친한 선생님이기 때문에","mis":"K4-2-u3-X24"},{"t":"책을 가장 많이 읽는 분이기 때문에","mis":"K4-2-u3-X24"},{"t":"선생님께 명령하면 바로 바뀌기 때문에","mis":"K4-2-u3-X57"}],"explanation":["누가 정할 수 있나요?","도서실을 맡은 분이에요.","바꿀 수 있는 사람이에요."],"asset":{"type":"passage","lines":["1 도서실 담당 선생님, 안녕하세요? 저는 4학년 하린입니다.","2 점심시간에 도서실 문이 닫혀 있어서, 책을 빌리려는 친구들이","   쉬는 시간마다 한꺼번에 몰려 줄이 깁니다.","3 점심시간에도 도서실을 열고, 도서 도우미가 돌아가며 도우면 어떨까요?","4 그러면 책을 빌리는 친구들이 나뉘어 쉬는 시간에 붐비지 않고,","   점심을 먹은 뒤 조용히 책을 읽을 곳도 생깁니다."],"title":"하린이의 글 「점심시간에도 도서실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L06_challenge#10','kor',4,2,'u3','L06','g4_2_kor_u3_L06_challenge','lesson_challenge','K4-2-u3-C28',4,'essay','teacher','쪽지가 제안하는 글로 부족한 까닭을 쓰고, 문제 상황 · 제안하는 내용 · 제안하는 이유가 드러나게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C28","difficulty":4,"kind":"essay","stem":"쪽지가 제안하는 글로 부족한 까닭을 쓰고, 문제 상황 · 제안하는 내용 · 제안하는 이유가 드러나게 고쳐 쓰세요.","answer_guide":{"answer":"예: 이 쪽지는 신발장 위에 두지 말라고 막기만 할 뿐, 실내화를 어디에 두면 좋을지 해결 방법과 그래야 하는 이유가 없다. 고쳐 쓰면 「실내화를 놓을 칸이 모자라 신발장 위에 두는 친구가 많습니다. 반마다 실내화 주머니 걸이를 달아 주시면 좋겠습니다. 그러면 신발장 위가 정리되고 실내화가 떨어지지 않습니다.」","scoring_points":["막기만 하고 해결 방법과 이유가 없다고 썼는가","문제 상황과 제안하는 내용을 썼는가","제안하는 이유를 썼는가"]},"explanation":["막기만 하나요?","방법을 내놓아요.","좋아지는 점을 써요."],"asset":{"type":"passage","lines":["「신발장 위에 실내화를 두지 마세요.」"],"title":"현관 신발장에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#1','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C32',1,'match','auto','제안하는 글을 쓰는 과정을 차례대로 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u3-C32","difficulty":1,"kind":"match","stem":"제안하는 글을 쓰는 과정을 차례대로 이으세요.","pairs":[{"l":"첫째","r":"문제 상황 파악하기"},{"l":"둘째","r":"누구에게 제안할지 생각하기"},{"l":"셋째","r":"제안하는 내용을 정하고 이유 설명하기"},{"l":"넷째","r":"제안하는 글 쓰기"}],"mis":"K4-2-u3-X32","explanation":["무엇이 문제인지 먼저 알아요.","누구에게 할지 정해요.","내용과 이유를 정하고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#2','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C34',1,'mc','auto','여원이는 누구에게 제안하면 좋을까요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":2,"concept":"K4-2-u3-C34","difficulty":1,"kind":"mc","stem":"여원이는 누구에게 제안하면 좋을까요?","options":[{"t":"버스 정류장 안내판을 맡아 관리하는 시청의 담당자","correct":true},{"t":"함께 간 할머니","mis":"K4-2-u3-X24"},{"t":"버스를 운전하는 기사님","mis":"K4-2-u3-X24"},{"t":"옆에 계셨던 아저씨","mis":"K4-2-u3-X24"}],"explanation":["안내판을 누가 바꾸나요?","맡아 관리하는 곳이에요.","시청의 담당자예요."],"asset":{"type":"passage","lines":["1 오늘 할머니와 도서관에 가려고 버스 정류장에 갔다.","2 버스 노선 안내판이 너무 높이 붙어 있고 글자가 작아서,","   할머니도 나도 탈 버스를 찾기 어려웠다.","3 옆에 계신 아저씨께 여쭈어 보고서야 버스를 탈 수 있었다.","4 다른 어린이나 어르신도 같은 불편을 겪지 않을까? 바꿀 방법은 없을까?"],"title":"여원의 일기 — 정류장에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#3','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C33',1,'ox','auto','글을 쓰다가 이유가 약한 것을 알게 되면 앞 단계로 돌아가 다시 생각해도 돼요.',ARRAY['K4-2-u3-X33']::text[],false,'{"seq":3,"concept":"K4-2-u3-C33","difficulty":1,"kind":"ox","stem":"글을 쓰다가 이유가 약한 것을 알게 되면 앞 단계로 돌아가 다시 생각해도 돼요.","answer":"O","reason_options":[{"t":"쓰는 과정의 차례는 길잡이라서 필요하면 되돌아가 고칠 수 있기 때문에","correct":true},{"t":"한번 지나간 단계로는 다시 돌아가면 안 되기 때문에","mis":"K4-2-u3-X33"}],"mis":"K4-2-u3-X33","explanation":["차례는 길잡이예요.","되돌아가도 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#4','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C38',1,'mc','auto','제안하는 내용을 나타낼 때 쓰는 표현은 무엇인가요?',ARRAY['K4-2-u3-X40','K4-2-u3-X39','K4-2-u3-X31']::text[],false,'{"seq":4,"concept":"K4-2-u3-C38","difficulty":1,"kind":"mc","stem":"제안하는 내용을 나타낼 때 쓰는 표현은 무엇인가요?","options":[{"t":"「……면 좋겠습니다」","correct":true},{"t":"「왜냐하면 ……때문입니다」","mis":"K4-2-u3-X40"},{"t":"「무조건 ……하세요」","mis":"K4-2-u3-X39"},{"t":"「……해서 너무 속상합니다」","mis":"K4-2-u3-X31"}],"explanation":["바라는 것을 말해요.","왜냐하면은 이유 표현이에요.","좋겠습니다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#5','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C35',2,'mc','auto','여원이의 문제 상황에 알맞은 제안 내용은 무엇인가요?',ARRAY['K4-2-u3-X34','K4-2-u3-X35']::text[],false,'{"seq":5,"concept":"K4-2-u3-C35","difficulty":2,"kind":"mc","stem":"여원이의 문제 상황에 알맞은 제안 내용은 무엇인가요?","options":[{"t":"어린이와 어르신 눈높이에 안내판을 하나 더 달아 주세요","correct":true},{"t":"정류장마다 안내하는 사람을 하루 종일 세워 주세요","mis":"K4-2-u3-X34"},{"t":"버스를 없애고 모두 걸어 다니게 해 주세요","mis":"K4-2-u3-X35"},{"t":"할머니가 버스를 타지 않게 해 주세요","mis":"K4-2-u3-X35"}],"explanation":["문제를 바로 푸나요?","실제로 할 수 있나요?","눈높이 안내판이에요."],"asset":{"type":"passage","lines":["1 오늘 할머니와 도서관에 가려고 버스 정류장에 갔다.","2 버스 노선 안내판이 너무 높이 붙어 있고 글자가 작아서,","   할머니도 나도 탈 버스를 찾기 어려웠다.","3 옆에 계신 아저씨께 여쭈어 보고서야 버스를 탈 수 있었다.","4 다른 어린이나 어르신도 같은 불편을 겪지 않을까? 바꿀 방법은 없을까?"],"title":"여원의 일기 — 정류장에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#6','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C36',2,'mc','auto','여원이의 두 이유 가운데 더 알맞은 것과 그 까닭은 무엇인가요?',ARRAY['K4-2-u3-X36','K4-2-u3-X37']::text[],false,'{"seq":6,"concept":"K4-2-u3-C36","difficulty":2,"kind":"mc","stem":"여원이의 두 이유 가운데 더 알맞은 것과 그 까닭은 무엇인가요?","options":[{"t":"㉯ — 제안대로 하면 여러 사람에게 무엇이 좋아지는지 보여 준다","correct":true},{"t":"둘 다 「왜냐하면」을 썼으니 똑같다","mis":"K4-2-u3-X36"},{"t":"㉮ — 내가 겪은 불편이니 가장 알맞다","mis":"K4-2-u3-X37"},{"t":"㉮ — 「왜냐하면」이 맨 앞에 있으니 알맞다","mis":"K4-2-u3-X36"}],"explanation":["「왜냐하면」만 보지 않아요.","누가 좋아지나요?","㉯는 여러 사람이에요."],"asset":{"type":"passage","lines":["㉮ 왜냐하면 제가 키가 작아서 안내판을 보기 불편하기 때문입니다.","㉯ 왜냐하면 어린이와 어르신, 휠체어를 탄 분까지 누구나","   스스로 탈 버스를 찾을 수 있기 때문입니다."],"title":"여원이가 떠올린 두 가지 이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#7','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C39',2,'mc','auto','제안하는 글에 알맞게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u3-X31','K4-2-u3-X39']::text[],false,'{"seq":7,"concept":"K4-2-u3-C39","difficulty":2,"kind":"mc","stem":"제안하는 글에 알맞게 쓴 문장은 무엇인가요?","options":[{"t":"「글자를 조금 더 크게 해 주시면 모두에게 도움이 될 것 같습니다.」","correct":true},{"t":"「이런 안내판을 만든 사람은 생각이 없나 봐요.」","mis":"K4-2-u3-X31"},{"t":"「내일까지 무조건 고쳐 놓으세요.」","mis":"K4-2-u3-X39"},{"t":"「안 바꿔 주시면 날마다 글을 보낼 거예요.」","mis":"K4-2-u3-X39"}],"explanation":["읽는 사람의 기분을 생각해요.","탓하거나 억지로 요구하지 않아요.","예의 있게 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#8','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C40',2,'mc','auto','제안이 받아들여지기 어렵다는 답을 받는다면 어떻게 하는 것이 알맞나요?',ARRAY['K4-2-u3-X41','K4-2-u3-X30']::text[],false,'{"seq":8,"concept":"K4-2-u3-C40","difficulty":2,"kind":"mc","stem":"제안이 받아들여지기 어렵다는 답을 받는다면 어떻게 하는 것이 알맞나요?","options":[{"t":"받아들여지기 어려운 까닭을 살펴 제안을 고치거나 다른 방법을 찾는다","correct":true},{"t":"제안하는 글은 쓸모없으니 다시는 쓰지 않는다","mis":"K4-2-u3-X41"},{"t":"받아들여질 때까지 같은 글을 날마다 보낸다","mis":"K4-2-u3-X41"},{"t":"글로 썼으니 꼭 받아들여야 한다고 따진다","mis":"K4-2-u3-X30"}],"explanation":["답에 적힌 까닭을 봐요.","고칠 실마리예요.","다른 방법도 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#9','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C37',2,'mc','auto','여원이의 글 제목으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X42','K4-2-u3-X31']::text[],false,'{"seq":9,"concept":"K4-2-u3-C37","difficulty":2,"kind":"mc","stem":"여원이의 글 제목으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「버스 정류장 안내판을 눈높이에 맞춰 주세요」","correct":true},{"t":"「할머니와 함께한 토요일」","mis":"K4-2-u3-X42"},{"t":"「정류장이 정말 싫어요」","mis":"K4-2-u3-X31"},{"t":"「여원이의 하루」","mis":"K4-2-u3-X42"}],"explanation":["무엇을 제안하나요?","제목에 드러나야 해요.","첫째 제목이에요."],"asset":{"type":"passage","lines":["1 오늘 할머니와 도서관에 가려고 버스 정류장에 갔다.","2 버스 노선 안내판이 너무 높이 붙어 있고 글자가 작아서,","   할머니도 나도 탈 버스를 찾기 어려웠다.","3 옆에 계신 아저씨께 여쭈어 보고서야 버스를 탈 수 있었다.","4 다른 어린이나 어르신도 같은 불편을 겪지 않을까? 바꿀 방법은 없을까?"],"title":"여원의 일기 — 정류장에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_basic#10','kor',4,2,'u3','L07','g4_2_kor_u3_L07_basic','lesson_basic','K4-2-u3-C36',3,'error','auto','여원이의 두 이유를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X36','K4-2-u3-X37']::text[],false,'{"seq":10,"concept":"K4-2-u3-C36","difficulty":3,"kind":"error","stem":"여원이의 두 이유를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉮도 ‘왜냐하면’으로 시작하니 ㉯만큼 알맞은 이유야.」","correct":true,"mis_target":"K4-2-u3-X36"},{"t":"친구 가 — 「㉯는 누구에게 무엇이 좋아지는지 보여 줘.」","mis":"K4-2-u3-X37"},{"t":"친구 나 — 「㉮는 내 불편만 말하고 있어.」","mis":"K4-2-u3-X37"}],"explanation":["「왜냐하면」은 표현일 뿐이에요.","좋아지는 점을 봐요.","친구 다가 알맞지 않아요."],"asset":{"type":"passage","lines":["㉮ 왜냐하면 제가 키가 작아서 안내판을 보기 불편하기 때문입니다.","㉯ 왜냐하면 어린이와 어르신, 휠체어를 탄 분까지 누구나","   스스로 탈 버스를 찾을 수 있기 때문입니다."],"title":"여원이가 떠올린 두 가지 이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#1','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C32',2,'sa','auto','제안하는 글을 쓰는 과정에서 맨 처음 할 일을 쓰세요. (○○ ○○ 파악하기)','{}'::text[],false,'{"seq":1,"concept":"K4-2-u3-C32","difficulty":2,"kind":"sa","stem":"제안하는 글을 쓰는 과정에서 맨 처음 할 일을 쓰세요. (○○ ○○ 파악하기)","answer":["문제 상황 파악하기","문제 상황 파악","문제상황 파악하기","문제 상황"],"explanation":["무엇이 불편한지 알아야 해요.","그래야 누구에게 할지 정해요.","‘문제 상황 파악하기’예요."],"mis":"K4-2-u3-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#2','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C38',2,'blank','auto','이유를 나타낼 때 「왜냐하면 ……(  )」처럼 써요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X40']::text[],false,'{"seq":2,"concept":"K4-2-u3-C38","difficulty":2,"kind":"blank","stem":"이유를 나타낼 때 「왜냐하면 ……(  )」처럼 써요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"때문입니다","correct":true},{"t":"좋겠습니다","mis":"K4-2-u3-X40"},{"t":"어떨까요","mis":"K4-2-u3-X40"},{"t":"합시다","mis":"K4-2-u3-X40"}],"explanation":["이유 표현이에요.","왜냐하면과 짝이에요.","‘때문입니다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#3','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C35',3,'mc','auto','하린이의 문제 상황에 알맞은 제안 내용은 무엇인가요?',ARRAY['K4-2-u3-X34','K4-2-u3-X35']::text[],false,'{"seq":3,"concept":"K4-2-u3-C35","difficulty":3,"kind":"mc","stem":"하린이의 문제 상황에 알맞은 제안 내용은 무엇인가요?","options":[{"t":"점심시간에도 도서실을 열고 도서 도우미가 돌아가며 돕기","correct":true},{"t":"도서실 선생님이 점심도 드시지 않고 날마다 혼자 도서실을 지키게 하기","mis":"K4-2-u3-X34"},{"t":"줄이 길지 않게 책을 빌리지 못하게 하기","mis":"K4-2-u3-X35"},{"t":"쉬는 시간을 아예 없애기","mis":"K4-2-u3-X35"}],"explanation":["문제를 바로 푸나요?","실제로 할 수 있나요?","도우미가 돌아가며 도와요."],"asset":{"type":"passage","lines":["1 도서실 담당 선생님, 안녕하세요? 저는 4학년 하린입니다.","2 점심시간에 도서실 문이 닫혀 있어서, 책을 빌리려는 친구들이","   쉬는 시간마다 한꺼번에 몰려 줄이 깁니다.","3 점심시간에도 도서실을 열고, 도서 도우미가 돌아가며 도우면 어떨까요?","4 그러면 책을 빌리는 친구들이 나뉘어 쉬는 시간에 붐비지 않고,","   점심을 먹은 뒤 조용히 책을 읽을 곳도 생깁니다."],"title":"하린이의 글 「점심시간에도 도서실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#4','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C36',3,'mc','auto','하린이의 두 이유 가운데 더 알맞은 것과 그 까닭은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X36','K4-2-u3-X40']::text[],false,'{"seq":4,"concept":"K4-2-u3-C36","difficulty":3,"kind":"mc","stem":"하린이의 두 이유 가운데 더 알맞은 것과 그 까닭은 무엇인가요?","options":[{"t":"㉯ — 줄이 짧아지고 더 많은 친구가 책을 빌릴 수 있어 여러 사람에게 좋아지는 점을 보여 준다","correct":true},{"t":"㉮ — 내가 좋아하는 것이니 가장 솔직한 이유다","mis":"K4-2-u3-X37"},{"t":"둘 다 「왜냐하면」으로 시작하니 똑같다","mis":"K4-2-u3-X36"},{"t":"둘 다 알맞지 않다 — 이유에는 「왜냐하면」을 쓰면 안 된다","mis":"K4-2-u3-X40"}],"explanation":["내 취향은 이유로 약해요.","누가 좋아지나요?","㉯가 더 알맞아요."],"asset":{"type":"passage","lines":["㉮ 왜냐하면 제가 책을 아주 좋아하기 때문입니다.","㉯ 왜냐하면 책을 빌리는 친구들이 나뉘어 줄이 짧아지고,","   더 많은 친구가 책을 빌릴 수 있기 때문입니다."],"title":"하린이가 떠올린 두 가지 이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#5','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C40',3,'ox','auto','예의 있게 쓴 제안은 언제나 받아들여져요.',ARRAY['K4-2-u3-X30']::text[],false,'{"seq":5,"concept":"K4-2-u3-C40","difficulty":3,"kind":"ox","stem":"예의 있게 쓴 제안은 언제나 받아들여져요.","answer":"X","reason_options":[{"t":"까닭이 있어 받아들여지지 않을 때도 있기 때문에","correct":true},{"t":"예의 있게 쓰면 꼭 받아들여야 하기 때문에","mis":"K4-2-u3-X30"}],"mis":"K4-2-u3-X30","explanation":["답글을 떠올려요.","받아들여지지 않을 수도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#6','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C34',3,'mc','auto','미술실 물감 통의 뚜껑이 잘 닫히지 않아 물감이 자주 마른다면 누구에게 제안하는 것이 가장 알맞나요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":6,"concept":"K4-2-u3-C34","difficulty":3,"kind":"mc","stem":"미술실 물감 통의 뚜껑이 잘 닫히지 않아 물감이 자주 마른다면 누구에게 제안하는 것이 가장 알맞나요?","options":[{"t":"미술실 물품을 맡아 준비하시는 선생님","correct":true},{"t":"물감을 함께 쓰는 짝","mis":"K4-2-u3-X24"},{"t":"물감을 좋아하는 옆 반 친구","mis":"K4-2-u3-X24"},{"t":"물감 그림을 칭찬해 주신 이웃 어른","mis":"K4-2-u3-X24"}],"explanation":["누가 물감 통을 바꿀 수 있나요?","미술실 물품을 맡은 분이에요.","그분께 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#7','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C38',3,'error','auto','제안하는 표현을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X40']::text[],false,'{"seq":7,"concept":"K4-2-u3-C38","difficulty":3,"kind":"error","stem":"제안하는 표현을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「표현은 외워서 어느 문장에나 ‘……합시다’를 똑같이 넣어야 해.」","correct":true,"mis_target":"K4-2-u3-X40"},{"t":"친구 가 — 「문장에 어울리는 제안 표현을 골라 써.」","mis":"K4-2-u3-X40"},{"t":"친구 다 — 「‘……면 어떨까요?’도 제안하는 표현이야.」","mis":"K4-2-u3-X40"}],"explanation":["표현은 외우는 것이 아니에요.","어울리는 것을 골라요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#8','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C33',4,'mc','auto','여원이가 글을 쓰다가 「㉮는 내 불편만 말하네」라고 알게 되었어요. 어떻게 하는 것이 가장 알맞나요?',ARRAY['K4-2-u3-X33','K4-2-u3-X32','K4-2-u3-X36']::text[],false,'{"seq":8,"concept":"K4-2-u3-C33","difficulty":4,"kind":"mc","stem":"여원이가 글을 쓰다가 「㉮는 내 불편만 말하네」라고 알게 되었어요. 어떻게 하는 것이 가장 알맞나요?","options":[{"t":"셋째 단계로 돌아가 여러 사람에게 무엇이 좋아지는지 이유를 다시 생각한다","correct":true},{"t":"이미 넷째 단계라 고칠 수 없으니 그대로 쓴다","mis":"K4-2-u3-X33"},{"t":"처음부터 다른 문제 상황을 새로 고른다","mis":"K4-2-u3-X32"},{"t":"「왜냐하면」을 한 번 더 붙여 이유를 강하게 만든다","mis":"K4-2-u3-X36"}],"explanation":["이유가 약해요.","이유를 정하는 단계가 있어요.","되돌아가도 돼요."],"asset":{"type":"passage","lines":["㉮ 왜냐하면 제가 키가 작아서 안내판을 보기 불편하기 때문입니다.","㉯ 왜냐하면 어린이와 어르신, 휠체어를 탄 분까지 누구나","   스스로 탈 버스를 찾을 수 있기 때문입니다."],"title":"여원이가 떠올린 두 가지 이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#9','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C39',4,'mc','auto','여원이의 제안이 받아들여진 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X39','K4-2-u3-X36','K4-2-u3-X30']::text[],false,'{"seq":9,"concept":"K4-2-u3-C39","difficulty":4,"kind":"mc","stem":"여원이의 제안이 받아들여진 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"겪은 문제를 구체적으로 쓰고, 여러 사람에게 좋아지는 점을 예의 있게 전했다","correct":true},{"t":"무조건 고쳐 놓으라고 강하게 요구했다","mis":"K4-2-u3-X39"},{"t":"「왜냐하면」을 여러 번 썼다","mis":"K4-2-u3-X36"},{"t":"글로 쓰면 언제나 받아들여지기 때문이다","mis":"K4-2-u3-X30"}],"explanation":["글의 문제 상황을 봐요.","이유를 봐요.","말투도 봐요."],"asset":{"type":"passage","lines":["1 ○○시청 버스 정류장 담당자님, 안녕하세요? 저는 4학년 여원입니다.","2 지난 토요일 정류장에 갔는데, 노선 안내판이 높이 붙어 있고","   글자가 작아서 탈 버스를 찾기 어려웠습니다.","3 어린이와 어르신 눈높이에 안내판을 하나 더 달고, 글자를 크게 해 주시면 좋겠습니다.","4 왜냐하면 누구나 스스로 탈 버스를 찾을 수 있기 때문입니다.","5 정류장을 이용하는 모든 사람을 위해 제 제안을 살펴봐 주시기를 부탁드립니다."],"title":"여원이의 글 「버스 정류장 안내판을 눈높이에 맞춰 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L07_challenge#10','kor',4,2,'u3','L07','g4_2_kor_u3_L07_challenge','lesson_challenge','K4-2-u3-C36',4,'essay','teacher','하린이의 이유 ㉮보다 ㉯가 더 알맞은 까닭을 쓰고, 하린이의 제안을 뒷받침할 이유를 하나 더 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C36","difficulty":4,"kind":"essay","stem":"하린이의 이유 ㉮보다 ㉯가 더 알맞은 까닭을 쓰고, 하린이의 제안을 뒷받침할 이유를 하나 더 쓰세요.","answer_guide":{"answer":"예: ㉮는 하린이가 책을 좋아한다는 내 취향만 말해서, 제안대로 하면 다른 사람에게 무엇이 좋아지는지 알 수 없다. ㉯는 줄이 짧아지고 더 많은 친구가 책을 빌릴 수 있다는 점을 보여 주어 더 알맞다. 이유를 하나 더 쓰면 「점심을 먹은 뒤 조용히 책을 읽을 곳이 생겨 쉬는 시간에 복도가 덜 붐빕니다.」","scoring_points":["㉮가 내 취향만 말한다고 썼는가","㉯가 여러 사람에게 좋아지는 점을 보여 준다고 썼는가","좋아지는 점이 드러나는 이유를 하나 더 썼는가"]},"explanation":["누가 좋아지나요?","「왜냐하면」만 보지 않아요.","좋아지는 점을 더해요."],"asset":{"type":"passage","lines":["㉮ 왜냐하면 제가 책을 아주 좋아하기 때문입니다.","㉯ 왜냐하면 책을 빌리는 친구들이 나뉘어 줄이 짧아지고,","   더 많은 친구가 책을 빌릴 수 있기 때문입니다."],"title":"하린이가 떠올린 두 가지 이유"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#1','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C41',1,'mc','auto','이 글의 제안하는 내용과 이유를 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u3-X06','K4-2-u3-X35']::text[],false,'{"seq":1,"concept":"K4-2-u3-C41","difficulty":1,"kind":"mc","stem":"이 글의 제안하는 내용과 이유를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"낮은 반납함을 하나 더 두자 — 동생들도 스스로 책을 돌려줄 수 있다","correct":true},{"t":"반납함 입구가 높다 — 동생들이 발끝을 든다","mis":"K4-2-u3-X06"},{"t":"도서관을 새로 짓자 — 책이 많아진다","mis":"K4-2-u3-X35"},{"t":"반납함을 없애자 — 책을 돌려주지 않아도 된다","mis":"K4-2-u3-X35"}],"explanation":["무엇을 바라나요?","그러면 무엇이 좋아지나요?","둘을 짝지어요."],"asset":{"type":"passage","lines":["1 어린이 도서관 관장님께 — 저는 이 도서관을 자주 찾는 4학년 학생입니다.","2 책 반납함 입구가 높아서 1학년 동생들은 발끝을 들어도 책을 넣기 어렵습니다.","3 입구가 낮은 반납함을 하나 더 두시면 좋겠습니다.","4 그러면 어린 동생들도 누구의 도움 없이 스스로 책을 돌려줄 수 있습니다."],"title":"한 어린이가 쓴 제안하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#2','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C42',1,'mc','auto','제안하는 글로 해결하기에 가장 알맞은 문제 상황은 무엇인가요?',ARRAY['K4-2-u3-X43']::text[],false,'{"seq":2,"concept":"K4-2-u3-C42","difficulty":1,"kind":"mc","stem":"제안하는 글로 해결하기에 가장 알맞은 문제 상황은 무엇인가요?","options":[{"t":"㉮ — 많은 친구가 겪고, 바꿀 수 있는 분께 제안할 수 있다","correct":true},{"t":"㉯ — 모든 사람이 겪으니 가장 큰 문제다","mis":"K4-2-u3-X43"},{"t":"㉰ — 내 마음이 가장 속상하다","mis":"K4-2-u3-X43"},{"t":"셋 다 똑같이 알맞다","mis":"K4-2-u3-X43"}],"explanation":["누구에게 제안하면 바뀌나요?","날씨는 바꿀 수 없어요.","㉮예요."],"asset":{"type":"passage","lines":["㉮ 운동장 수돗가에 비누가 없어서 체육 시간 뒤에 손을 물로만 헹군다","㉯ 우리나라의 여름이 너무 덥다","㉰ 짝이 내 그림을 보고 웃어서 속상했다"],"title":"선재가 떠올린 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#3','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C47',1,'ox','auto','「비누 걸이가 튼튼합니다.」는 사람이 나오지 않아서 어색한 문장이에요.',ARRAY['K4-2-u3-X47']::text[],false,'{"seq":3,"concept":"K4-2-u3-C47","difficulty":1,"kind":"ox","stem":"「비누 걸이가 튼튼합니다.」는 사람이 나오지 않아서 어색한 문장이에요.","answer":"X","reason_options":[{"t":"「무엇이」 칸에는 물건도 올 수 있어 무엇이 + 어떠하다로 바르게 짜인 문장이기 때문에","correct":true},{"t":"「누가/무엇이」 칸에는 사람만 와야 하기 때문에","mis":"K4-2-u3-X47"}],"mis":"K4-2-u3-X47","explanation":["「무엇이」를 떠올려요.","비누 걸이도 「무엇」이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#4','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C45',1,'mc','auto','「물이 차갑습니다.」는 어떤 짜임의 문장인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":4,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"「물이 차갑습니다.」는 어떤 짜임의 문장인가요?","options":[{"t":"무엇이 + 어떠하다","correct":true},{"t":"누가 + 어찌하다","mis":"K4-2-u3-X45"},{"t":"무엇이 + 무엇이다","mis":"K4-2-u3-X45"},{"t":"누가 + 무엇이다","mis":"K4-2-u3-X45"}],"explanation":["물은 「무엇」이에요.","차갑다는 모습이에요.","어떠하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#5','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C43',2,'mc','auto','선재의 제안을 뒷받침할 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X38']::text[],false,'{"seq":5,"concept":"K4-2-u3-C43","difficulty":2,"kind":"mc","stem":"선재의 제안을 뒷받침할 이유로 알맞은 것은 무엇인가요?","options":[{"t":"체육 시간 뒤에 손의 세균을 더 잘 씻어 낼 수 있다","correct":true},{"t":"내가 좋아하는 비누 향기를 맡을 수 있다","mis":"K4-2-u3-X37"},{"t":"다른 학교 수돗가에는 다 비누가 있을 것 같다","mis":"K4-2-u3-X38"},{"t":"비누를 놓으면 손 씻기 싫어하는 친구가 한 명도 없어질 것이다","mis":"K4-2-u3-X38"}],"explanation":["확인한 사실이 있나요?","내 취향은 약해요.","짐작은 사실처럼 쓰지 않아요."],"asset":{"type":"passage","lines":["문제 상황 — 운동장 수돗가에 비누가 없어 손을 물로만 헹군다","제안하는 대상 — 학교 시설을 정할 수 있는 교장 선생님","제안하는 내용 — 수돗가마다 물이 잘 빠지는 비누 걸이를 달고 비누를 놓자","확인한 사실 — 보건 선생님께 여쭈어 보니, 비누로 씻으면","   물로만 씻을 때보다 손의 세균을 더 잘 없앨 수 있다고 하셨다"],"title":"선재의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#6','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C44',2,'mc','auto','쓸 내용을 조직할 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u3-X44']::text[],false,'{"seq":6,"concept":"K4-2-u3-C44","difficulty":2,"kind":"mc","stem":"쓸 내용을 조직할 때 알맞은 방법은 무엇인가요?","options":[{"t":"쓸 내용을 핵심 낱말로 짧게 적어 차례를 정한다","correct":true},{"t":"개요에 글 전체를 미리 다 써 둔다","mis":"K4-2-u3-X44"},{"t":"개요 없이 떠오르는 대로 끝까지 쓴다","mis":"K4-2-u3-X44"},{"t":"개요에는 제목만 하나 적는다","mis":"K4-2-u3-X44"}],"explanation":["개요는 길잡이예요.","글 전체가 아니에요.","핵심 낱말로 짧게요."],"asset":{"type":"passage","lines":["처음 — 인사 · 수돗가 비누 없음 · 물로만 헹굼","가운데 — 비누 걸이 달기 · 세균 · 세면대 줄","끝 — 살펴봐 주시기를 부탁"],"title":"선재가 짠 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#7','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C46',2,'match','auto','선재의 어색한 문장과 바르게 고친 문장을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u3-C46","difficulty":2,"kind":"match","stem":"선재의 어색한 문장과 바르게 고친 문장을 알맞게 이으세요.","pairs":[{"l":"수돗가는 손을 씻는 곳을 좋아합니다.","r":"수돗가는 손을 씻는 곳입니다."},{"l":"우리는 비누로 손을 깨끗합니다.","r":"우리는 비누로 손을 깨끗이 씻습니다."},{"l":"비누 걸이가 있는 수돗가를 편리합니다.","r":"비누 걸이가 있는 수돗가는 편리합니다."}],"mis":"K4-2-u3-X46","explanation":["소리 내어 읽어요.","앞과 뒤가 어울리나요?","무엇이다 · 어찌하다 · 어떠하다로 고쳐요."],"asset":{"type":"passage","lines":["1 수돗가는 손을 씻는 곳을 좋아합니다.","2 우리는 비누로 손을 깨끗합니다.","3 비누 걸이가 있는 수돗가를 편리합니다."],"title":"선재의 첫 글 가운데 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#8','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C49',2,'mc','auto','시청에 제안하는 글을 전하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X48']::text[],false,'{"seq":8,"concept":"K4-2-u3-C49","difficulty":2,"kind":"mc","stem":"시청에 제안하는 글을 전하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"시청 누리집의 제안 게시판에 올린다","correct":true},{"t":"교실 칠판에 붙여 둔다","mis":"K4-2-u3-X48"},{"t":"짝에게 대신 읽어 준다","mis":"K4-2-u3-X48"},{"t":"집 냉장고 문에 붙여 둔다","mis":"K4-2-u3-X48"}],"explanation":["누가 읽어야 하나요?","시청 담당자예요.","시청 누리집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#9','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C48',2,'mc','auto','제안하는 글을 고쳐 쓰기 전에 점검할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X42','K4-2-u3-X36','K4-2-u3-X23']::text[],false,'{"seq":9,"concept":"K4-2-u3-C48","difficulty":2,"kind":"mc","stem":"제안하는 글을 고쳐 쓰기 전에 점검할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"소리 내어 읽어 짜임이 어색한 문장이 있는지","correct":true},{"t":"제목이 길고 멋있는지","mis":"K4-2-u3-X42"},{"t":"「왜냐하면」을 몇 번 썼는지","mis":"K4-2-u3-X36"},{"t":"친구의 제안이 더 좋아도 절대 바꾸지 않았는지","mis":"K4-2-u3-X23"}],"explanation":["어색한 문장을 찾아요.","소리 내어 읽어요.","고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_basic#10','kor',4,2,'u3','L09','g4_2_kor_u3_L09_basic','lesson_basic','K4-2-u3-C45',3,'error','auto','문장의 짜임을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":10,"concept":"K4-2-u3-C45","difficulty":3,"kind":"error","stem":"문장의 짜임을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘이곳은 수돗가입니다.’는 누가 + 어찌하다 짜임이야.」","correct":true,"mis_target":"K4-2-u3-X45"},{"t":"친구 가 — 「‘우리는 손을 씻습니다.’는 누가 + 어찌하다야.」","mis":"K4-2-u3-X45"},{"t":"친구 나 — 「‘물이 차갑습니다.’는 무엇이 + 어떠하다야.」","mis":"K4-2-u3-X45"}],"explanation":["수돗가는 「무엇」이에요.","「무엇이다」 짜임이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#1','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C45',2,'sa','auto','「종소리가 울립니다.」에서 「울립니다」처럼 움직임을 나타내는 짜임을 무엇이라고 하는지 쓰세요. (어○○다)','{}'::text[],false,'{"seq":1,"concept":"K4-2-u3-C45","difficulty":2,"kind":"sa","stem":"「종소리가 울립니다.」에서 「울립니다」처럼 움직임을 나타내는 짜임을 무엇이라고 하는지 쓰세요. (어○○다)","answer":["어찌하다"],"explanation":["움직임이에요.","어떠하다는 모습이에요.","‘어찌하다’예요."],"mis":"K4-2-u3-X45"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#2','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C47',2,'blank','auto','「(  ) 튼튼합니다.」의 빈칸에 들어갈 「무엇이」로 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X46','K4-2-u3-X45']::text[],false,'{"seq":2,"concept":"K4-2-u3-C47","difficulty":2,"kind":"blank","stem":"「(  ) 튼튼합니다.」의 빈칸에 들어갈 「무엇이」로 알맞은 말은 무엇인가요?","options":[{"t":"비누 걸이가","correct":true},{"t":"튼튼하게","mis":"K4-2-u3-X46"},{"t":"비누 걸이를","mis":"K4-2-u3-X46"},{"t":"씻습니다","mis":"K4-2-u3-X45"}],"explanation":["「무엇이」 칸이에요.","물건도 올 수 있어요.","‘비누 걸이가’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#3','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C46',3,'match','auto','하린이의 어색한 문장과 바르게 고친 문장을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u3-C46","difficulty":3,"kind":"match","stem":"하린이의 어색한 문장과 바르게 고친 문장을 알맞게 이으세요.","pairs":[{"l":"도서실은 책을 빌리는 곳을 좋아합니다.","r":"도서실은 책을 빌리는 곳입니다."},{"l":"친구들은 점심시간에 책을 즐겁습니다.","r":"친구들은 점심시간에 책을 즐겁게 읽습니다."},{"l":"점심시간의 도서실을 조용합니다.","r":"점심시간의 도서실은 조용합니다."}],"mis":"K4-2-u3-X46","explanation":["소리 내어 읽어요.","앞과 뒤가 어울리게요.","무엇이다 · 어찌하다 · 어떠하다예요."],"asset":{"type":"passage","lines":["① 도서실은 책을 빌리는 곳을 좋아합니다.","② 친구들은 점심시간에 책을 즐겁습니다.","③ 점심시간의 도서실을 조용합니다."],"title":"하린이의 첫 글 가운데 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#4','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C47',3,'mc','auto','「누가/무엇이」 칸에 사람이 아닌 것이 오고, 바르게 짜인 문장은 무엇인가요?',ARRAY['K4-2-u3-X47','K4-2-u3-X46']::text[],false,'{"seq":4,"concept":"K4-2-u3-C47","difficulty":3,"kind":"mc","stem":"「누가/무엇이」 칸에 사람이 아닌 것이 오고, 바르게 짜인 문장은 무엇인가요?","options":[{"t":"「도서실 창문이 환합니다.」","correct":true},{"t":"「하린이가 책을 읽습니다.」","mis":"K4-2-u3-X47"},{"t":"「친구들은 책을 즐겁습니다.」","mis":"K4-2-u3-X46"},{"t":"「선생님께서 웃으십니다.」","mis":"K4-2-u3-X47"}],"explanation":["사람이 아닌 것을 찾아요.","창문은 「무엇」이에요.","무엇이 + 어떠하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#5','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C42',3,'mc','auto','새로 떠올린 문제 상황 가운데 제안하는 글로 해결하기에 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X43']::text[],false,'{"seq":5,"concept":"K4-2-u3-C42","difficulty":3,"kind":"mc","stem":"새로 떠올린 문제 상황 가운데 제안하는 글로 해결하기에 가장 알맞은 것은 무엇인가요?","options":[{"t":"㉯ 미술실 물감 통의 뚜껑이 잘 닫히지 않아 물감이 자주 마른다","correct":true},{"t":"㉮ 동생과 텔레비전 채널 때문에 다투어 속상했다","mis":"K4-2-u3-X43"},{"t":"㉰ 오늘 비가 와서 운동장에서 놀지 못했다","mis":"K4-2-u3-X43"},{"t":"셋 다 제안하는 글로 해결하기 알맞지 않다","mis":"K4-2-u3-X43"}],"explanation":["바꿀 수 있는 분이 있나요?","많은 친구가 겪나요?","㉯예요."],"asset":{"type":"passage","lines":["㉮ 동생과 텔레비전 채널 때문에 다투어 속상했다","㉯ 미술실 물감 통의 뚜껑이 잘 닫히지 않아 물감이 자주 마른다","㉰ 오늘 비가 와서 운동장에서 놀지 못했다"],"title":"새로 떠올린 문제 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#6','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C43',3,'mc','auto','이유에 사실을 넣을 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X38','K4-2-u3-X37']::text[],false,'{"seq":6,"concept":"K4-2-u3-C43","difficulty":3,"kind":"mc","stem":"이유에 사실을 넣을 때 알맞은 것은 무엇인가요?","options":[{"t":"보건 선생님께 여쭈어 확인한 사실만 쓰고, 확인하지 않은 짐작은 사실처럼 쓰지 않는다","correct":true},{"t":"이유가 강해 보이게 그럴듯한 수를 지어 넣는다","mis":"K4-2-u3-X38"},{"t":"내가 좋아하는 것을 사실처럼 쓴다","mis":"K4-2-u3-X37"},{"t":"사실은 지루하니 빼고 내 느낌만 쓴다","mis":"K4-2-u3-X37"}],"explanation":["선재는 여쭈어 확인했어요.","지어내지 않아요.","확인한 사실만 써요."],"asset":{"type":"passage","lines":["문제 상황 — 운동장 수돗가에 비누가 없어 손을 물로만 헹군다","제안하는 대상 — 학교 시설을 정할 수 있는 교장 선생님","제안하는 내용 — 수돗가마다 물이 잘 빠지는 비누 걸이를 달고 비누를 놓자","확인한 사실 — 보건 선생님께 여쭈어 보니, 비누로 씻으면","   물로만 씻을 때보다 손의 세균을 더 잘 없앨 수 있다고 하셨다"],"title":"선재의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#7','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C44',3,'ox','auto','개요에는 쓸 글 전체를 문장으로 미리 다 써 두어야 해요.',ARRAY['K4-2-u3-X44']::text[],false,'{"seq":7,"concept":"K4-2-u3-C44","difficulty":3,"kind":"ox","stem":"개요에는 쓸 글 전체를 문장으로 미리 다 써 두어야 해요.","answer":"X","reason_options":[{"t":"핵심 낱말로 짧게 적어 차례를 정하면 쓸 때 힘을 아낄 수 있기 때문에","correct":true},{"t":"개요가 길수록 글이 좋아지기 때문에","mis":"K4-2-u3-X44"}],"mis":"K4-2-u3-X44","explanation":["선재의 개요를 봐요.","핵심 낱말뿐이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["처음 — 인사 · 수돗가 비누 없음 · 물로만 헹굼","가운데 — 비누 걸이 달기 · 세균 · 세면대 줄","끝 — 살펴봐 주시기를 부탁"],"title":"선재가 짠 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#8','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C48',4,'mc','auto','하린이가 친구의 글을 읽어 보니 「반마다 요일을 정해 도서실을 돕자」는 제안이 더 좋아 보였어요. 어떻게 하는 것이 알맞나요?',ARRAY['K4-2-u3-X23','K4-2-u3-X19','K4-2-u3-X41']::text[],false,'{"seq":8,"concept":"K4-2-u3-C48","difficulty":4,"kind":"mc","stem":"하린이가 친구의 글을 읽어 보니 「반마다 요일을 정해 도서실을 돕자」는 제안이 더 좋아 보였어요. 어떻게 하는 것이 알맞나요?","options":[{"t":"친구의 제안이 더 좋다고 생각되면 받아들여 내 제안을 다듬는다","correct":true},{"t":"내가 쓴 글이니 절대 바꾸지 않는다","mis":"K4-2-u3-X23"},{"t":"두 제안을 합치면 언제나 좋으니 따져 보지 않고 다 넣는다","mis":"K4-2-u3-X19"},{"t":"다시는 제안하는 글을 쓰지 않는다","mis":"K4-2-u3-X41"}],"explanation":["더 나은 방법이 보였어요.","받아들여도 돼요.","내 제안을 다듬어요."],"asset":{"type":"passage","lines":["1 도서실 담당 선생님, 안녕하세요? 저는 4학년 하린입니다.","2 점심시간에 도서실 문이 닫혀 있어서, 책을 빌리려는 친구들이","   쉬는 시간마다 한꺼번에 몰려 줄이 깁니다.","3 점심시간에도 도서실을 열고, 도서 도우미가 돌아가며 도우면 어떨까요?","4 그러면 책을 빌리는 친구들이 나뉘어 쉬는 시간에 붐비지 않고,","   점심을 먹은 뒤 조용히 책을 읽을 곳도 생깁니다."],"title":"하린이의 글 「점심시간에도 도서실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#9','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C49',4,'mc','auto','하린이가 쓴 글을 전하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X48']::text[],false,'{"seq":9,"concept":"K4-2-u3-C49","difficulty":4,"kind":"mc","stem":"하린이가 쓴 글을 전하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"도서실 담당 선생님께 찾아가 직접 드린다","correct":true},{"t":"시청 누리집의 제안 게시판에 올린다","mis":"K4-2-u3-X48"},{"t":"아파트 게시판에 붙인다","mis":"K4-2-u3-X48"},{"t":"동생에게 대신 읽어 준다","mis":"K4-2-u3-X48"}],"explanation":["누구에게 쓴 글인가요?","학교 안의 선생님이에요.","직접 드려요."],"asset":{"type":"passage","lines":["1 도서실 담당 선생님, 안녕하세요? 저는 4학년 하린입니다.","2 점심시간에 도서실 문이 닫혀 있어서, 책을 빌리려는 친구들이","   쉬는 시간마다 한꺼번에 몰려 줄이 깁니다.","3 점심시간에도 도서실을 열고, 도서 도우미가 돌아가며 도우면 어떨까요?","4 그러면 책을 빌리는 친구들이 나뉘어 쉬는 시간에 붐비지 않고,","   점심을 먹은 뒤 조용히 책을 읽을 곳도 생깁니다."],"title":"하린이의 글 「점심시간에도 도서실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L09_challenge#10','kor',4,2,'u3','L09','g4_2_kor_u3_L09_challenge','lesson_challenge','K4-2-u3-C46',4,'essay','teacher','하린이의 첫 글 세 문장을 바르게 고쳐 쓰고, 고친 문장이 각각 「누가/무엇이 + 어찌하다 · 어떠하다 · 무엇이다」 가운데 어떤 짜임인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C46","difficulty":4,"kind":"essay","stem":"하린이의 첫 글 세 문장을 바르게 고쳐 쓰고, 고친 문장이 각각 「누가/무엇이 + 어찌하다 · 어떠하다 · 무엇이다」 가운데 어떤 짜임인지 쓰세요.","answer_guide":{"answer":"예: ① 「도서실은 책을 빌리는 곳입니다.」 — 무엇이 + 무엇이다. ② 「친구들은 점심시간에 책을 즐겁게 읽습니다.」 — 누가 + 어찌하다. ③ 「점심시간의 도서실은 조용합니다.」 — 무엇이 + 어떠하다.","scoring_points":["세 문장을 모두 자연스럽게 고쳤는가","고친 문장의 짜임을 바르게 밝혔는가","「누가/무엇이」와 뒷부분이 어울리는지 살폈는가"]},"explanation":["소리 내어 읽어요.","앞과 뒤를 맞춰요.","짜임을 밝혀요."],"asset":{"type":"passage","lines":["① 도서실은 책을 빌리는 곳을 좋아합니다.","② 친구들은 점심시간에 책을 즐겁습니다.","③ 점심시간의 도서실을 조용합니다."],"title":"하린이의 첫 글 가운데 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#1','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C50',1,'mc','auto','㉯ 의견 곁에 붙이기 알맞은 질문 쪽지는 무엇인가요?',ARRAY['K4-2-u3-X13','K4-2-u3-X12','K4-2-u3-X14']::text[],false,'{"seq":1,"concept":"K4-2-u3-C50","difficulty":1,"kind":"mc","stem":"㉯ 의견 곁에 붙이기 알맞은 질문 쪽지는 무엇인가요?","options":[{"t":"「한 판이 오래 걸리는 놀이는 어떻게 넘기나요?」","correct":true},{"t":"「좋은 의견이에요! 모래시계는 무슨 색이에요?」","mis":"K4-2-u3-X13"},{"t":"「이런 생각을 누가 했어요? 이상해요.」","mis":"K4-2-u3-X12"},{"t":"「궁금한 건 없지만 쪽지를 많이 붙이려고 써요.」","mis":"K4-2-u3-X14"}],"explanation":["의견을 더 낫게 하나요?","실천할 때 어려움을 물어요.","존중하는 말로 써요."],"asset":{"type":"passage","lines":["누리집 글 — 쉬는 시간마다 교실 놀잇감을 서로 먼저 하려고 다투는 일이 생겨요.","함께 즐겁게 놀려면 어떻게 하면 좋을까요?","㉮ 요일마다 놀잇감을 쓸 모둠을 정하자. 모든 모둠이 돌아가며 쓸 수 있기 때문이다.","㉯ 모래시계를 두고 한 판이 끝나면 다음 친구에게 넘기자.","㉰ 놀잇감을 모두 치워 버리자. 다툴 일이 없어지기 때문이다."],"title":"칠판에 붙은 의견 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#2','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C51',1,'mc','auto','㉰ 「놀잇감을 모두 치워 버리자」에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X49','K4-2-u3-X14','K4-2-u3-X17']::text[],false,'{"seq":2,"concept":"K4-2-u3-C51","difficulty":1,"kind":"mc","stem":"㉰ 「놀잇감을 모두 치워 버리자」에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"다툼은 줄지만 함께 즐겁게 놀자는 바람까지 없애서 알맞은 해결이 아니다","correct":true},{"t":"다툼이 사라지니 가장 확실한 방법이다","mis":"K4-2-u3-X49"},{"t":"질문 쪽지를 가장 많이 받았으니 가장 좋은 의견이다","mis":"K4-2-u3-X14"},{"t":"가장 쉽게 할 수 있으니 가장 좋은 의견이다","mis":"K4-2-u3-X17"}],"explanation":["누리집 글이 바란 것은?","함께 즐겁게 놀기예요.","바람까지 없애면 안 돼요."],"asset":{"type":"passage","lines":["누리집 글 — 쉬는 시간마다 교실 놀잇감을 서로 먼저 하려고 다투는 일이 생겨요.","함께 즐겁게 놀려면 어떻게 하면 좋을까요?","㉮ 요일마다 놀잇감을 쓸 모둠을 정하자. 모든 모둠이 돌아가며 쓸 수 있기 때문이다.","㉯ 모래시계를 두고 한 판이 끝나면 다음 친구에게 넘기자.","㉰ 놀잇감을 모두 치워 버리자. 다툴 일이 없어지기 때문이다."],"title":"칠판에 붙은 의견 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#3','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C54',1,'ox','auto','「마음먹다」는 두 낱말이 만나 한 낱말이 되었으니 붙여 써요.',ARRAY['K4-2-u3-X51']::text[],false,'{"seq":3,"concept":"K4-2-u3-C54","difficulty":1,"kind":"ox","stem":"「마음먹다」는 두 낱말이 만나 한 낱말이 되었으니 붙여 써요.","answer":"O","reason_options":[{"t":"하나의 낱말이 된 말은 사이를 띄지 않고 붙여 쓰기 때문에","correct":true},{"t":"두 낱말이 이어지면 언제나 붙여 쓰기 때문에","mis":"K4-2-u3-X51"}],"mis":"K4-2-u3-X51","explanation":["마음을 먹다 → 마음먹다","한 낱말이 되었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#4','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C56',1,'mc','auto','「넓다」와 「좁다」는 어떤 관계인가요?',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":4,"concept":"K4-2-u3-C56","difficulty":1,"kind":"mc","stem":"「넓다」와 「좁다」는 어떤 관계인가요?","options":[{"t":"뜻이 반대인 관계","correct":true},{"t":"뜻이 비슷한 관계","mis":"K4-2-u3-X53"},{"t":"뜻을 포함하는 관계","mis":"K4-2-u3-X53"},{"t":"아무 관계가 없다","mis":"K4-2-u3-X53"}],"explanation":["넓은 방, 좁은 방","뜻이 서로 반대예요.","반대인 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#5','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C52',2,'match','auto','유건이의 발표 문장을 짜임에 맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u3-C52","difficulty":2,"kind":"match","stem":"유건이의 발표 문장을 짜임에 맞게 이으세요.","pairs":[{"l":"문제 상황","r":"㉢ 응원 도구가 한 번 쓰고 버려집니다"},{"l":"제안하는 내용","r":"㉠ 나눔 상자를 만들면 어떨까요?"},{"l":"제안하는 이유","r":"㉡ 쓰레기가 줄고 준비 시간도 아낍니다"}],"mis":"K4-2-u3-X26","explanation":["무엇이 문제인가요?","무엇을 하자고 하나요?","그러면 무엇이 좋아지나요?"],"asset":{"type":"passage","lines":["㉠ 학년마다 응원 도구를 모아 두는 나눔 상자를 만들면 어떨까요?","㉡ 그러면 버려지는 쓰레기가 줄고 다음 해 준비 시간도 아낄 수 있습니다.","㉢ 운동회가 끝나면 반마다 만든 응원 도구가 한 번 쓰고 버려집니다."],"title":"유건이의 안건 발표 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#6','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C53',2,'mc','auto','전교 학생 자치회에 낼 안건을 고르는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X50','K4-2-u3-X17']::text[],false,'{"seq":6,"concept":"K4-2-u3-C53","difficulty":2,"kind":"mc","stem":"전교 학생 자치회에 낼 안건을 고르는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"많은 학생과 관련 있고, 실천할 수 있으며, 이유에 공감을 얻은 제안을 고른다","correct":true},{"t":"발표를 가장 큰 목소리로 한 친구의 제안을 고른다","mis":"K4-2-u3-X50"},{"t":"우리 반에만 좋은 점이 큰 제안을 고른다","mis":"K4-2-u3-X50"},{"t":"가장 쉽게 할 수 있는 제안을 고른다","mis":"K4-2-u3-X17"}],"explanation":["자치회는 학교 모두의 일을 다뤄요.","많은 학생과 관련 있나요?","공감을 얻었나요?"],"asset":{"type":"passage","lines":["㉮ 응원 도구 나눔 상자 만들기","㉯ 우리 반 교실 벽만 좋아하는 색으로 새로 칠하기","㉰ 학년이 바뀔 때 다 읽은 책을 동생 학년과 바꾸어 읽기"],"title":"우리 반에서 나온 제안들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#7','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C55',2,'mc','auto','바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u3-X51','K4-2-u3-X52']::text[],false,'{"seq":7,"concept":"K4-2-u3-C55","difficulty":2,"kind":"mc","stem":"바르게 쓴 것은 무엇인가요?","options":[{"t":"밥 먹고","correct":true},{"t":"밥먹고","mis":"K4-2-u3-X51"},{"t":"마음 먹고","mis":"K4-2-u3-X52"},{"t":"물마시고","mis":"K4-2-u3-X51"}],"explanation":["밥과 먹다는 한 낱말이 아니에요.","마음먹다는 한 낱말이에요.","‘밥 먹고’가 바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#8','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C57',2,'mc','auto','「장갑을 벗다」의 반대말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X54']::text[],false,'{"seq":8,"concept":"K4-2-u3-C57","difficulty":2,"kind":"mc","stem":"「장갑을 벗다」의 반대말로 알맞은 것은 무엇인가요?","options":[{"t":"장갑을 끼다","correct":true},{"t":"장갑을 입다","mis":"K4-2-u3-X54"},{"t":"장갑을 쓰다","mis":"K4-2-u3-X54"},{"t":"장갑을 신다","mis":"K4-2-u3-X54"}],"explanation":["장갑을 손에 넣을 때를 떠올려요.","「끼다」라고 해요.","반대말은 쓰임에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#9','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C58',2,'mc','auto','「시냇물이 (  ).」 — 깨끗하다는 뜻으로 바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u3-X55']::text[],false,'{"seq":9,"concept":"K4-2-u3-C58","difficulty":2,"kind":"mc","stem":"「시냇물이 (  ).」 — 깨끗하다는 뜻으로 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"맑다","correct":true},{"t":"막다","mis":"K4-2-u3-X55"},{"t":"말다","mis":"K4-2-u3-X55"},{"t":"맏다","mis":"K4-2-u3-X55"}],"explanation":["겹받침 ㄺ이에요.","ㄹ과 ㄱ을 나란히 써요.","‘맑다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_basic#10','kor',4,2,'u3','L11','g4_2_kor_u3_L11_basic','lesson_basic','K4-2-u3-C51',3,'error','auto','칠판 의견 ㉰를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X49']::text[],false,'{"seq":10,"concept":"K4-2-u3-C51","difficulty":3,"kind":"error","stem":"칠판 의견 ㉰를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「다툼만 없어지면 되니까 놀잇감을 모두 치우는 게 가장 좋아.」","correct":true,"mis_target":"K4-2-u3-X49"},{"t":"친구 가 — 「㉮는 모든 모둠이 돌아가며 쓸 수 있어.」","mis":"K4-2-u3-X49"},{"t":"친구 나 — 「㉰는 함께 노는 즐거움까지 없애.」","mis":"K4-2-u3-X49"}],"explanation":["누리집 글의 바람을 봐요.","함께 즐겁게 놀기예요.","친구 다가 알맞지 않아요."],"asset":{"type":"passage","lines":["누리집 글 — 쉬는 시간마다 교실 놀잇감을 서로 먼저 하려고 다투는 일이 생겨요.","함께 즐겁게 놀려면 어떻게 하면 좋을까요?","㉮ 요일마다 놀잇감을 쓸 모둠을 정하자. 모든 모둠이 돌아가며 쓸 수 있기 때문이다.","㉯ 모래시계를 두고 한 판이 끝나면 다음 친구에게 넘기자.","㉰ 놀잇감을 모두 치워 버리자. 다툴 일이 없어지기 때문이다."],"title":"칠판에 붙은 의견 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#1','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C54',2,'sa','auto','「청소를 하다」가 한 낱말이 되면 어떻게 쓰는지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u3-C54","difficulty":2,"kind":"sa","stem":"「청소를 하다」가 한 낱말이 되면 어떻게 쓰는지 쓰세요.","answer":["청소하다"],"explanation":["정리를 하다 → 정리하다","청소를 하다도 같아요.","‘청소하다’예요."],"mis":"K4-2-u3-X52"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#2','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C56',2,'blank','auto','「과일」과 「사과」는 뜻을 (  ) 관계예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":2,"concept":"K4-2-u3-C56","difficulty":2,"kind":"blank","stem":"「과일」과 「사과」는 뜻을 (  ) 관계예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"포함하는","correct":true},{"t":"비슷한","mis":"K4-2-u3-X53"},{"t":"반대인","mis":"K4-2-u3-X53"},{"t":"바꾸는","mis":"K4-2-u3-X53"}],"explanation":["과일 안에 무엇이 있나요?","사과가 들어가요.","‘포함하는’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#3','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C55',3,'mc','auto','띄어쓰기가 모두 바른 문장은 무엇인가요?',ARRAY['K4-2-u3-X51','K4-2-u3-X52']::text[],false,'{"seq":3,"concept":"K4-2-u3-C55","difficulty":3,"kind":"mc","stem":"띄어쓰기가 모두 바른 문장은 무엇인가요?","options":[{"t":"「손 씻고 책 읽은 뒤 힘내서 청소했어요.」","correct":true},{"t":"「손씻고 책읽은 뒤 힘내서 청소했어요.」","mis":"K4-2-u3-X51"},{"t":"「손 씻고 책 읽은 뒤 힘 내서 청소했어요.」","mis":"K4-2-u3-X52"},{"t":"「손 씻고 책 읽은 뒤 힘내서 청소 했어요.」","mis":"K4-2-u3-X52"}],"explanation":["손 씻다 · 책 읽다는 띄어요.","힘내다 · 청소하다는 한 낱말이에요.","첫째가 바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#4','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C57',3,'mc','auto','「눈을 뜨다」와 「배가 물에 뜨다」의 반대말을 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u3-X54','K4-2-u3-X53']::text[],false,'{"seq":4,"concept":"K4-2-u3-C57","difficulty":3,"kind":"mc","stem":"「눈을 뜨다」와 「배가 물에 뜨다」의 반대말을 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"감다 · 가라앉다","correct":true},{"t":"감다 · 감다","mis":"K4-2-u3-X54"},{"t":"가라앉다 · 가라앉다","mis":"K4-2-u3-X54"},{"t":"닫다 · 내리다","mis":"K4-2-u3-X53"}],"explanation":["눈을 뜨다 ↔ 눈을 감다","배가 뜨다 ↔ 배가 가라앉다","쓰임에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#5','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C56',3,'match','auto','낱말 짝과 그 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u3-C56","difficulty":3,"kind":"match","stem":"낱말 짝과 그 관계를 알맞게 이으세요.","pairs":[{"l":"기르다 — 키우다","r":"뜻이 비슷한 관계"},{"l":"길다 — 짧다","r":"뜻이 반대인 관계"},{"l":"탈것 — 자전거","r":"뜻을 포함하는 관계"}],"mis":"K4-2-u3-X53","explanation":["기르다와 키우다는 바꿔 써도 돼요.","길다와 짧다는 반대예요.","탈것 안에 자전거가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#6','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C50',3,'mc','auto','㉮ 의견 곁에 붙이기 알맞은 질문 쪽지는 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13','K4-2-u3-X14']::text[],false,'{"seq":6,"concept":"K4-2-u3-C50","difficulty":3,"kind":"mc","stem":"㉮ 의견 곁에 붙이기 알맞은 질문 쪽지는 무엇인가요?","options":[{"t":"「결석한 친구가 많은 날은 그 모둠이 어떻게 하나요?」","correct":true},{"t":"「㉮는 말도 안 돼요. 누가 썼어요?」","mis":"K4-2-u3-X12"},{"t":"「좋은 의견이에요! 요일 이름표는 무슨 색이에요?」","mis":"K4-2-u3-X13"},{"t":"「쪽지를 많이 받아야 하니 아무거나 쓸게요.」","mis":"K4-2-u3-X14"}],"explanation":["실천할 때 어려움을 물어요.","말투도 존중해요.","첫째 쪽지예요."],"asset":{"type":"passage","lines":["누리집 글 — 쉬는 시간마다 교실 놀잇감을 서로 먼저 하려고 다투는 일이 생겨요.","함께 즐겁게 놀려면 어떻게 하면 좋을까요?","㉮ 요일마다 놀잇감을 쓸 모둠을 정하자. 모든 모둠이 돌아가며 쓸 수 있기 때문이다.","㉯ 모래시계를 두고 한 판이 끝나면 다음 친구에게 넘기자.","㉰ 놀잇감을 모두 치워 버리자. 다툴 일이 없어지기 때문이다."],"title":"칠판에 붙은 의견 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#7','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C53',3,'ox','auto','전교 학생 자치회 안건은 우리 반에만 좋은 점이 큰 제안을 골라야 해요.',ARRAY['K4-2-u3-X50']::text[],false,'{"seq":7,"concept":"K4-2-u3-C53","difficulty":3,"kind":"ox","stem":"전교 학생 자치회 안건은 우리 반에만 좋은 점이 큰 제안을 골라야 해요.","answer":"X","reason_options":[{"t":"학교 모두의 일을 다루니 많은 학생과 관련 있고 공감을 얻은 제안이 알맞기 때문에","correct":true},{"t":"우리 반이 낸 제안이니 우리 반에 좋은 것이 먼저이기 때문에","mis":"K4-2-u3-X50"}],"mis":"K4-2-u3-X50","explanation":["자치회는 누구의 일을 다루나요?","학교 모두예요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 응원 도구 나눔 상자 만들기","㉯ 우리 반 교실 벽만 좋아하는 색으로 새로 칠하기","㉰ 학년이 바뀔 때 다 읽은 책을 동생 학년과 바꾸어 읽기"],"title":"우리 반에서 나온 제안들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#8','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C51',4,'mc','auto','다온이네 모둠 의견 가운데 칠판 의견 ㉰ 「놀잇감을 모두 치우자」와 같은 까닭으로 알맞지 않은 의견은 무엇인가요?',ARRAY['K4-2-u3-X49','K4-2-u3-X17']::text[],false,'{"seq":8,"concept":"K4-2-u3-C51","difficulty":4,"kind":"mc","stem":"다온이네 모둠 의견 가운데 칠판 의견 ㉰ 「놀잇감을 모두 치우자」와 같은 까닭으로 알맞지 않은 의견은 무엇인가요?","options":[{"t":"㉰ 게시판을 없애고 작품을 각자 사물함에 넣어 두자","correct":true},{"t":"㉮ 작은 집게로 작품을 단단히 집자","mis":"K4-2-u3-X49"},{"t":"㉯ 당번이 아침마다 살펴 다시 붙이자","mis":"K4-2-u3-X49"},{"t":"㉱ 마음속으로 「떨어지지 마라」 하고 빌자","mis":"K4-2-u3-X17"}],"explanation":["문제만 없애나요?","작품을 함께 보려는 바람은요?","게시판까지 없애요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#9','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C52',4,'mc','auto','하린이가 「점심시간 도서실」을 전교 학생 자치회 안건으로 발표한다면, 짜임에 맞게 이어 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X31']::text[],false,'{"seq":9,"concept":"K4-2-u3-C52","difficulty":4,"kind":"mc","stem":"하린이가 「점심시간 도서실」을 전교 학생 자치회 안건으로 발표한다면, 짜임에 맞게 이어 말한 것은 무엇인가요?","options":[{"t":"「점심시간에 도서실이 닫혀 쉬는 시간마다 줄이 깁니다. → 점심시간에도 도서실을 열면 어떨까요? → 그러면 줄이 짧아지고 조용히 책을 읽을 곳이 생깁니다.」","correct":true},{"t":"「점심시간에도 도서실을 열면 어떨까요? → 점심시간에 도서실이 닫혀 줄이 깁니다. → 그러면 줄이 짧아집니다.」","mis":"K4-2-u3-X26"},{"t":"「그러면 줄이 짧아집니다. → 점심시간에도 도서실을 열면 어떨까요? → 점심시간에 도서실이 닫혀 있습니다.」","mis":"K4-2-u3-X26"},{"t":"「점심시간에 도서실이 닫혀 있어서 정말 속상합니다. → 왜 아무도 안 열어 주나요?」","mis":"K4-2-u3-X31"}],"explanation":["문제 상황이 먼저예요.","그다음 제안하는 내용이에요.","마지막이 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_L11_challenge#10','kor',4,2,'u3','L11','g4_2_kor_u3_L11_challenge','lesson_challenge','K4-2-u3-C51',4,'essay','teacher','칠판 의견 ㉰가 다툼을 없애는데도 알맞은 해결이 아닌 까닭을 쓰고, ㉮나 ㉯ 곁에 붙일 질문 쪽지를 하나 써서 그 질문이 의견을 어떻게 더 낫게 만드는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u3-C51","difficulty":4,"kind":"essay","stem":"칠판 의견 ㉰가 다툼을 없애는데도 알맞은 해결이 아닌 까닭을 쓰고, ㉮나 ㉯ 곁에 붙일 질문 쪽지를 하나 써서 그 질문이 의견을 어떻게 더 낫게 만드는지 쓰세요.","answer_guide":{"answer":"예: ㉰는 놀잇감이 없어져 다툼은 사라지지만, 누리집 글이 바란 「함께 즐겁게 놀기」까지 없애기 때문에 알맞은 해결이 아니다. ㉯ 곁에 「좋은 생각이에요. 그런데 한 판이 오래 걸리는 놀이는 어떻게 넘기나요?」라는 쪽지를 붙이겠다. 이 질문에 답하면서 「긴 놀이는 모래시계 두 번으로 정하자」처럼 의견이 더 구체적으로 다듬어질 수 있다.","scoring_points":["㉰가 바라는 모습까지 없앤다고 썼는가","존중하는 말로 어려움이나 실천 방법을 묻는 질문 쪽지를 썼는가","질문이 의견을 어떻게 낫게 하는지 썼는가"]},"explanation":["바라는 모습은?","존중하며 물어요.","의견이 다듬어져요."],"asset":{"type":"passage","lines":["누리집 글 — 쉬는 시간마다 교실 놀잇감을 서로 먼저 하려고 다투는 일이 생겨요.","함께 즐겁게 놀려면 어떻게 하면 좋을까요?","㉮ 요일마다 놀잇감을 쓸 모둠을 정하자. 모든 모둠이 돌아가며 쓸 수 있기 때문이다.","㉯ 모래시계를 두고 한 판이 끝나면 다음 친구에게 넘기자.","㉰ 놀잇감을 모두 치워 버리자. 다툴 일이 없어지기 때문이다."],"title":"칠판에 붙은 의견 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#1','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C3',1,'mc','auto','토의로 정하기에 알맞은 일은 무엇인가요?',ARRAY['K4-2-u3-X02']::text[],false,'{"seq":1,"concept":"K4-2-u3-C3","difficulty":1,"kind":"mc","stem":"토의로 정하기에 알맞은 일은 무엇인가요?","options":[{"t":"교실 뒤 놀이 공간을 나누어 쓰는 방법","correct":true},{"t":"10 빼기 3의 답","mis":"K4-2-u3-X02"},{"t":"내가 오늘 먹고 싶은 간식","mis":"K4-2-u3-X02"},{"t":"내 일기장에 붙일 스티커 모양","mis":"K4-2-u3-X02"}],"explanation":["답이 정해진 일은 빼요.","나 혼자만의 일도 빼요.","모두와 관련 있는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#2','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C8',1,'mc','auto','토의 절차를 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K4-2-u3-X07']::text[],false,'{"seq":2,"concept":"K4-2-u3-C8","difficulty":1,"kind":"mc","stem":"토의 절차를 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"주제 정하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기","correct":true},{"t":"의견 결정하기 → 주제 정하기 → 의견 모으기 → 의견 마련하기","mis":"K4-2-u3-X07"},{"t":"의견 모으기 → 주제 정하기 → 의견 결정하기 → 의견 마련하기","mis":"K4-2-u3-X07"},{"t":"주제 정하기 → 의견 결정하기 → 의견 마련하기 → 의견 모으기","mis":"K4-2-u3-X07"}],"explanation":["주제가 먼저예요.","준비하고 모아요.","결정이 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#3','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C5',1,'mc','auto','어떤 일에 대해 의견을 내놓는 것을 무엇이라고 하나요?',ARRAY['K4-2-u3-X57','K4-2-u3-X01']::text[],false,'{"seq":3,"concept":"K4-2-u3-C5","difficulty":1,"kind":"mc","stem":"어떤 일에 대해 의견을 내놓는 것을 무엇이라고 하나요?","options":[{"t":"제안","correct":true},{"t":"명령","mis":"K4-2-u3-X57"},{"t":"불평","mis":"K4-2-u3-X57"},{"t":"말다툼","mis":"K4-2-u3-X01"}],"explanation":["예슬이도 했어요.","아정이도 했어요.","‘제안’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#4','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C27',1,'mc','auto','제안하는 글에서 「무엇을 바라는가」를 쓰는 부분은 무엇인가요?',ARRAY['K4-2-u3-X26']::text[],false,'{"seq":4,"concept":"K4-2-u3-C27","difficulty":1,"kind":"mc","stem":"제안하는 글에서 「무엇을 바라는가」를 쓰는 부분은 무엇인가요?","options":[{"t":"제안하는 내용","correct":true},{"t":"문제 상황","mis":"K4-2-u3-X26"},{"t":"제안하는 이유","mis":"K4-2-u3-X26"},{"t":"글쓴이 소개","mis":"K4-2-u3-X26"}],"explanation":["불편한 점이 아니에요.","좋아지는 점도 아니에요.","바라는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#5','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C45',1,'mc','auto','「우리는 손을 씻습니다.」는 어떤 짜임의 문장인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":5,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"「우리는 손을 씻습니다.」는 어떤 짜임의 문장인가요?","options":[{"t":"누가 + 어찌하다","correct":true},{"t":"무엇이 + 어떠하다","mis":"K4-2-u3-X45"},{"t":"무엇이 + 무엇이다","mis":"K4-2-u3-X45"},{"t":"누가 + 어떠하다","mis":"K4-2-u3-X45"}],"explanation":["우리는 「누가」예요.","씻다는 움직임이에요.","어찌하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#6','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C54',1,'mc','auto','「겁을 먹다」가 한 낱말이 된 말을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u3-X52']::text[],false,'{"seq":6,"concept":"K4-2-u3-C54","difficulty":1,"kind":"mc","stem":"「겁을 먹다」가 한 낱말이 된 말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"겁먹다","correct":true},{"t":"겁 먹다","mis":"K4-2-u3-X52"},{"t":"겁을먹다","mis":"K4-2-u3-X52"},{"t":"겁 을 먹다","mis":"K4-2-u3-X52"}],"explanation":["두 낱말이 한 낱말이 되었어요.","사이를 띄지 않아요.","‘겁먹다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#7','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C56',1,'mc','auto','「무섭다」와 「두렵다」는 어떤 관계인가요?',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":7,"concept":"K4-2-u3-C56","difficulty":1,"kind":"mc","stem":"「무섭다」와 「두렵다」는 어떤 관계인가요?","options":[{"t":"뜻이 비슷한 관계","correct":true},{"t":"뜻이 반대인 관계","mis":"K4-2-u3-X53"},{"t":"뜻을 포함하는 관계","mis":"K4-2-u3-X53"},{"t":"아무 관계가 없다","mis":"K4-2-u3-X53"}],"explanation":["바꿔 써 봐요.","뜻이 거의 같아요.","비슷한 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#8','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C58',1,'mc','auto','겹받침 ㄺ을 바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u3-X55']::text[],false,'{"seq":8,"concept":"K4-2-u3-C58","difficulty":1,"kind":"mc","stem":"겹받침 ㄺ을 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"흙길","correct":true},{"t":"흑길","mis":"K4-2-u3-X55"},{"t":"흘길","mis":"K4-2-u3-X55"},{"t":"흔길","mis":"K4-2-u3-X55"}],"explanation":["ㄹ과 ㄱ을 나란히 써요.","흙이 들어 있어요.","‘흙길’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#9','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C13',2,'mc','auto','「좋은 의견이에요! 그런데 스티커는 무슨 색인가요?」가 좋은 질문이 아닌 까닭은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X14','K4-2-u3-X11']::text[],false,'{"seq":9,"concept":"K4-2-u3-C13","difficulty":2,"kind":"mc","stem":"「좋은 의견이에요! 그런데 스티커는 무슨 색인가요?」가 좋은 질문이 아닌 까닭은 무엇인가요?","options":[{"t":"말투는 공손하지만 의견이 문제를 해결하는지 따지는 데 도움이 되지 않기 때문에","correct":true},{"t":"「좋은 의견이에요」라는 말을 붙였기 때문에","mis":"K4-2-u3-X12"},{"t":"질문이 하나뿐이어서 수가 모자라기 때문에","mis":"K4-2-u3-X14"},{"t":"스티커 의견을 포기하게 만들기 때문에","mis":"K4-2-u3-X11"}],"explanation":["말투는 괜찮아요.","무엇을 묻나요?","해결과 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#10','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C16',2,'mc','auto','「음수대 물이 약하게 나와서 쉬는 시간마다 줄이 길다」에서 문제가 생긴 까닭은 무엇인가요?',ARRAY['K4-2-u3-X16','K4-2-u3-X25']::text[],false,'{"seq":10,"concept":"K4-2-u3-C16","difficulty":2,"kind":"mc","stem":"「음수대 물이 약하게 나와서 쉬는 시간마다 줄이 길다」에서 문제가 생긴 까닭은 무엇인가요?","options":[{"t":"음수대 물이 약하게 나온다","correct":true},{"t":"쉬는 시간마다 줄이 길다","mis":"K4-2-u3-X16"},{"t":"쉬는 시간이 짧다","mis":"K4-2-u3-X16"},{"t":"물을 마시는 친구가 없다","mis":"K4-2-u3-X25"}],"explanation":["「왜 줄이 긴가」를 물어요.","물이 약해서예요.","줄이 긴 것은 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#11','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C18',2,'mc','auto','의견을 견줄 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X18']::text[],false,'{"seq":11,"concept":"K4-2-u3-C18","difficulty":2,"kind":"mc","stem":"의견을 견줄 때 알맞은 생각은 무엇인가요?","options":[{"t":"쉬운지와 문제가 해결되는지를 함께 따진다","correct":true},{"t":"가장 쉬운 의견이 언제나 가장 좋다","mis":"K4-2-u3-X17"},{"t":"쉬운 의견은 모두 버린다","mis":"K4-2-u3-X18"},{"t":"어려운 의견일수록 좋다","mis":"K4-2-u3-X17"}],"explanation":["솔비의 의견을 떠올려요.","쉬워도 해결이 안 됐어요.","둘을 함께 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#12','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C28',2,'mc','auto','「계단 난간에 매달리지 마세요.」가 제안하는 글로 부족한 까닭은 무엇인가요?',ARRAY['K4-2-u3-X27','K4-2-u3-X28','K4-2-u3-X31']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"mc","stem":"「계단 난간에 매달리지 마세요.」가 제안하는 글로 부족한 까닭은 무엇인가요?","options":[{"t":"막기만 할 뿐 해결 방법과 이유가 없기 때문에","correct":true},{"t":"「~하세요」로 끝나서 이미 충분하기 때문에","mis":"K4-2-u3-X27"},{"t":"너무 길게 써서 읽기 어렵기 때문에","mis":"K4-2-u3-X28"},{"t":"불만을 쏟아 냈기 때문에","mis":"K4-2-u3-X31"}],"explanation":["막기만 하나요?","왜, 어떻게가 없어요.","제안하는 글로 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#13','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C36',2,'mc','auto','「수돗가에 비누를 놓아 주세요」를 뒷받침하는 이유로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X36','K4-2-u3-X38']::text[],false,'{"seq":13,"concept":"K4-2-u3-C36","difficulty":2,"kind":"mc","stem":"「수돗가에 비누를 놓아 주세요」를 뒷받침하는 이유로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「그러면 체육 시간 뒤에 많은 친구가 손을 제대로 씻을 수 있습니다.」","correct":true},{"t":"「왜냐하면 제가 비누 거품을 좋아하기 때문입니다.」","mis":"K4-2-u3-X37"},{"t":"「왜냐하면 왜냐하면이 들어가야 하기 때문입니다.」","mis":"K4-2-u3-X36"},{"t":"「왜냐하면 다른 학교에는 다 있을 것 같기 때문입니다.」","mis":"K4-2-u3-X38"}],"explanation":["여러 사람에게 좋아지나요?","취향과 짐작은 약해요.","첫째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#14','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C35',2,'mc','auto','「계단 옆 게시판이 높아서 1학년 동생들이 읽지 못한다」에 알맞은 제안 내용은 무엇인가요?',ARRAY['K4-2-u3-X34','K4-2-u3-X35']::text[],false,'{"seq":14,"concept":"K4-2-u3-C35","difficulty":2,"kind":"mc","stem":"「계단 옆 게시판이 높아서 1학년 동생들이 읽지 못한다」에 알맞은 제안 내용은 무엇인가요?","options":[{"t":"동생들 눈높이에 게시판을 하나 더 달아 주세요","correct":true},{"t":"게시판 옆에 하루 종일 읽어 주는 사람을 세워 주세요","mis":"K4-2-u3-X34"},{"t":"게시판을 모두 없애 주세요","mis":"K4-2-u3-X35"},{"t":"1학년 동생들은 계단을 쓰지 않게 해 주세요","mis":"K4-2-u3-X35"}],"explanation":["문제를 바로 푸나요?","실제로 할 수 있나요?","눈높이 게시판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#15','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C46',2,'mc','auto','「우리는 비누로 손을 깨끗합니다.」를 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u3-X46']::text[],false,'{"seq":15,"concept":"K4-2-u3-C46","difficulty":2,"kind":"mc","stem":"「우리는 비누로 손을 깨끗합니다.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"「우리는 비누로 손을 깨끗이 씻습니다.」","correct":true},{"t":"「우리는 비누로 손을 깨끗하게.」","mis":"K4-2-u3-X46"},{"t":"「우리는 비누로 손이 씻습니다.」","mis":"K4-2-u3-X46"},{"t":"「손이 비누로 우리를 씻습니다.」","mis":"K4-2-u3-X46"}],"explanation":["소리 내어 읽어요.","「손을」 뒤에 움직임이 와야 해요.","깨끗이 씻습니다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#16','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C23',2,'mc','auto','「모둠 활동 뒤 색연필이 뒤섞이는 문제」를 해결할 실천 계획으로 가장 구체적인 것은 무엇인가요?',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":16,"concept":"K4-2-u3-C23","difficulty":2,"kind":"mc","stem":"「모둠 활동 뒤 색연필이 뒤섞이는 문제」를 해결할 실천 계획으로 가장 구체적인 것은 무엇인가요?","options":[{"t":"모둠 활동이 끝나면 정리 당번 한 명이 색깔별 통에 색연필을 나누어 담는다","correct":true},{"t":"색연필을 아끼려고 열심히 노력한다","mis":"K4-2-u3-X21"},{"t":"언젠가 시간이 나면 색연필을 정리한다","mis":"K4-2-u3-X21"},{"t":"모두 알아서 잘 정리한다","mis":"K4-2-u3-X21"}],"explanation":["언제 하나요?","누가 하나요?","무엇을 하나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#17','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C31',3,'mc','auto','생활 속에서 문제를 만났을 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X22','K4-2-u3-X05']::text[],false,'{"seq":17,"concept":"K4-2-u3-C31","difficulty":3,"kind":"mc","stem":"생활 속에서 문제를 만났을 때 알맞은 생각은 무엇인가요?","options":[{"t":"문제와 상황에 따라 토의 · 직접 말하기 · 제안하는 글 가운데 알맞은 방법을 고른다","correct":true},{"t":"어떤 문제든 언제나 제안하는 글부터 쓴다","mis":"K4-2-u3-X04"},{"t":"내가 겪는 일이 아니면 그냥 지나친다","mis":"K4-2-u3-X22"},{"t":"토의를 했으면 다른 사람에게 알릴 필요가 없다","mis":"K4-2-u3-X05"}],"explanation":["1차시와 6차시의 물음이에요.","방법은 여러 가지예요.","상황에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#18','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C51',3,'mc','auto','「체육 시간 공 다툼」을 두고 나온 의견 가운데 알맞은 해결이 아닌 것은 무엇인가요?',ARRAY['K4-2-u3-X49']::text[],false,'{"seq":18,"concept":"K4-2-u3-C51","difficulty":3,"kind":"mc","stem":"「체육 시간 공 다툼」을 두고 나온 의견 가운데 알맞은 해결이 아닌 것은 무엇인가요?","options":[{"t":"「공을 모두 치워서 다툴 일을 없애자.」","correct":true},{"t":"「모둠마다 공을 쓸 시간을 정하자.」","mis":"K4-2-u3-X49"},{"t":"「공을 하나 더 마련해 달라고 체육 선생님께 부탁하자.」","mis":"K4-2-u3-X49"},{"t":"「공을 먼저 쓴 모둠이 다음 모둠에게 넘겨주자.」","mis":"K4-2-u3-X49"}],"explanation":["바라는 것은 함께 즐겁게 노는 것이에요.","공을 치우면 놀 수 없어요.","바람까지 없애요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#19','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C43',3,'mc','auto','제안하는 글의 이유에 쓰기에 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u3-X38']::text[],false,'{"seq":19,"concept":"K4-2-u3-C43","difficulty":3,"kind":"mc","stem":"제안하는 글의 이유에 쓰기에 알맞지 않은 것은 무엇인가요?","options":[{"t":"「다른 학교 도서실은 다 점심시간에 열 것 같습니다.」","correct":true},{"t":"「점심시간에 열면 쉬는 시간의 줄이 짧아집니다.」","mis":"K4-2-u3-X38"},{"t":"「사서 선생님께 여쭈어 보니 점심시간에 책을 빌리고 싶어 하는 친구가 많다고 하셨습니다.」","mis":"K4-2-u3-X38"},{"t":"「더 많은 친구가 책을 빌릴 수 있습니다.」","mis":"K4-2-u3-X38"}],"explanation":["확인한 것인가요?","「것 같습니다」는 짐작이에요.","짐작을 사실처럼 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#20','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C40',3,'mc','auto','「올해는 예산이 모자라 안내판을 더 달기 어렵습니다.」라는 답을 받았다면 다음에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X41','K4-2-u3-X30']::text[],false,'{"seq":20,"concept":"K4-2-u3-C40","difficulty":3,"kind":"mc","stem":"「올해는 예산이 모자라 안내판을 더 달기 어렵습니다.」라는 답을 받았다면 다음에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"까닭을 살펴, 먼저 글자만 크게 바꿔 줄 수 있는지 제안을 고쳐 본다","correct":true},{"t":"다시는 제안하는 글을 쓰지 않는다","mis":"K4-2-u3-X41"},{"t":"받아들여질 때까지 같은 글을 날마다 보낸다","mis":"K4-2-u3-X41"},{"t":"글로 썼으니 꼭 들어줘야 한다고 따진다","mis":"K4-2-u3-X30"}],"explanation":["답에 까닭이 있어요.","고칠 실마리예요.","제안을 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#21','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C42',3,'mc','auto','제안하는 글로 해결하기에 알맞지 않은 문제 상황은 무엇인가요?',ARRAY['K4-2-u3-X43']::text[],false,'{"seq":21,"concept":"K4-2-u3-C42","difficulty":3,"kind":"mc","stem":"제안하는 글로 해결하기에 알맞지 않은 문제 상황은 무엇인가요?","options":[{"t":"「올여름에 비가 너무 많이 왔다.」","correct":true},{"t":"「강당 문이 무거워 동생들이 혼자 열기 어렵다.」","mis":"K4-2-u3-X43"},{"t":"「교실 시계가 자꾸 멈춰 수업 시작을 놓친다.」","mis":"K4-2-u3-X43"},{"t":"「급수대 수도꼭지 하나가 고장 나 물이 샌다.」","mis":"K4-2-u3-X43"}],"explanation":["누구에게 제안하면 바뀌나요?","날씨는 바꿀 수 없어요.","첫째가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#22','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C39',3,'mc','auto','여원이가 고쳐 쓰기 전에 적은 문장 가운데 예의 있게 고쳐야 할 것은 무엇인가요?',ARRAY['K4-2-u3-X39']::text[],false,'{"seq":22,"concept":"K4-2-u3-C39","difficulty":3,"kind":"mc","stem":"여원이가 고쳐 쓰기 전에 적은 문장 가운데 예의 있게 고쳐야 할 것은 무엇인가요?","options":[{"t":"「이런 안내판을 만든 사람은 생각이 없나 봐요.」","correct":true},{"t":"「눈높이에 맞는 안내판을 하나 더 달면 어떨까요?」","mis":"K4-2-u3-X39"},{"t":"「글자를 조금 더 크게 해 주시면 모두에게 도움이 될 것 같습니다.」","mis":"K4-2-u3-X39"},{"t":"「제 제안을 살펴봐 주시기를 부탁드립니다.」","mis":"K4-2-u3-X39"}],"explanation":["상대를 탓하나요?","읽는 사람의 기분을 생각해요.","첫째를 고쳐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#23','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C17',4,'mc','auto','이 단원에서 배운 내용을 가장 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X27','K4-2-u3-X30']::text[],false,'{"seq":23,"concept":"K4-2-u3-C17","difficulty":4,"kind":"mc","stem":"이 단원에서 배운 내용을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"「토의에서 질문하며 의견을 다듬고, 해결되는지와 실천할 수 있는지를 함께 따져 정하고, 바꿀 수 있는 사람에게 예의 있게 제안해.」","correct":true},{"t":"「가장 쉬운 의견을 고르고, 「왜냐하면」만 넣어 제안하면 돼.」","mis":"K4-2-u3-X17"},{"t":"「「~하지 마세요」라고만 적어도 좋은 제안이야.」","mis":"K4-2-u3-X27"},{"t":"「글로 제안하면 언제나 받아들여지니 다른 방법은 필요 없어.」","mis":"K4-2-u3-X30"}],"explanation":["「언제나」, 「~만」을 조심해요.","질문 · 기준 · 대상","첫째가 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#24','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C31',4,'essay','teacher','「모둠 친구가 내 연필을 말없이 자꾸 가져간다」와 「강당 문이 무거워 동생들이 혼자 열기 어렵다」에 알맞은 해결 방법을 각각 쓰고, 「문제가 생기면 언제나 제안하는 글부터 써야 한다」가 왜 알맞지 않은지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C31","difficulty":4,"kind":"essay","stem":"「모둠 친구가 내 연필을 말없이 자꾸 가져간다」와 「강당 문이 무거워 동생들이 혼자 열기 어렵다」에 알맞은 해결 방법을 각각 쓰고, 「문제가 생기면 언제나 제안하는 글부터 써야 한다」가 왜 알맞지 않은지 쓰세요.","answer_guide":{"answer":"예: 연필 일은 두 사람 사이의 일이라 그 친구에게 직접 차분히 말하는 것이 알맞다. 강당 문은 많은 학생이 겪고 학교 시설을 정할 수 있는 교장 선생님께 바꿔 달라고 할 수 있으니 제안하는 글을 쓰는 것이 알맞다. 이처럼 문제와 상황에 따라 직접 말하기 · 토의 · 제안하는 글 가운데 알맞은 방법이 다르므로 「언제나 제안하는 글부터」는 알맞지 않다.","scoring_points":["연필 일에 직접 말하기를 썼는가","강당 문에 제안하는 글(바꿀 수 있는 분께)을 썼는가","「언제나」가 알맞지 않은 까닭을 썼는가"]},"explanation":["누구와의 일인가요?","누가 바꿀 수 있나요?","상황에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_a#25','kor',4,2,'u3','','g4_2_kor_u3_review_a','unit_review','K4-2-u3-C43',4,'essay','teacher','선재의 계획을 보고, 이유로 쓸 수 있는 것 두 가지와 쓰면 안 되는 것 한 가지를 쓰세요. 쓰면 안 되는 까닭도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C43","difficulty":4,"kind":"essay","stem":"선재의 계획을 보고, 이유로 쓸 수 있는 것 두 가지와 쓰면 안 되는 것 한 가지를 쓰세요. 쓰면 안 되는 까닭도 쓰세요.","answer_guide":{"answer":"예: 이유로 쓸 수 있는 것은 「비누로 씻으면 물로만 씻을 때보다 손의 세균을 더 잘 없앨 수 있다(보건 선생님께 확인함)」와 「교실 세면대까지 가서 줄 서지 않아도 손을 제대로 씻을 수 있다」이다. 쓰면 안 되는 것은 「다른 학교 수돗가에는 다 비누가 있을 것 같다」이다. 확인하지 않은 짐작을 사실처럼 쓰면 읽는 사람이 글을 믿을 수 없기 때문이다.","scoring_points":["이유로 쓸 수 있는 것 두 가지를 썼는가","쓰면 안 되는 것(짐작·취향)을 썼는가","쓰면 안 되는 까닭을 썼는가"]},"explanation":["확인한 사실을 찾아요.","좋아지는 점을 찾아요.","짐작은 사실처럼 쓰지 않아요."],"asset":{"type":"passage","lines":["문제 상황 — 운동장 수돗가에 비누가 없어 손을 물로만 헹군다","제안하는 대상 — 학교 시설을 정할 수 있는 교장 선생님","제안하는 내용 — 수돗가마다 물이 잘 빠지는 비누 걸이를 달고 비누를 놓자","확인한 사실 — 보건 선생님께 여쭈어 보니, 비누로 씻으면","   물로만 씻을 때보다 손의 세균을 더 잘 없앨 수 있다고 하셨다"],"title":"선재의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#1','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C2',1,'ox','auto','토의는 여럿이 의견을 모아 문제의 해결 방법을 찾는 것이에요.',ARRAY['K4-2-u3-X01']::text[],false,'{"seq":1,"concept":"K4-2-u3-C2","difficulty":1,"kind":"ox","stem":"토의는 여럿이 의견을 모아 문제의 해결 방법을 찾는 것이에요.","answer":"O","reason_options":[{"t":"혼자서는 풀기 어려운 문제도 여럿이 의견을 모으면 길이 보이기 때문에","correct":true},{"t":"한 사람이 정한 방법을 모두에게 알리는 것이기 때문에","mis":"K4-2-u3-X01"}],"mis":"K4-2-u3-X01","explanation":["문턱 이야기를 떠올려요.","여럿이 모았어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#2','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C8',1,'mc','auto','「의견 결정하기」 단계에서 하는 일은 무엇인가요?',ARRAY['K4-2-u3-X07']::text[],false,'{"seq":2,"concept":"K4-2-u3-C8","difficulty":1,"kind":"mc","stem":"「의견 결정하기」 단계에서 하는 일은 무엇인가요?","options":[{"t":"기준을 세워 가장 알맞은 의견을 정한다","correct":true},{"t":"모두와 관련 있는 문제를 고른다","mis":"K4-2-u3-X07"},{"t":"주제에 맞는 의견과 이유를 준비한다","mis":"K4-2-u3-X07"},{"t":"의견을 나누며 서로 묻고 따진다","mis":"K4-2-u3-X07"}],"explanation":["마지막 단계예요.","「정한다」를 찾아요.","기준으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#3','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C25',1,'mc','auto','제안은 누구에게 하는 것이 알맞나요?',ARRAY['K4-2-u3-X24','K4-2-u3-X57']::text[],false,'{"seq":3,"concept":"K4-2-u3-C25","difficulty":1,"kind":"mc","stem":"제안은 누구에게 하는 것이 알맞나요?","options":[{"t":"그 일을 정하거나 바꿀 수 있는 사람","correct":true},{"t":"나와 가장 친한 사람","mis":"K4-2-u3-X24"},{"t":"그 일과 상관없는 사람","mis":"K4-2-u3-X24"},{"t":"불평을 들어 줄 사람","mis":"K4-2-u3-X57"}],"explanation":["누가 바꿀 수 있나요?","그 사람에게 해요.","정하거나 바꿀 수 있는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#4','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C27',1,'mc','auto','제안하는 글에서 「무엇이 불편한가」를 쓰는 부분은 무엇인가요?',ARRAY['K4-2-u3-X26']::text[],false,'{"seq":4,"concept":"K4-2-u3-C27","difficulty":1,"kind":"mc","stem":"제안하는 글에서 「무엇이 불편한가」를 쓰는 부분은 무엇인가요?","options":[{"t":"문제 상황","correct":true},{"t":"제안하는 내용","mis":"K4-2-u3-X26"},{"t":"제안하는 이유","mis":"K4-2-u3-X26"},{"t":"끝인사","mis":"K4-2-u3-X26"}],"explanation":["불편한 점이에요.","처음에 나와요.","문제 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#5','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C45',1,'mc','auto','「이곳은 수돗가입니다.」는 어떤 짜임의 문장인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":5,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"「이곳은 수돗가입니다.」는 어떤 짜임의 문장인가요?","options":[{"t":"무엇이 + 무엇이다","correct":true},{"t":"누가 + 어찌하다","mis":"K4-2-u3-X45"},{"t":"무엇이 + 어떠하다","mis":"K4-2-u3-X45"},{"t":"누가 + 어떠하다","mis":"K4-2-u3-X45"}],"explanation":["이곳은 「무엇」이에요.","수돗가라고 말해요.","무엇이다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#6','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C55',1,'mc','auto','「물을 마시다」를 줄여 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u3-X51']::text[],false,'{"seq":6,"concept":"K4-2-u3-C55","difficulty":1,"kind":"mc","stem":"「물을 마시다」를 줄여 바르게 쓴 것은 무엇인가요?","options":[{"t":"물 마시다","correct":true},{"t":"물마시다","mis":"K4-2-u3-X51"},{"t":"물을마시다","mis":"K4-2-u3-X51"},{"t":"물 마 시다","mis":"K4-2-u3-X51"}],"explanation":["물과 마시다는 한 낱말이 아니에요.","그대로 띄어 써요.","‘물 마시다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#7','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C56',1,'mc','auto','「악기」와 「피아노」는 어떤 관계인가요?',ARRAY['K4-2-u3-X53']::text[],false,'{"seq":7,"concept":"K4-2-u3-C56","difficulty":1,"kind":"mc","stem":"「악기」와 「피아노」는 어떤 관계인가요?","options":[{"t":"뜻을 포함하는 관계","correct":true},{"t":"뜻이 비슷한 관계","mis":"K4-2-u3-X53"},{"t":"뜻이 반대인 관계","mis":"K4-2-u3-X53"},{"t":"아무 관계가 없다","mis":"K4-2-u3-X53"}],"explanation":["악기 안에 무엇이 있나요?","피아노·북·피리가 있어요.","포함하는 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#8','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C58',1,'mc','auto','「닭을 기르는 곳」을 바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u3-X55']::text[],false,'{"seq":8,"concept":"K4-2-u3-C58","difficulty":1,"kind":"mc","stem":"「닭을 기르는 곳」을 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"닭장","correct":true},{"t":"닥장","mis":"K4-2-u3-X55"},{"t":"달장","mis":"K4-2-u3-X55"},{"t":"닺장","mis":"K4-2-u3-X55"}],"explanation":["겹받침 ㄺ이에요.","ㄹ과 ㄱ을 함께 써요.","‘닭장’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#9','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C12',2,'mc','auto','친구 의견에 할 질문으로 상대의 기분을 헤아린 것은 무엇인가요?',ARRAY['K4-2-u3-X12','K4-2-u3-X13']::text[],false,'{"seq":9,"concept":"K4-2-u3-C12","difficulty":2,"kind":"mc","stem":"친구 의견에 할 질문으로 상대의 기분을 헤아린 것은 무엇인가요?","options":[{"t":"「번호만 맞추면 되니 편하겠네요. 그런데 새 책이 들어오면 번호는 누가 붙이나요?」","correct":true},{"t":"「그건 너무 귀찮은 방법 아닌가요?」","mis":"K4-2-u3-X12"},{"t":"「틀린 생각 같은데, 왜 그렇게 생각해요?」","mis":"K4-2-u3-X12"},{"t":"「스티커는 어느 가게에서 사나요?」","mis":"K4-2-u3-X13"}],"explanation":["좋은 점을 먼저 인정해요.","구체적으로 물어요.","첫째 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#10','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C15',2,'mc','auto','모둠 토의 주제로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u3-X09']::text[],false,'{"seq":10,"concept":"K4-2-u3-C15","difficulty":2,"kind":"mc","stem":"모둠 토의 주제로 알맞지 않은 것은 무엇인가요?","options":[{"t":"우리나라 여름 방학을 한 달 늘리려면 어떻게 할까?","correct":true},{"t":"계단 옆 게시판이 높아 1학년 동생들이 읽지 못하는 문제를 어떻게 해결할까?","mis":"K4-2-u3-X09"},{"t":"비 오는 날 현관 바닥이 미끄러운 문제를 어떻게 해결할까?","mis":"K4-2-u3-X09"},{"t":"모둠 활동 뒤 색연필이 뒤섞이는 문제를 어떻게 해결할까?","mis":"K4-2-u3-X09"}],"explanation":["우리가 해결에 나설 수 있나요?","방학은 우리가 정할 수 없어요.","첫째가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#11','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C21',2,'mc','auto','효주네 모둠이 두 의견을 합친 뒤에 한 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X19','K4-2-u3-X20','K4-2-u3-X18']::text[],false,'{"seq":11,"concept":"K4-2-u3-C21","difficulty":2,"kind":"mc","stem":"효주네 모둠이 두 의견을 합친 뒤에 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"합친 의견도 같은 기준으로 따져 보고, 해결에 도움이 적은 솔비의 의견은 넣지 않았다","correct":true},{"t":"넷을 모두 합쳐 가장 큰 의견을 만들었다","mis":"K4-2-u3-X19"},{"t":"가위바위보로 합칠 의견을 골랐다","mis":"K4-2-u3-X20"},{"t":"쉬운 의견이라는 까닭만으로 모두 뺐다","mis":"K4-2-u3-X18"}],"explanation":["결정한 의견을 봐요.","솔비의 의견은 빠졌어요.","같은 기준으로 따졌어요."],"asset":{"type":"passage","lines":["결정한 의견 — 현관 밖에서 우산 털고 접기 + 비 오는 날 등교 시간 수건 당번","결정한 까닭 — 두 의견이 서로 도와 바닥의 물을 줄이고, 우리가 할 수 있다","따로 할 일 — 발판은 우리 힘만으로 할 수 없어 학교에 제안하기로 했다"],"title":"효주네 모둠의 결정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#12','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C28',2,'ox','auto','「~하세요」로 끝나는 쪽지는 모두 제안하는 글이에요.',ARRAY['K4-2-u3-X27']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"ox","stem":"「~하세요」로 끝나는 쪽지는 모두 제안하는 글이에요.","answer":"X","reason_options":[{"t":"해결 방법과 이유 없이 막기만 하는 말은 제안하는 글로 부족하기 때문에","correct":true},{"t":"「~하세요」로 끝나면 무엇이든 제안이기 때문에","mis":"K4-2-u3-X27"}],"mis":"K4-2-u3-X27","explanation":["「복도에 앉지 마세요」를 떠올려요.","방법이 없었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#13','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C36',2,'ox','auto','「왜냐하면 ……때문입니다」를 쓰기만 하면 알맞은 이유가 돼요.',ARRAY['K4-2-u3-X36']::text[],false,'{"seq":13,"concept":"K4-2-u3-C36","difficulty":2,"kind":"ox","stem":"「왜냐하면 ……때문입니다」를 쓰기만 하면 알맞은 이유가 돼요.","answer":"X","reason_options":[{"t":"이유는 제안대로 하면 무엇이 좋아지는지 보여 주어야 하기 때문에","correct":true},{"t":"「왜냐하면」이 들어가면 모두 알맞은 이유이기 때문에","mis":"K4-2-u3-X36"}],"mis":"K4-2-u3-X36","explanation":["여원이의 ㉮를 떠올려요.","「왜냐하면」이 있어도 약했어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#14','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C34',2,'mc','auto','「계단 옆 게시판을 낮게 달아 주세요」는 누구에게 제안하는 것이 알맞나요?',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":14,"concept":"K4-2-u3-C34","difficulty":2,"kind":"mc","stem":"「계단 옆 게시판을 낮게 달아 주세요」는 누구에게 제안하는 것이 알맞나요?","options":[{"t":"학교 시설을 정할 수 있는 교장 선생님","correct":true},{"t":"게시판을 읽는 1학년 동생","mis":"K4-2-u3-X24"},{"t":"계단을 함께 오르는 짝","mis":"K4-2-u3-X24"},{"t":"게시판 글을 쓴 옆 반 친구","mis":"K4-2-u3-X24"}],"explanation":["누가 게시판을 옮기나요?","학교 시설을 정하는 분이에요.","교장 선생님이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#15','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C47',2,'mc','auto','「비누 걸이가 튼튼합니다.」에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X47','K4-2-u3-X45']::text[],false,'{"seq":15,"concept":"K4-2-u3-C47","difficulty":2,"kind":"mc","stem":"「비누 걸이가 튼튼합니다.」에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"무엇이(비누 걸이가) + 어떠하다(튼튼합니다)로 바르게 짜인 문장이다","correct":true},{"t":"사람이 나오지 않아서 어색한 문장이다","mis":"K4-2-u3-X47"},{"t":"너무 짧아서 문장이 아니다","mis":"K4-2-u3-X47"},{"t":"누가 + 어찌하다 짜임의 문장이다","mis":"K4-2-u3-X45"}],"explanation":["「무엇이」 칸을 봐요.","물건도 와요.","어떠하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#16','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C38',2,'mc','auto','제안하는 이유를 나타내는 표현은 무엇인가요?',ARRAY['K4-2-u3-X40']::text[],false,'{"seq":16,"concept":"K4-2-u3-C38","difficulty":2,"kind":"mc","stem":"제안하는 이유를 나타내는 표현은 무엇인가요?","options":[{"t":"「……면 ……할 수 있습니다」","correct":true},{"t":"「……면 좋겠습니다」","mis":"K4-2-u3-X40"},{"t":"「……면 어떨까요?」","mis":"K4-2-u3-X40"},{"t":"「……합시다」","mis":"K4-2-u3-X40"}],"explanation":["세 개는 제안 표현이에요.","좋아지는 점을 말해요.","할 수 있습니다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#17','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C31',3,'mc','auto','「모둠 친구가 내 연필을 말없이 자꾸 가져간다」에 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u3-X04','K4-2-u3-X28']::text[],false,'{"seq":17,"concept":"K4-2-u3-C31","difficulty":3,"kind":"mc","stem":"「모둠 친구가 내 연필을 말없이 자꾸 가져간다」에 알맞은 방법은 무엇인가요?","options":[{"t":"그 친구에게 직접 차분히 말한다","correct":true},{"t":"교장 선생님께 제안하는 글을 쓴다","mis":"K4-2-u3-X04"},{"t":"전교 학생 자치회 안건으로 낸다","mis":"K4-2-u3-X04"},{"t":"「연필 가져가지 마세요」 쪽지만 붙인다","mis":"K4-2-u3-X28"}],"explanation":["누구와의 일인가요?","두 사람 사이의 일이에요.","직접 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#18','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C51',3,'ox','auto','다툼이 없어지기만 하면 무엇을 없애든 알맞은 해결이에요.',ARRAY['K4-2-u3-X49']::text[],false,'{"seq":18,"concept":"K4-2-u3-C51","difficulty":3,"kind":"ox","stem":"다툼이 없어지기만 하면 무엇을 없애든 알맞은 해결이에요.","answer":"X","reason_options":[{"t":"해결은 문제만 없애는 것이 아니라 원래 바라던 모습을 이루는 것이기 때문에","correct":true},{"t":"다툼이 사라지는 것이 가장 확실한 해결이기 때문에","mis":"K4-2-u3-X49"}],"mis":"K4-2-u3-X49","explanation":["놀잇감을 모두 치우면요?","함께 놀 수 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#19','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C43',3,'ox','auto','이유가 강해 보이도록 확인하지 않은 짐작을 사실처럼 써도 돼요.',ARRAY['K4-2-u3-X38']::text[],false,'{"seq":19,"concept":"K4-2-u3-C43","difficulty":3,"kind":"ox","stem":"이유가 강해 보이도록 확인하지 않은 짐작을 사실처럼 써도 돼요.","answer":"X","reason_options":[{"t":"확인하지 않은 짐작을 사실처럼 쓰면 읽는 사람이 글을 믿을 수 없기 때문에","correct":true},{"t":"이유는 강해 보이기만 하면 되기 때문에","mis":"K4-2-u3-X38"}],"mis":"K4-2-u3-X38","explanation":["선재는 여쭈어 확인했어요.","지어내지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#20','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C30',3,'ox','auto','제안하는 글을 쓰면 문제와 해결 방법을 더 또렷하게 정리하게 돼요.',ARRAY['K4-2-u3-X30']::text[],false,'{"seq":20,"concept":"K4-2-u3-C30","difficulty":3,"kind":"ox","stem":"제안하는 글을 쓰면 문제와 해결 방법을 더 또렷하게 정리하게 돼요.","answer":"O","reason_options":[{"t":"글로 쓰면서 무엇이 불편하고 무엇을 바라는지 차례대로 생각하게 되기 때문에","correct":true},{"t":"글로 쓰면 제안이 언제나 받아들여지기 때문에","mis":"K4-2-u3-X30"}],"mis":"K4-2-u3-X30","explanation":["쓰면서 정리돼요.","「언제나 받아들여진다」는 아니에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#21','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C9',3,'mc','auto','호연이네 반이 두 문제 가운데 「학급 문고」를 먼저 다룬 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X08','K4-2-u3-X25']::text[],false,'{"seq":21,"concept":"K4-2-u3-C9","difficulty":3,"kind":"mc","stem":"호연이네 반이 두 문제 가운데 「학급 문고」를 먼저 다룬 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"책을 찾느라 쉬는 시간을 다 쓰는 친구가 많아 더 급하다는 까닭이 가장 많았기 때문에","correct":true},{"t":"성주가 먼저 말했기 때문에","mis":"K4-2-u3-X08"},{"t":"사회자가 좋아하는 문제였기 때문에","mis":"K4-2-u3-X08"},{"t":"사물함 문제는 아무도 겪지 않기 때문에","mis":"K4-2-u3-X25"}],"explanation":["사회자는 까닭을 들게 했어요.","더 급한 까닭이 있었어요.","그래서 먼저 다뤘어요."],"asset":{"type":"speech","turns":[{"who":"사회자 호연","text":"우리 반에서 함께 해결하고 싶은 문제가 있나요?"},{"who":"성주","text":"학급 문고 책이 제자리로 돌아오지 않아서 읽고 싶은 책을 찾기 어렵습니다."},{"who":"초은","text":"사물함 위에 물건이 쌓여 있어서 떨어질 때가 있습니다."},{"who":"사회자 호연","text":"두 문제 가운데 무엇이 더 급한지 까닭을 들어 말해 봅시다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#22','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C49',3,'mc','auto','아파트 이웃에게 「놀이 시설 옆 의자를 고쳐 주세요」라는 글을 알리려고 해요. 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u3-X48']::text[],false,'{"seq":22,"concept":"K4-2-u3-C49","difficulty":3,"kind":"mc","stem":"아파트 이웃에게 「놀이 시설 옆 의자를 고쳐 주세요」라는 글을 알리려고 해요. 알맞은 방법은 무엇인가요?","options":[{"t":"관리 사무소의 허락을 받아 아파트 게시판에 붙인다","correct":true},{"t":"학교 교실 칠판에 붙인다","mis":"K4-2-u3-X48"},{"t":"허락 없이 아파트 현관문마다 붙인다","mis":"K4-2-u3-X48"},{"t":"시청 누리집에 우리 반 이야기로 올린다","mis":"K4-2-u3-X48"}],"explanation":["누가 읽어야 하나요?","이웃이에요.","허락을 받아 게시판에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#23','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C36',4,'mc','auto','하린이의 글을 더 좋게 고치는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X36','K4-2-u3-X39','K4-2-u3-X38']::text[],false,'{"seq":23,"concept":"K4-2-u3-C36","difficulty":4,"kind":"mc","stem":"하린이의 글을 더 좋게 고치는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"문제 상황에 겪은 일을 구체적으로 보태고, 이유에는 여러 친구에게 좋아지는 점과 확인한 사실을 쓴다","correct":true},{"t":"「왜냐하면」을 모든 문장 앞에 붙인다","mis":"K4-2-u3-X36"},{"t":"「무조건 열어 주세요」로 강하게 끝맺는다","mis":"K4-2-u3-X39"},{"t":"「다른 학교는 다 열 것 같다」는 짐작을 사실처럼 보탠다","mis":"K4-2-u3-X38"}],"explanation":["문제 상황은 구체적으로요.","이유는 좋아지는 점과 사실로요.","예의 있게 써요."],"asset":{"type":"passage","lines":["1 도서실 담당 선생님, 안녕하세요? 저는 4학년 하린입니다.","2 점심시간에 도서실 문이 닫혀 있어서, 책을 빌리려는 친구들이","   쉬는 시간마다 한꺼번에 몰려 줄이 깁니다.","3 점심시간에도 도서실을 열고, 도서 도우미가 돌아가며 도우면 어떨까요?","4 그러면 책을 빌리는 친구들이 나뉘어 쉬는 시간에 붐비지 않고,","   점심을 먹은 뒤 조용히 책을 읽을 곳도 생깁니다."],"title":"하린이의 글 「점심시간에도 도서실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#24','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C27',4,'essay','teacher','「강당 문이 무거워 동생들이 혼자 열기 어렵다」를 문제 상황으로 하여, 문제 상황 · 제안하는 내용 · 제안하는 이유가 드러나게 교장 선생님께 드리는 제안하는 글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C27","difficulty":4,"kind":"essay","stem":"「강당 문이 무거워 동생들이 혼자 열기 어렵다」를 문제 상황으로 하여, 문제 상황 · 제안하는 내용 · 제안하는 이유가 드러나게 교장 선생님께 드리는 제안하는 글을 쓰세요.","answer_guide":{"answer":"예: 교장 선생님, 안녕하세요? 저는 4학년 ○○입니다. 강당 문이 무거워서 1·2학년 동생들이 혼자 열지 못하고 문 앞에서 기다리는 일이 많습니다. 강당 문에 문이 천천히 닫히는 장치를 달거나, 가벼운 문을 하나 더 만들어 주시면 좋겠습니다. 그러면 동생들도 스스로 강당에 드나들 수 있고, 문에 손이 끼일 걱정도 줄어듭니다. 제 제안을 살펴봐 주시기를 부탁드립니다.","scoring_points":["겪은 문제 상황을 구체적으로 썼는가","실천할 수 있는 제안하는 내용을 썼는가","여러 사람에게 좋아지는 점을 이유로 예의 있게 썼는가"]},"explanation":["불편한 점을 써요.","바라는 점을 써요.","좋아지는 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_b#25','kor',4,2,'u3','','g4_2_kor_u3_review_b','unit_review','K4-2-u3-C46',4,'essay','teacher','「수돗가는 손을 씻는 곳을 좋아합니다.」와 「비누 걸이가 있는 수돗가를 편리합니다.」를 바르게 고쳐 쓰고, 「‘누가/무엇이’ 칸에는 사람만 온다」는 생각이 왜 알맞지 않은지 예를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C46","difficulty":4,"kind":"essay","stem":"「수돗가는 손을 씻는 곳을 좋아합니다.」와 「비누 걸이가 있는 수돗가를 편리합니다.」를 바르게 고쳐 쓰고, 「‘누가/무엇이’ 칸에는 사람만 온다」는 생각이 왜 알맞지 않은지 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「수돗가는 손을 씻는 곳입니다.」, 「비누 걸이가 있는 수돗가는 편리합니다.」로 고친다. 「비누 걸이가 튼튼합니다.」처럼 물건도 「무엇이」 칸에 올 수 있으므로 사람만 온다는 생각은 알맞지 않다.","scoring_points":["첫 문장을 무엇이다 짜임으로 고쳤는가","둘째 문장을 어떠하다 짜임으로 고쳤는가","물건이 「무엇이」 칸에 온 예를 들었는가"]},"explanation":["소리 내어 읽어요.","앞과 뒤가 어울리게요.","물건도 「무엇이」예요."],"asset":{"type":"passage","lines":["1 수돗가는 손을 씻는 곳을 좋아합니다.","2 우리는 비누로 손을 깨끗합니다.","3 비누 걸이가 있는 수돗가를 편리합니다."],"title":"선재의 첫 글 가운데 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#1','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C2',1,'mc','auto','교실 앞문 문턱 이야기에서 반 친구들이 한 일은 무엇인가요?',ARRAY['K4-2-u3-X01']::text[],false,'{"seq":1,"concept":"K4-2-u3-C2","difficulty":1,"kind":"mc","stem":"교실 앞문 문턱 이야기에서 반 친구들이 한 일은 무엇인가요?","options":[{"t":"왜 걸리는지, 어떻게 하면 좋을지 함께 이야기해 선생님께 알렸다","correct":true},{"t":"각자 조심하자고 마음먹고 그냥 지나쳤다","mis":"K4-2-u3-X01"},{"t":"한 친구가 혼자 정해 모두에게 따르라고 했다","mis":"K4-2-u3-X01"},{"t":"누구 잘못인지 가리려고 말다툼했다","mis":"K4-2-u3-X01"}],"explanation":["함께 이야기했어요.","해결 방법을 찾았어요.","그것이 토의예요."],"asset":{"type":"passage","lines":["교실 앞문 문턱에 발이 걸려 넘어질 뻔한 친구가 여럿이었어요.","반 친구들이 왜 걸리는지, 어떻게 하면 좋을지 함께 이야기해 선생님께 알렸어요.","얼마 뒤 문턱에 눈에 잘 띄는 밝은 색 띠가 붙었어요."],"title":"모두가 그냥 지나쳤던 문턱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#2','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C8',1,'ox','auto','토의 절차에서 「의견 마련하기」는 주제에 맞는 의견과 뒷받침할 이유를 준비하는 단계예요.',ARRAY['K4-2-u3-X07']::text[],false,'{"seq":2,"concept":"K4-2-u3-C8","difficulty":1,"kind":"ox","stem":"토의 절차에서 「의견 마련하기」는 주제에 맞는 의견과 뒷받침할 이유를 준비하는 단계예요.","answer":"O","reason_options":[{"t":"주제를 정한 뒤 내 의견과 이유를 먼저 준비해야 모을 수 있기 때문에","correct":true},{"t":"마지막에 가장 알맞은 의견을 정하는 단계이기 때문에","mis":"K4-2-u3-X07"}],"mis":"K4-2-u3-X07","explanation":["둘째 단계예요.","의견과 이유를 준비해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#3','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C25',1,'ox','auto','학교 수돗가에 비누를 놓아 달라는 제안은 같은 반 짝에게 하는 것이 가장 알맞아요.',ARRAY['K4-2-u3-X24']::text[],false,'{"seq":3,"concept":"K4-2-u3-C25","difficulty":1,"kind":"ox","stem":"학교 수돗가에 비누를 놓아 달라는 제안은 같은 반 짝에게 하는 것이 가장 알맞아요.","answer":"X","reason_options":[{"t":"학교 시설을 정할 수 있는 교장 선생님께 해야 바뀔 수 있기 때문에","correct":true},{"t":"가까이 있는 사람에게 제안해야 빨리 바뀌기 때문에","mis":"K4-2-u3-X24"}],"mis":"K4-2-u3-X24","explanation":["누가 수돗가를 바꾸나요?","학교 시설을 정하는 분이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#4','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C27',1,'ox','auto','제안하는 글에는 문제 상황 · 제안하는 내용 · 제안하는 이유가 들어가요.',ARRAY['K4-2-u3-X31']::text[],false,'{"seq":4,"concept":"K4-2-u3-C27","difficulty":1,"kind":"ox","stem":"제안하는 글에는 문제 상황 · 제안하는 내용 · 제안하는 이유가 들어가요.","answer":"O","reason_options":[{"t":"불편한 점과 바라는 점, 그러면 좋아지는 점을 알아야 읽는 사람이 바꾸고 싶어지기 때문에","correct":true},{"t":"속상한 마음을 쏟아 내는 글이기 때문에","mis":"K4-2-u3-X31"}],"mis":"K4-2-u3-X31","explanation":["세 가지를 떠올려요.","불편 · 바람 · 좋아지는 점","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#5','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C45',1,'mc','auto','「누가/무엇이 + 어떠하다」 짜임의 문장은 무엇인가요?',ARRAY['K4-2-u3-X45']::text[],false,'{"seq":5,"concept":"K4-2-u3-C45","difficulty":1,"kind":"mc","stem":"「누가/무엇이 + 어떠하다」 짜임의 문장은 무엇인가요?","options":[{"t":"「교실이 조용합니다.」","correct":true},{"t":"「친구가 노래합니다.」","mis":"K4-2-u3-X45"},{"t":"「이것은 연필입니다.」","mis":"K4-2-u3-X45"},{"t":"「동생이 웃습니다.」","mis":"K4-2-u3-X45"}],"explanation":["모습을 나타내요.","조용하다는 모습이에요.","어떠하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#6','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C55',1,'ox','auto','「밥」과 「먹다」가 이어지면 언제나 「밥먹다」로 붙여 써요.',ARRAY['K4-2-u3-X51']::text[],false,'{"seq":6,"concept":"K4-2-u3-C55","difficulty":1,"kind":"ox","stem":"「밥」과 「먹다」가 이어지면 언제나 「밥먹다」로 붙여 써요.","answer":"X","reason_options":[{"t":"「밥 먹다」는 하나의 낱말이 된 것이 아니라서 띄어 쓰기 때문에","correct":true},{"t":"두 낱말이 이어지면 언제나 붙여 쓰기 때문에","mis":"K4-2-u3-X51"}],"mis":"K4-2-u3-X51","explanation":["한 낱말이 되었나요?","그렇지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#7','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C57',1,'mc','auto','「모자를 벗다」의 반대말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X54']::text[],false,'{"seq":7,"concept":"K4-2-u3-C57","difficulty":1,"kind":"mc","stem":"「모자를 벗다」의 반대말로 알맞은 것은 무엇인가요?","options":[{"t":"모자를 쓰다","correct":true},{"t":"모자를 입다","mis":"K4-2-u3-X54"},{"t":"모자를 신다","mis":"K4-2-u3-X54"},{"t":"모자를 끼다","mis":"K4-2-u3-X54"}],"explanation":["모자를 머리에 얹을 때를 떠올려요.","「쓰다」라고 해요.","반대말은 쓰임에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#8','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C4',1,'mc','auto','토의할 때의 바른 태도는 무엇인가요?',ARRAY['K4-2-u3-X03']::text[],false,'{"seq":8,"concept":"K4-2-u3-C4","difficulty":1,"kind":"mc","stem":"토의할 때의 바른 태도는 무엇인가요?","options":[{"t":"손을 들고 내 차례가 되면 말한다","correct":true},{"t":"내 생각과 다르면 바로 끼어들어 말한다","mis":"K4-2-u3-X03"},{"t":"목소리가 큰 친구의 의견을 그대로 따른다","mis":"K4-2-u3-X03"},{"t":"다른 의견은 듣지 않고 내 의견만 말한다","mis":"K4-2-u3-X03"}],"explanation":["차례를 지켜요.","끝까지 들어요.","손을 들고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#9','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C13',2,'ox','auto','「좋은 의견이에요」라는 말만 붙이면 무엇을 묻든 좋은 질문이에요.',ARRAY['K4-2-u3-X13']::text[],false,'{"seq":9,"concept":"K4-2-u3-C13","difficulty":2,"kind":"ox","stem":"「좋은 의견이에요」라는 말만 붙이면 무엇을 묻든 좋은 질문이에요.","answer":"X","reason_options":[{"t":"질문은 의견이 문제를 해결하는지 따지는 데 도움이 되어야 하기 때문에","correct":true},{"t":"공손한 말투만 있으면 질문의 목적을 이루기 때문에","mis":"K4-2-u3-X13"}],"mis":"K4-2-u3-X13","explanation":["말투와 내용을 따로 봐요.","내용도 중요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#10','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C16',2,'ox','auto','「현관에서 미끄러질 뻔한 친구가 있다」는 현관 바닥 문제가 생긴 까닭이에요.',ARRAY['K4-2-u3-X16']::text[],false,'{"seq":10,"concept":"K4-2-u3-C16","difficulty":2,"kind":"ox","stem":"「현관에서 미끄러질 뻔한 친구가 있다」는 현관 바닥 문제가 생긴 까닭이에요.","answer":"X","reason_options":[{"t":"미끄러질 뻔한 것은 바닥에 물이 고여서 생긴 영향이기 때문에","correct":true},{"t":"눈에 보이는 일은 모두 까닭이기 때문에","mis":"K4-2-u3-X16"}],"mis":"K4-2-u3-X16","explanation":["왜 미끄러웠나요?","물이 고여서예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#11','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C18',2,'ox','auto','쉽게 할 수 있는 의견은 해결에 도움이 되더라도 모두 버려야 해요.',ARRAY['K4-2-u3-X18']::text[],false,'{"seq":11,"concept":"K4-2-u3-C18","difficulty":2,"kind":"ox","stem":"쉽게 할 수 있는 의견은 해결에 도움이 되더라도 모두 버려야 해요.","answer":"X","reason_options":[{"t":"쉬운지와 해결되는지를 함께 따져, 해결에 도움이 되면 쉬운 의견도 좋은 의견이기 때문에","correct":true},{"t":"쉬운 의견은 모두 쓸모없기 때문에","mis":"K4-2-u3-X18"}],"mis":"K4-2-u3-X18","explanation":["효주의 우산 털기는 쉬워요.","그래도 물이 줄어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#12','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C28',2,'mc','auto','쪽지 「신발장 위에 실내화를 두지 마세요.」에 보태면 제안하는 글에 가까워지는 것은 무엇인가요?',ARRAY['K4-2-u3-X28','K4-2-u3-X27','K4-2-u3-X31']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"mc","stem":"쪽지 「신발장 위에 실내화를 두지 마세요.」에 보태면 제안하는 글에 가까워지는 것은 무엇인가요?","options":[{"t":"실내화를 둘 곳(해결 방법)과 그러면 좋아지는 점(이유)","correct":true},{"t":"「절대」와 느낌표","mis":"K4-2-u3-X28"},{"t":"「꼭이요」라는 말","mis":"K4-2-u3-X27"},{"t":"실내화를 올려 두는 사람이 싫다는 마음","mis":"K4-2-u3-X31"}],"explanation":["막기만 하면 부족해요.","방법을 내놓아요.","이유도 써요."],"asset":{"type":"passage","lines":["「신발장 위에 실내화를 두지 마세요.」"],"title":"현관 신발장에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#13','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C37',2,'mc','auto','여원이의 글에서 문제 상황을 구체적으로 쓴 부분은 무엇인가요?',ARRAY['K4-2-u3-X42']::text[],false,'{"seq":13,"concept":"K4-2-u3-C37","difficulty":2,"kind":"mc","stem":"여원이의 글에서 문제 상황을 구체적으로 쓴 부분은 무엇인가요?","options":[{"t":"「지난 토요일 정류장에 갔는데, 노선 안내판이 높이 붙어 있고 글자가 작아서 탈 버스를 찾기 어려웠습니다.」","correct":true},{"t":"「정류장이 좀 불편합니다.」","mis":"K4-2-u3-X42"},{"t":"「저는 4학년 여원입니다.」","mis":"K4-2-u3-X42"},{"t":"「제 제안을 살펴봐 주시기를 부탁드립니다.」","mis":"K4-2-u3-X42"}],"explanation":["겪은 일을 봐요.","언제, 무엇이 불편했나요?","2번 문장이에요."],"asset":{"type":"passage","lines":["1 ○○시청 버스 정류장 담당자님, 안녕하세요? 저는 4학년 여원입니다.","2 지난 토요일 정류장에 갔는데, 노선 안내판이 높이 붙어 있고","   글자가 작아서 탈 버스를 찾기 어려웠습니다.","3 어린이와 어르신 눈높이에 안내판을 하나 더 달고, 글자를 크게 해 주시면 좋겠습니다.","4 왜냐하면 누구나 스스로 탈 버스를 찾을 수 있기 때문입니다.","5 정류장을 이용하는 모든 사람을 위해 제 제안을 살펴봐 주시기를 부탁드립니다."],"title":"여원이의 글 「버스 정류장 안내판을 눈높이에 맞춰 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#14','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C35',2,'ox','auto','문제만 해결된다면 실천하기 어려운 제안도 알맞은 제안이에요.',ARRAY['K4-2-u3-X34']::text[],false,'{"seq":14,"concept":"K4-2-u3-C35","difficulty":2,"kind":"ox","stem":"문제만 해결된다면 실천하기 어려운 제안도 알맞은 제안이에요.","answer":"X","reason_options":[{"t":"제안하는 내용은 문제를 해결하면서 실제로 할 수 있어야 하기 때문에","correct":true},{"t":"해결만 되면 어떻게 하든 상관없기 때문에","mis":"K4-2-u3-X34"}],"mis":"K4-2-u3-X34","explanation":["하루 종일 안내하는 사람을 떠올려요.","실천이 어려워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#15','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C46',2,'mc','auto','「점심시간의 도서실을 조용합니다.」를 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u3-X46']::text[],false,'{"seq":15,"concept":"K4-2-u3-C46","difficulty":2,"kind":"mc","stem":"「점심시간의 도서실을 조용합니다.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"「점심시간의 도서실은 조용합니다.」","correct":true},{"t":"「점심시간의 도서실을 조용히.」","mis":"K4-2-u3-X46"},{"t":"「점심시간을 도서실은 조용합니다.」","mis":"K4-2-u3-X46"},{"t":"「도서실을 점심시간이 조용합니다.」","mis":"K4-2-u3-X46"}],"explanation":["「무엇이」 칸이 어울리나요?","「도서실은」으로 고쳐요.","무엇이 + 어떠하다예요."],"asset":{"type":"passage","lines":["① 도서실은 책을 빌리는 곳을 좋아합니다.","② 친구들은 점심시간에 책을 즐겁습니다.","③ 점심시간의 도서실을 조용합니다."],"title":"하린이의 첫 글 가운데 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#16','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C23',2,'ox','auto','「현관을 안전하게 하려고 열심히 노력한다」는 구체적인 실천 계획이에요.',ARRAY['K4-2-u3-X21']::text[],false,'{"seq":16,"concept":"K4-2-u3-C23","difficulty":2,"kind":"ox","stem":"「현관을 안전하게 하려고 열심히 노력한다」는 구체적인 실천 계획이에요.","answer":"X","reason_options":[{"t":"언제, 누가, 무엇을 할지가 드러나지 않기 때문에","correct":true},{"t":"노력한다는 말이 들어가면 구체적인 계획이기 때문에","mis":"K4-2-u3-X21"}],"mis":"K4-2-u3-X21","explanation":["언제 하나요?","누가 하나요?","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#17','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C6',3,'error','auto','문제를 해결하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X05','K4-2-u3-X04']::text[],false,'{"seq":17,"concept":"K4-2-u3-C6","difficulty":3,"kind":"error","stem":"문제를 해결하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「토의로 정했으면 다른 반에 알리는 글은 쓸 필요 없어.」","correct":true,"mis_target":"K4-2-u3-X05"},{"t":"친구 가 — 「토의로 정한 방법을 제안하는 글로 알릴 수 있어.」","mis":"K4-2-u3-X04"},{"t":"친구 다 — 「두 사람 사이의 일은 직접 말하는 게 알맞아.」","mis":"K4-2-u3-X04"}],"explanation":["토의와 글은 이어져요.","예슬이를 떠올려요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#18','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C51',3,'mc','auto','놀잇감 다툼 의견 가운데 질문 쪽지를 가장 많이 받은 의견에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X14','K4-2-u3-X49']::text[],false,'{"seq":18,"concept":"K4-2-u3-C51","difficulty":3,"kind":"mc","stem":"놀잇감 다툼 의견 가운데 질문 쪽지를 가장 많이 받은 의견에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"쪽지 수가 아니라 바라는 모습을 이루는지로 좋은 의견을 가린다","correct":true},{"t":"쪽지를 가장 많이 받았으니 가장 좋은 의견이다","mis":"K4-2-u3-X14"},{"t":"쪽지를 많이 받았으니 가장 나쁜 의견이다","mis":"K4-2-u3-X14"},{"t":"다툼만 없애면 되니 쪽지 수는 상관없이 ㉰를 고른다","mis":"K4-2-u3-X49"}],"explanation":["개수가 기준이 아니에요.","바라는 모습은?","함께 즐겁게 놀기예요."],"asset":{"type":"passage","lines":["누리집 글 — 쉬는 시간마다 교실 놀잇감을 서로 먼저 하려고 다투는 일이 생겨요.","함께 즐겁게 놀려면 어떻게 하면 좋을까요?","㉮ 요일마다 놀잇감을 쓸 모둠을 정하자. 모든 모둠이 돌아가며 쓸 수 있기 때문이다.","㉯ 모래시계를 두고 한 판이 끝나면 다음 친구에게 넘기자.","㉰ 놀잇감을 모두 치워 버리자. 다툴 일이 없어지기 때문이다."],"title":"칠판에 붙은 의견 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#19','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C43',3,'mc','auto','선재가 「비누로 씻으면 세균을 더 잘 없앤다」를 이유에 넣기 전에 한 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X38','K4-2-u3-X37']::text[],false,'{"seq":19,"concept":"K4-2-u3-C43","difficulty":3,"kind":"mc","stem":"선재가 「비누로 씻으면 세균을 더 잘 없앤다」를 이유에 넣기 전에 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"보건 선생님께 여쭈어 확인했다","correct":true},{"t":"그럴 것 같아서 바로 썼다","mis":"K4-2-u3-X38"},{"t":"친구에게 들은 소문을 그대로 옮겼다","mis":"K4-2-u3-X38"},{"t":"비누 향기가 좋아서 넣었다","mis":"K4-2-u3-X37"}],"explanation":["계획의 「확인한 사실」을 봐요.","여쭈어 보았어요.","확인한 뒤에 썼어요."],"asset":{"type":"passage","lines":["문제 상황 — 운동장 수돗가에 비누가 없어 손을 물로만 헹군다","제안하는 대상 — 학교 시설을 정할 수 있는 교장 선생님","제안하는 내용 — 수돗가마다 물이 잘 빠지는 비누 걸이를 달고 비누를 놓자","확인한 사실 — 보건 선생님께 여쭈어 보니, 비누로 씻으면","   물로만 씻을 때보다 손의 세균을 더 잘 없앨 수 있다고 하셨다"],"title":"선재의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#20','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C30',3,'mc','auto','제안하는 글을 쓰면 좋은 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u3-X31']::text[],false,'{"seq":20,"concept":"K4-2-u3-C30","difficulty":3,"kind":"mc","stem":"제안하는 글을 쓰면 좋은 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"속상한 마음을 마음껏 쏟아 낼 수 있다","correct":true},{"t":"만나기 어려운 분께도 차분히 전할 수 있다","mis":"K4-2-u3-X31"},{"t":"읽은 사람들도 문제에 관심을 둘 수 있다","mis":"K4-2-u3-X31"},{"t":"문제와 해결 방법이 또렷하게 정리된다","mis":"K4-2-u3-X31"}],"explanation":["제안하는 글은 무엇을 내놓나요?","해결 방법이에요.","불만을 쏟는 글이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#21','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C42',3,'ox','auto','「짝이 내 그림을 보고 웃어서 속상했다」는 교장 선생님께 제안하는 글로 해결하기에 알맞은 문제예요.',ARRAY['K4-2-u3-X43']::text[],false,'{"seq":21,"concept":"K4-2-u3-C42","difficulty":3,"kind":"ox","stem":"「짝이 내 그림을 보고 웃어서 속상했다」는 교장 선생님께 제안하는 글로 해결하기에 알맞은 문제예요.","answer":"X","reason_options":[{"t":"두 사람 사이의 속상한 일은 짝에게 직접 마음을 말하는 것이 알맞기 때문에","correct":true},{"t":"속상한 일은 모두 제안하는 글로 써야 하기 때문에","mis":"K4-2-u3-X43"}],"mis":"K4-2-u3-X43","explanation":["누구와의 일인가요?","짝과의 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#22','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C53',3,'ox','auto','전교 학생 자치회 안건은 많은 학생과 관련 있고 실천할 수 있으며 공감을 얻은 제안이 알맞아요.',ARRAY['K4-2-u3-X50']::text[],false,'{"seq":22,"concept":"K4-2-u3-C53","difficulty":3,"kind":"ox","stem":"전교 학생 자치회 안건은 많은 학생과 관련 있고 실천할 수 있으며 공감을 얻은 제안이 알맞아요.","answer":"O","reason_options":[{"t":"학생 자치회는 어느 반만이 아니라 학교 모두의 일을 다루기 때문에","correct":true},{"t":"목소리를 크게 발표한 제안이 뽑히기 때문에","mis":"K4-2-u3-X50"}],"mis":"K4-2-u3-X50","explanation":["자치회는 학교 전체의 일이에요.","많은 학생과 관련 있어야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#23','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C21',4,'mc','auto','다온이네 모둠의 의견 넷을 견준 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X17','K4-2-u3-X19','K4-2-u3-X49']::text[],false,'{"seq":23,"concept":"K4-2-u3-C21","difficulty":4,"kind":"mc","stem":"다온이네 모둠의 의견 넷을 견준 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「㉱는 쉽지만 해결이 안 되고, ㉰는 바라는 모습까지 없애. ㉮와 ㉯는 해결에 도움이 되고 실천할 수 있으니 합쳐도 같은 기준으로 따져 보자.」","correct":true},{"t":"「㉱가 가장 쉬우니 ㉱로 정하자.」","mis":"K4-2-u3-X17"},{"t":"「넷을 모두 합치면 언제나 가장 좋아.」","mis":"K4-2-u3-X19"},{"t":"「㉰는 작품이 떨어질 일이 없으니 가장 확실해.」","mis":"K4-2-u3-X49"}],"explanation":["쉬운지와 해결되는지 함께요.","바라는 모습도 봐요.","합친 것도 따져요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#24','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C18',4,'essay','teacher','「교실 화분이 자꾸 시드는 문제」로 토의한다면 내 의견과 이유를 쓰고, 「마음속으로 화분을 아끼자」라는 의견이 쉬운데도 알맞지 않은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C18","difficulty":4,"kind":"essay","stem":"「교실 화분이 자꾸 시드는 문제」로 토의한다면 내 의견과 이유를 쓰고, 「마음속으로 화분을 아끼자」라는 의견이 쉬운데도 알맞지 않은 까닭을 쓰세요.","answer_guide":{"answer":"예: 요일마다 물을 주는 당번을 두 사람씩 정하면 좋겠다. 왜냐하면 물 주는 날을 잊지 않아 화분이 마르지 않기 때문이다. 「마음속으로 화분을 아끼자」는 쉽게 할 수 있지만, 그렇게 해도 화분에 물을 주는 사람이 정해지지 않아 화분이 시드는 문제가 해결되지 않는다. 쉬운지와 해결되는지를 함께 따져야 한다.","scoring_points":["내 의견과 이유를 썼는가","「마음속으로」 의견이 해결에 도움이 적다고 썼는가","쉬운지와 해결되는지를 함께 따져야 한다고 썼는가"]},"explanation":["의견과 이유를 써요.","마음만으로는 물이 안 줘져요.","해결되는지 따져요."],"asset":{"type":"passage","lines":["주제 — 교실 화분이 자꾸 시드는 문제를 어떻게 해결할까?","한빛 — 「요일마다 물을 주는 사람을 정하면 좋겠습니다.」","예슬 — 「우리 반에서 정한 방법을 다른 반에도 알리고 싶어.」"],"title":"한빛이네 반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_c#25','kor',4,2,'u3','','g4_2_kor_u3_review_c','unit_review','K4-2-u3-C51',4,'essay','teacher','「쉬는 시간 놀잇감 다툼」을 해결하는 내 의견과 이유를 쓰고, 「놀잇감을 모두 치우자」가 왜 알맞은 해결이 아닌지 「바라는 모습」이라는 말을 넣어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C51","difficulty":4,"kind":"essay","stem":"「쉬는 시간 놀잇감 다툼」을 해결하는 내 의견과 이유를 쓰고, 「놀잇감을 모두 치우자」가 왜 알맞은 해결이 아닌지 「바라는 모습」이라는 말을 넣어 쓰세요.","answer_guide":{"answer":"예: 놀잇감마다 쓸 순서를 적는 순서판을 두면 좋겠다. 왜냐하면 차례가 정해져 다투지 않고 모두가 돌아가며 놀 수 있기 때문이다. 「놀잇감을 모두 치우자」는 다툼은 없애지만 함께 즐겁게 놀자는 바라는 모습까지 없애기 때문에 알맞은 해결이 아니다.","scoring_points":["내 의견과 이유를 썼는가","「바라는 모습」을 넣어 ㉰가 알맞지 않은 까닭을 썼는가","내 의견이 바라는 모습을 이루는지 드러냈는가"]},"explanation":["의견과 이유를 써요.","바라는 모습은?","함께 즐겁게 놀기예요."],"asset":{"type":"passage","lines":["누리집 글 — 쉬는 시간마다 교실 놀잇감을 서로 먼저 하려고 다투는 일이 생겨요.","함께 즐겁게 놀려면 어떻게 하면 좋을까요?","㉮ 요일마다 놀잇감을 쓸 모둠을 정하자. 모든 모둠이 돌아가며 쓸 수 있기 때문이다.","㉯ 모래시계를 두고 한 판이 끝나면 다음 친구에게 넘기자.","㉰ 놀잇감을 모두 치워 버리자. 다툴 일이 없어지기 때문이다."],"title":"칠판에 붙은 의견 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#1','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C3',1,'mc','auto','토의할 까닭이 없는 일은 무엇인가요?',ARRAY['K4-2-u3-X02']::text[],false,'{"seq":1,"concept":"K4-2-u3-C3","difficulty":1,"kind":"mc","stem":"토의할 까닭이 없는 일은 무엇인가요?","options":[{"t":"3 더하기 4의 답","correct":true},{"t":"학급 행사 날 우리 반이 함께 할 활동","mis":"K4-2-u3-X02"},{"t":"음수대 앞 줄이 긴 문제를 해결하는 방법","mis":"K4-2-u3-X02"},{"t":"학급 문고 책이 제자리로 돌아오게 하는 방법","mis":"K4-2-u3-X02"}],"explanation":["답이 하나로 정해졌나요?","7로 정해져 있어요.","토의할 까닭이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#2','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C8',1,'mc','auto','「의견 모으기」 단계에서 하는 일은 무엇인가요?',ARRAY['K4-2-u3-X07']::text[],false,'{"seq":2,"concept":"K4-2-u3-C8","difficulty":1,"kind":"mc","stem":"「의견 모으기」 단계에서 하는 일은 무엇인가요?","options":[{"t":"의견을 나누며 알맞은지 서로 묻고 따진다","correct":true},{"t":"기준을 세워 가장 알맞은 의견을 정한다","mis":"K4-2-u3-X07"},{"t":"우리가 풀 수 있는 문제를 고른다","mis":"K4-2-u3-X07"},{"t":"토의 결과를 제안하는 글로 쓴다","mis":"K4-2-u3-X07"}],"explanation":["셋째 단계예요.","서로 의견을 나눠요.","묻고 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#3','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C5',1,'mc','auto','「제안하는 글」을 바르게 설명한 것은 무엇인가요?',ARRAY['K4-2-u3-X31','K4-2-u3-X57']::text[],false,'{"seq":3,"concept":"K4-2-u3-C5","difficulty":1,"kind":"mc","stem":"「제안하는 글」을 바르게 설명한 것은 무엇인가요?","options":[{"t":"제안하는 내용을 담아 쓴 글","correct":true},{"t":"속상한 마음만 적은 글","mis":"K4-2-u3-X31"},{"t":"있었던 일을 날짜 차례로 적은 일기","mis":"K4-2-u3-X57"},{"t":"상대에게 무조건 하라고 시키는 글","mis":"K4-2-u3-X57"}],"explanation":["제안은 의견을 내놓는 것이에요.","그 내용을 담았어요.","제안하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#4','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C27',1,'mc','auto','아정이의 글 4번 「그러면 복도가 붐비지 않아 안전하고……」는 짜임 가운데 무엇인가요?',ARRAY['K4-2-u3-X26','K4-2-u3-X29']::text[],false,'{"seq":4,"concept":"K4-2-u3-C27","difficulty":1,"kind":"mc","stem":"아정이의 글 4번 「그러면 복도가 붐비지 않아 안전하고……」는 짜임 가운데 무엇인가요?","options":[{"t":"제안하는 이유","correct":true},{"t":"문제 상황","mis":"K4-2-u3-X26"},{"t":"제안하는 내용","mis":"K4-2-u3-X26"},{"t":"제목","mis":"K4-2-u3-X29"}],"explanation":["「그러면」으로 시작해요.","좋아지는 점이에요.","제안하는 이유예요."],"asset":{"type":"passage","lines":["1 방과 후 담당 선생님, 안녕하세요? 저는 4학년 아정입니다.","2 요즘 방과 후 수업이 시작되기 전까지 기다릴 곳이 없어","   많은 친구가 복도 바닥에 앉아 있습니다. 지나가는 사람과 부딪치기도 합니다.","3 수업이 끝난 빈 교실 하나를 기다리는 곳으로 열어 주시면 좋겠습니다.","4 그러면 복도가 붐비지 않아 안전하고, 기다리는 동안 숙제나 책 읽기를 할 수 있습니다.","5 읽어 주셔서 고맙습니다."],"title":"아정이의 글 「방과 후 수업을 기다리는 교실을 열어 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#5','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C45',1,'ox','auto','「종소리가 울립니다.」는 「무엇이 + 어찌하다」 짜임의 문장이에요.',ARRAY['K4-2-u3-X47']::text[],false,'{"seq":5,"concept":"K4-2-u3-C45","difficulty":1,"kind":"ox","stem":"「종소리가 울립니다.」는 「무엇이 + 어찌하다」 짜임의 문장이에요.","answer":"O","reason_options":[{"t":"종소리가 「무엇이」이고 울린다는 움직임을 나타내기 때문에","correct":true},{"t":"「무엇이」 칸에는 사람만 오기 때문에","mis":"K4-2-u3-X47"}],"mis":"K4-2-u3-X47","explanation":["종소리는 「무엇」이에요.","울리다는 움직임이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#6','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C54',1,'mc','auto','「정리를 하다」가 한 낱말이 된 말을 넣어 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u3-X52','K4-2-u3-X51']::text[],false,'{"seq":6,"concept":"K4-2-u3-C54","difficulty":1,"kind":"mc","stem":"「정리를 하다」가 한 낱말이 된 말을 넣어 바르게 쓴 문장은 무엇인가요?","options":[{"t":"「놀이가 끝나면 놀잇감을 정리하고 들어가요.」","correct":true},{"t":"「놀이가 끝나면 놀잇감을 정리 하고 들어가요.」","mis":"K4-2-u3-X52"},{"t":"「놀이가 끝나면 놀잇감을 정 리하고 들어가요.」","mis":"K4-2-u3-X52"},{"t":"「놀이가 끝나면놀잇감을 정리하고들어가요.」","mis":"K4-2-u3-X51"}],"explanation":["정리하다는 한 낱말이에요.","붙여 써요.","첫째 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#7','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C57',1,'mc','auto','「신발을 벗다」의 반대말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X54']::text[],false,'{"seq":7,"concept":"K4-2-u3-C57","difficulty":1,"kind":"mc","stem":"「신발을 벗다」의 반대말로 알맞은 것은 무엇인가요?","options":[{"t":"신발을 신다","correct":true},{"t":"신발을 입다","mis":"K4-2-u3-X54"},{"t":"신발을 쓰다","mis":"K4-2-u3-X54"},{"t":"신발을 끼다","mis":"K4-2-u3-X54"}],"explanation":["신발을 발에 넣을 때를 떠올려요.","「신다」라고 해요.","무엇을 벗는지에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#8','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C4',1,'ox','auto','토의할 때 나와 다른 의견도 끝까지 들어요.',ARRAY['K4-2-u3-X03']::text[],false,'{"seq":8,"concept":"K4-2-u3-C4","difficulty":1,"kind":"ox","stem":"토의할 때 나와 다른 의견도 끝까지 들어요.","answer":"O","reason_options":[{"t":"끝까지 들어야 의견이 주제에 알맞은지 함께 따질 수 있기 때문에","correct":true},{"t":"목소리가 큰 의견을 따르면 되기 때문에","mis":"K4-2-u3-X03"}],"mis":"K4-2-u3-X03","explanation":["끼어들지 않아요.","끝까지 들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#9','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C13',2,'error','auto','토의에서 질문하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X14','K4-2-u3-X13','K4-2-u3-X12']::text[],false,'{"seq":9,"concept":"K4-2-u3-C13","difficulty":2,"kind":"error","stem":"토의에서 질문하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「궁금한 것이 없어도 질문 수를 채우려고 묻는 게 좋아.」","correct":true,"mis_target":"K4-2-u3-X14"},{"t":"친구 가 — 「의견대로 했을 때 생길 어려움을 물어.」","mis":"K4-2-u3-X13"},{"t":"친구 나 — 「친구 의견을 존중하는 말을 한 뒤 물어.」","mis":"K4-2-u3-X12"}],"explanation":["질문의 목적을 떠올려요.","수를 채우는 게 아니에요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#10','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C15',2,'mc','auto','효주네 모둠이 현관 바닥 문제를 주제로 고른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X09','K4-2-u3-X02']::text[],false,'{"seq":10,"concept":"K4-2-u3-C15","difficulty":2,"kind":"mc","stem":"효주네 모둠이 현관 바닥 문제를 주제로 고른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"모둠 친구 모두가 미끄러질 뻔한 친구를 보았고, 우리가 해결에 나설 수 있는 문제였기 때문에","correct":true},{"t":"가장 크고 어려운 문제였기 때문에","mis":"K4-2-u3-X09"},{"t":"효주 혼자만 겪은 일이었기 때문에","mis":"K4-2-u3-X02"},{"t":"답이 하나로 정해진 문제였기 때문에","mis":"K4-2-u3-X02"}],"explanation":["모두와 관련 있나요?","우리가 나설 수 있나요?","둘 다 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#11','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C21',2,'error','auto','모둠 의견을 결정하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X20','K4-2-u3-X19']::text[],false,'{"seq":11,"concept":"K4-2-u3-C21","difficulty":2,"kind":"error","stem":"모둠 의견을 결정하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「시간이 없으니 가위바위보로 빨리 정하자.」","correct":true,"mis_target":"K4-2-u3-X20"},{"t":"친구 나 — 「해결에 도움이 되는지 따져 보자.」","mis":"K4-2-u3-X19"},{"t":"친구 다 — 「우리가 실천할 수 있는지도 보자.」","mis":"K4-2-u3-X19"}],"explanation":["기준이 있나요?","가위바위보는 기준이 아니에요.","친구 가가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#12','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C28',2,'error','auto','막기만 하는 쪽지를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X28','K4-2-u3-X27']::text[],false,'{"seq":12,"concept":"K4-2-u3-C28","difficulty":2,"kind":"error","stem":"막기만 하는 쪽지를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「짧을수록 좋은 제안이니까 이유는 빼야 해.」","correct":true,"mis_target":"K4-2-u3-X28"},{"t":"친구 가 — 「어떻게 하면 좋을지 방법을 보태야 해.」","mis":"K4-2-u3-X27"},{"t":"친구 다 — 「그래야 하는 이유도 써야 해.」","mis":"K4-2-u3-X27"}],"explanation":["짧다고 좋은 제안이 아니에요.","방법과 이유가 필요해요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#13','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C36',2,'mc','auto','제안하는 이유를 쓸 때 가장 중요하게 생각할 것은 무엇인가요?',ARRAY['K4-2-u3-X36','K4-2-u3-X37','K4-2-u3-X28']::text[],false,'{"seq":13,"concept":"K4-2-u3-C36","difficulty":2,"kind":"mc","stem":"제안하는 이유를 쓸 때 가장 중요하게 생각할 것은 무엇인가요?","options":[{"t":"제안대로 하면 여러 사람에게 무엇이 좋아지는가","correct":true},{"t":"「왜냐하면」을 몇 번 넣었는가","mis":"K4-2-u3-X36"},{"t":"나 혼자 얼마나 불편했는가","mis":"K4-2-u3-X37"},{"t":"이유가 얼마나 짧은가","mis":"K4-2-u3-X28"}],"explanation":["읽는 사람이 바꾸고 싶어지려면?","좋아지는 점을 보여 줘요.","여러 사람에게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#14','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C35',2,'error','auto','여원이의 문제에 알맞은 제안을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X35','K4-2-u3-X34']::text[],false,'{"seq":14,"concept":"K4-2-u3-C35","difficulty":2,"kind":"error","stem":"여원이의 문제에 알맞은 제안을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「버스를 없애고 모두 걸어 다니게 해 달라고 하자.」","correct":true,"mis_target":"K4-2-u3-X35"},{"t":"친구 가 — 「눈높이에 안내판을 하나 더 달아 달라고 하자.」","mis":"K4-2-u3-X34"},{"t":"친구 나 — 「안내판 글자를 더 크게 바꿔 달라고 하자.」","mis":"K4-2-u3-X34"}],"explanation":["문제를 바로 푸나요?","버스를 없애면 문제가 커져요.","친구 다가 알맞지 않아요."],"asset":{"type":"passage","lines":["1 오늘 할머니와 도서관에 가려고 버스 정류장에 갔다.","2 버스 노선 안내판이 너무 높이 붙어 있고 글자가 작아서,","   할머니도 나도 탈 버스를 찾기 어려웠다.","3 옆에 계신 아저씨께 여쭈어 보고서야 버스를 탈 수 있었다.","4 다른 어린이나 어르신도 같은 불편을 겪지 않을까? 바꿀 방법은 없을까?"],"title":"여원의 일기 — 정류장에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#15','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C47',2,'ox','auto','「누가/무엇이」 칸에는 사람만 올 수 있어요.',ARRAY['K4-2-u3-X47']::text[],false,'{"seq":15,"concept":"K4-2-u3-C47","difficulty":2,"kind":"ox","stem":"「누가/무엇이」 칸에는 사람만 올 수 있어요.","answer":"X","reason_options":[{"t":"「비누 걸이가」, 「물이」처럼 물건도 「무엇이」 칸에 올 수 있기 때문에","correct":true},{"t":"문장에는 반드시 사람이 나와야 하기 때문에","mis":"K4-2-u3-X47"}],"mis":"K4-2-u3-X47","explanation":["「물이 차갑습니다」를 떠올려요.","물은 사람이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#16','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C38',2,'mc','auto','제안하는 글의 표현을 대하는 태도로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u3-X40']::text[],false,'{"seq":16,"concept":"K4-2-u3-C38","difficulty":2,"kind":"mc","stem":"제안하는 글의 표현을 대하는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"표현은 외우는 것이 아니라 문장에 어울리는 것을 골라 쓴다","correct":true},{"t":"「……합시다」만 외워서 모든 문장에 쓴다","mis":"K4-2-u3-X40"},{"t":"표현은 아무거나 써도 뜻이 같다","mis":"K4-2-u3-X40"},{"t":"제안 표현과 이유 표현은 같은 것이다","mis":"K4-2-u3-X40"}],"explanation":["외우지 않아요.","어울리는 것을 골라요.","문장에 맞게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#17','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C6',3,'ox','auto','토의와 제안하는 글은 둘 다 문제를 해결하는 방법이고, 토의로 정한 것을 글로 제안할 수도 있어요.',ARRAY['K4-2-u3-X04']::text[],false,'{"seq":17,"concept":"K4-2-u3-C6","difficulty":3,"kind":"ox","stem":"토의와 제안하는 글은 둘 다 문제를 해결하는 방법이고, 토의로 정한 것을 글로 제안할 수도 있어요.","answer":"O","reason_options":[{"t":"토의로 해결 방법을 찾고, 그 방법을 바꿀 수 있는 사람에게 글로 알릴 수 있기 때문에","correct":true},{"t":"문제가 생기면 언제나 글부터 써야 하기 때문에","mis":"K4-2-u3-X04"}],"mis":"K4-2-u3-X04","explanation":["효주네 발판을 떠올려요.","토의 뒤에 제안했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#18','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C51',3,'error','auto','서진이의 의견 ㉰ 「게시판을 없애자」를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X49']::text[],false,'{"seq":18,"concept":"K4-2-u3-C51","difficulty":3,"kind":"error","stem":"서진이의 의견 ㉰ 「게시판을 없애자」를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「작품이 떨어질 일이 없으니 가장 확실한 방법이야.」","correct":true,"mis_target":"K4-2-u3-X49"},{"t":"친구 나 — 「작품을 함께 보려는 게시판의 쓸모까지 없어져.」","mis":"K4-2-u3-X49"},{"t":"친구 다 — 「떨어지지 않게 하면서 함께 볼 방법을 찾아야 해.」","mis":"K4-2-u3-X49"}],"explanation":["게시판은 왜 있나요?","작품을 함께 보려고요.","친구 가가 알맞지 않아요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#19','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C43',3,'error','auto','선재의 이유를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X37','K4-2-u3-X38']::text[],false,'{"seq":19,"concept":"K4-2-u3-C43","difficulty":3,"kind":"error","stem":"선재의 이유를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「내가 좋아하는 비누 향기도 이유로 넣으면 더 좋아.」","correct":true,"mis_target":"K4-2-u3-X37"},{"t":"친구 가 — 「여쭈어 확인한 사실이라 믿을 수 있어.」","mis":"K4-2-u3-X38"},{"t":"친구 나 — 「세면대까지 가서 줄 서지 않아도 된다는 점도 좋아.」","mis":"K4-2-u3-X38"}],"explanation":["내 취향은 이유로 약해요.","여러 사람에게 좋아지는 점을 써요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#20','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C40',3,'error','auto','제안이 받아들여지지 않았을 때를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X41','K4-2-u3-X30']::text[],false,'{"seq":20,"concept":"K4-2-u3-C40","difficulty":3,"kind":"error","stem":"제안이 받아들여지지 않았을 때를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「받아들여지지 않았으니 제안하는 글은 쓸모없어.」","correct":true,"mis_target":"K4-2-u3-X41"},{"t":"친구 가 — 「답에 적힌 까닭을 살펴 제안을 고쳐 볼래.」","mis":"K4-2-u3-X30"},{"t":"친구 다 — 「다른 방법도 함께 찾아볼래.」","mis":"K4-2-u3-X30"}],"explanation":["받아들여지지 않을 수도 있어요.","그것도 해결 과정이에요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#21','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C42',3,'error','auto','제안하는 글의 문제를 고르는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u3-X43']::text[],false,'{"seq":21,"concept":"K4-2-u3-C42","difficulty":3,"kind":"error","stem":"제안하는 글의 문제를 고르는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「모든 사람이 겪는 일이면 날씨라도 가장 좋은 문제야.」","correct":true,"mis_target":"K4-2-u3-X43"},{"t":"친구 가 — 「많은 친구가 겪는 문제를 골라.」","mis":"K4-2-u3-X43"},{"t":"친구 나 — 「바꿀 수 있는 분께 제안할 수 있는지 봐.」","mis":"K4-2-u3-X43"}],"explanation":["날씨는 바꿀 수 없어요.","제안해도 바뀌지 않아요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#22','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C53',3,'mc','auto','우리 반에서 나온 제안 가운데 전교 학생 자치회 안건으로 가장 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u3-X50']::text[],false,'{"seq":22,"concept":"K4-2-u3-C53","difficulty":3,"kind":"mc","stem":"우리 반에서 나온 제안 가운데 전교 학생 자치회 안건으로 가장 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉯ 우리 반 교실 벽만 좋아하는 색으로 새로 칠하기","correct":true},{"t":"㉮ 응원 도구 나눔 상자 만들기","mis":"K4-2-u3-X50"},{"t":"㉰ 다 읽은 책을 동생 학년과 바꾸어 읽기","mis":"K4-2-u3-X50"},{"t":"㉮와 ㉰ 모두 알맞지 않다","mis":"K4-2-u3-X50"}],"explanation":["학교 모두와 관련 있나요?","㉯는 우리 반만의 일이에요.","㉯가 알맞지 않아요."],"asset":{"type":"passage","lines":["㉮ 응원 도구 나눔 상자 만들기","㉯ 우리 반 교실 벽만 좋아하는 색으로 새로 칠하기","㉰ 학년이 바뀔 때 다 읽은 책을 동생 학년과 바꾸어 읽기"],"title":"우리 반에서 나온 제안들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#23','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C12',4,'mc','auto','토의에서 질문을 가장 잘 이해한 친구의 말은 무엇인가요?',ARRAY['K4-2-u3-X14','K4-2-u3-X11','K4-2-u3-X13']::text[],false,'{"seq":23,"concept":"K4-2-u3-C12","difficulty":4,"kind":"mc","stem":"토의에서 질문을 가장 잘 이해한 친구의 말은 무엇인가요?","options":[{"t":"「질문은 친구를 이기려는 게 아니라, 존중하는 말로 결과·어려움·실천 방법을 물어 의견을 함께 다듬는 거야.」","correct":true},{"t":"「질문은 많이 할수록 토의를 잘한 거야.」","mis":"K4-2-u3-X14"},{"t":"「질문으로 친구가 의견을 포기하게 만들면 이긴 거야.」","mis":"K4-2-u3-X11"},{"t":"「「좋은 의견이에요」만 붙이면 무엇을 물어도 돼.」","mis":"K4-2-u3-X13"}],"explanation":["질문의 목적을 떠올려요.","함께 다듬어요.","존중하며 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#24','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C13',4,'essay','teacher','하윤이의 의견 「게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자」에 할 좋은 질문을 두 가지 쓰고, 각 질문이 결과 · 어려움 · 실천 방법 가운데 무엇을 묻는지 쓰세요. 좋은 질문의 조건도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u3-C13","difficulty":4,"kind":"essay","stem":"하윤이의 의견 「게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자」에 할 좋은 질문을 두 가지 쓰고, 각 질문이 결과 · 어려움 · 실천 방법 가운데 무엇을 묻는지 쓰세요. 좋은 질문의 조건도 쓰세요.","answer_guide":{"answer":"예: ① 「좋은 생각이야. 그런데 당번은 몇 명이, 언제부터 맡으면 좋을까?」 — 실천 방법을 묻는다. ② 「당번이 결석하는 날은 어떻게 하면 좋을까?」 — 어려움을 묻는다. 좋은 질문은 존중하는 말투로, 의견이 문제를 해결하는지 따지는 데 도움이 되는 것을 묻는다.","scoring_points":["좋은 질문 두 가지를 썼는가","각 질문이 무엇을 묻는지 밝혔는가","존중하는 말투와 문제를 따지는 내용, 두 조건을 썼는가"]},"explanation":["존중하며 물어요.","무엇을 묻는지 밝혀요.","말투와 내용 둘 다요."],"asset":{"type":"passage","lines":["주제 — 학급 게시판에 붙인 작품이 자꾸 떨어지는 문제를 어떻게 해결할까?","㉮ 준서 — 테이프 대신 작은 집게로 작품을 단단히 집자.","㉯ 하윤 — 게시판 당번이 아침마다 떨어진 작품을 살펴 다시 붙이자.","㉰ 서진 — 게시판을 없애고 작품을 각자 사물함에 넣어 두자.","㉱ 로운 — 작품을 붙일 때 「떨어지지 마라」 하고 마음속으로 빌자."],"title":"다온이네 모둠의 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u3_review_d#25','kor',4,2,'u3','','g4_2_kor_u3_review_d','unit_review','K4-2-u3-C57',4,'essay','teacher','「벗다」와 「뜨다」를 예로 들어 「한 낱말의 반대말은 하나뿐이다」가 왜 알맞지 않은지 쓰고, 「밥 먹다」와 「마음먹다」의 띄어쓰기가 다른 까닭도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u3-C57","difficulty":4,"kind":"essay","stem":"「벗다」와 「뜨다」를 예로 들어 「한 낱말의 반대말은 하나뿐이다」가 왜 알맞지 않은지 쓰고, 「밥 먹다」와 「마음먹다」의 띄어쓰기가 다른 까닭도 쓰세요.","answer_guide":{"answer":"예: 「옷을 벗다」의 반대말은 「입다」, 「장갑을 벗다」는 「끼다」, 「신발을 벗다」는 「신다」이다. 「눈을 뜨다」의 반대말은 「감다」, 「배가 뜨다」는 「가라앉다」이다. 이처럼 쓰임에 따라 반대말이 달라지므로 하나뿐인 것이 아니다. 「마음먹다」는 두 낱말이 만나 하나의 낱말이 되어 붙여 쓰고, 「밥 먹다」는 하나의 낱말이 아니라서 띄어 쓴다.","scoring_points":["「벗다」의 반대말을 둘 이상 들었는가","「뜨다」의 반대말을 둘 들었는가","「밥 먹다」와 「마음먹다」의 띄어쓰기가 다른 까닭을 썼는가"]},"explanation":["무엇을 벗나요?","무엇이 뜨나요?","한 낱말이 되었나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
